class CustomTypefaceSpan(private val typeface: android.graphics.Typeface) : android.text.style.MetricAffectingSpan() {
    override fun updateDrawState(ds: android.text.TextPaint) {
        applyCustomTypeface(ds, typeface)
    }
    override fun updateMeasureState(paint: android.text.TextPaint) {
        applyCustomTypeface(paint, typeface)
    }
    private fun applyCustomTypeface(paint: android.graphics.Paint, tf: android.graphics.Typeface) {
        val oldStyle = paint.typeface?.style ?: 0
        val want = oldStyle or tf.style
        paint.typeface = android.graphics.Typeface.create(tf, want)
    }
}

class CustomLineHeightSpan(private val targetLineHeight: Int) : android.text.style.LineHeightSpan {
    override fun chooseHeight(
        text: CharSequence?,
        start: Int,
        end: Int,
        spanstartv: Int,
        v: Int,
        fm: android.graphics.Paint.FontMetricsInt?
    ) {
        if (fm != null) {
            val currentHeight = fm.descent - fm.ascent
            if (currentHeight > 0) {
                val ratio = targetLineHeight.toFloat() / currentHeight
                fm.descent = (fm.descent * ratio).toInt()
                fm.ascent = (fm.ascent * ratio).toInt()
                fm.top = (fm.top * ratio).toInt()
                fm.bottom = (fm.bottom * ratio).toInt()
            }
        }
    }
}

fun buildSpannableString(
    text: String,
    spans: List<DocFormatSpan>,
    absoluteOffset: Int,
    baseTextSize: Float,
    baseTypeface: android.graphics.Typeface,
    density: Float = 1f
): android.text.SpannableString {
    val spannable = android.text.SpannableString(text)
    val chunkLength = text.length
    
    // Pass 1: paragraph styles (alignment and lineSpacing)
    val paraProps = mutableMapOf<String, MutableMap<String, String>>()
    
    spans.forEach { span ->
        val relStart = maxOf(0, span.start - absoluteOffset)
        val relEnd = minOf(chunkLength, span.end - absoluteOffset)
        if (relStart < relEnd) {
            when (span.type) {
                "alignment", "lineSpacing" -> {
                    val paraRangesInPage = getParagraphRangesInRange(text, relStart, relEnd.coerceAtLeast(relStart))
                    for (r in paraRangesInPage) {
                        val paraStart = r.first
                        val paraEnd = r.last + 1
                        if (paraStart >= 0 && paraEnd <= chunkLength && paraStart < paraEnd) {
                            val key = "$paraStart-$paraEnd"
                            paraProps.getOrPut(key) { mutableMapOf() }[span.type] = span.value
                        }
                    }
                }
            }
        }
    }
    
    for ((key, props) in paraProps) {
        val parts = key.split("-")
        if (parts.size < 2) continue
        val paraStart = parts[0].toIntOrNull() ?: continue
        val paraEnd = parts[1].toIntOrNull() ?: continue
        if (paraStart < 0 || paraEnd > chunkLength || paraStart >= paraEnd) continue
        
        val align = when (props["alignment"]) {
            "center" -> android.text.Layout.Alignment.ALIGN_CENTER
            "right" -> android.text.Layout.Alignment.ALIGN_OPPOSITE
            "justify" -> android.text.Layout.Alignment.ALIGN_NORMAL
            "left" -> android.text.Layout.Alignment.ALIGN_NORMAL
            else -> null
        }
        if (align != null) {
            spannable.setSpan(
                android.text.style.AlignmentSpan.Standard(align),
                paraStart,
                paraEnd,
                android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
            )
        }
        
        val lineHeightValue = props["lineSpacing"]?.toFloatOrNull()
        if (lineHeightValue != null) {
            val targetLineHeight = (24f * lineHeightValue * density).toInt()
            spannable.setSpan(
                CustomLineHeightSpan(targetLineHeight),
                paraStart,
                paraEnd,
                android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
            )
        }
    }
    
    // Pass 2: character styles
    spans.forEach { span ->
        val relStart = maxOf(0, span.start - absoluteOffset)
        val relEnd = minOf(chunkLength, span.end - absoluteOffset)
        if (relStart < relEnd) {
            val flags = android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
            when (span.type) {
                "bold" -> spannable.setSpan(android.text.style.StyleSpan(android.graphics.Typeface.BOLD), relStart, relEnd, flags)
                "italic" -> spannable.setSpan(android.text.style.StyleSpan(android.graphics.Typeface.ITALIC), relStart, relEnd, flags)
                "underline" -> spannable.setSpan(android.text.style.UnderlineSpan(), relStart, relEnd, flags)
                "strikethrough" -> spannable.setSpan(android.text.style.StrikethroughSpan(), relStart, relEnd, flags)
                "track_insert" -> {
                    spannable.setSpan(android.text.style.UnderlineSpan(), relStart, relEnd, flags)
                    spannable.setSpan(android.text.style.ForegroundColorSpan(0xFFC2410C.toInt()), relStart, relEnd, flags)
                    spannable.setSpan(android.text.style.StyleSpan(android.graphics.Typeface.BOLD), relStart, relEnd, flags)
                }
                "track_delete" -> {
                    spannable.setSpan(android.text.style.StrikethroughSpan(), relStart, relEnd, flags)
                    spannable.setSpan(android.text.style.ForegroundColorSpan(0xFFEF4444.toInt()), relStart, relEnd, flags)
                }
                "comment_highlight" -> {
                    spannable.setSpan(android.text.style.BackgroundColorSpan(0xFFFEF3C7.toInt()), relStart, relEnd, flags)
                    spannable.setSpan(android.text.style.ForegroundColorSpan(0xFF92400E.toInt()), relStart, relEnd, flags)
                }
                "color" -> try {
                    val cleanHex = if (span.value.startsWith("#")) span.value else "#${span.value}"
                    spannable.setSpan(android.text.style.ForegroundColorSpan(android.graphics.Color.parseColor(cleanHex)), relStart, relEnd, flags)
                } catch (e: Exception) {}
                "highlight" -> try {
                    val bgHex = if (span.value.isEmpty()) "#FDE047" else (if (span.value.startsWith("#")) span.value else "#${span.value}")
                    val parsedColor = android.graphics.Color.parseColor(bgHex)
                    val colorWithAlpha = (parsedColor and 0x00FFFFFF) or 0x73000000
                    spannable.setSpan(android.text.style.BackgroundColorSpan(colorWithAlpha), relStart, relEnd, flags)
                } catch (e: Exception) {
                    spannable.setSpan(android.text.style.BackgroundColorSpan(0x73FDE047.toInt()), relStart, relEnd, flags)
                }
                "subscript" -> spannable.setSpan(android.text.style.SubscriptSpan(), relStart, relEnd, flags)
                "superscript" -> spannable.setSpan(android.text.style.SuperscriptSpan(), relStart, relEnd, flags)
                "fontSize" -> {
                    val size = span.value.toFloatOrNull()
                    if (size != null) {
                        spannable.setSpan(android.text.style.AbsoluteSizeSpan((size * density).toInt(), false), relStart, relEnd, flags)
                    }
                }
                "fontFamily" -> {
                    val tf = when (span.value) {
                        "Arial", "Verdana", "Aptos", "Calibri" -> android.graphics.Typeface.SANS_SERIF
                        "Times New Roman", "Georgia" -> android.graphics.Typeface.SERIF
                        "Courier New" -> android.graphics.Typeface.MONOSPACE
                        else -> android.graphics.Typeface.DEFAULT
                    }
                    spannable.setSpan(CustomTypefaceSpan(tf), relStart, relEnd, flags)
                }
                "shading" -> try {
                    val parsedColor = android.graphics.Color.parseColor(if (span.value.startsWith("#")) span.value else "#${span.value}")
                    val colorWithAlpha = (parsedColor and 0x00FFFFFF) or 0x40000000
                    spannable.setSpan(android.text.style.BackgroundColorSpan(colorWithAlpha), relStart, relEnd, flags)
                } catch (e: Exception) {}
            }
        }
    }
    // Apply system emoji font to emoji characters to ensure they render on PDF Canvas
    try {
        val emojiTf = getEmojiTypeface()
        val textLength = text.length
        var i = 0
        while (i < textLength) {
            val codePoint = text.codePointAt(i)
            val charCount = Character.charCount(codePoint)
            if (isEmoji(codePoint)) {
                spannable.setSpan(
                    CustomTypefaceSpan(emojiTf),
                    i,
                    i + charCount,
                    android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
                )
            }
            i += charCount
        }
    } catch (e: Exception) {}
    return spannable
}

data class DocFormatSpan(var start: Int, var end: Int, val type: String, val value: String = "")

data class CopyFormattedData(
    val text: String,
    val spans: List<DocFormatSpan>,
    val sourceOffset: Int
)

data class DocTextStyle(
    val name: String,
    val fontSize: Int = 16,
    val isBold: Boolean = false,
    val isItalic: Boolean = false,
    val isUnderline: Boolean = false,
    val color: String? = null,
    val alignment: String? = null,
    val lineSpacing: Float? = null,
    val isDefault: Boolean = false
)

fun getDefaultTextStyles(): List<DocTextStyle> = listOf(
    DocTextStyle("Normal", fontSize = 16, isDefault = true),
    DocTextStyle("Title", fontSize = 24, isBold = true, color = "#1A1A1A", isDefault = true),
    DocTextStyle("Subtitle", fontSize = 18, isItalic = true, color = "#555555", isDefault = true),
    DocTextStyle("Heading 1", fontSize = 22, isBold = true, isDefault = true),
    DocTextStyle("Heading 2", fontSize = 20, isBold = true, isDefault = true),
    DocTextStyle("Heading 3", fontSize = 18, isBold = true, isDefault = true),
    DocTextStyle("Quote", fontSize = 16, isItalic = true, color = "#666666", isDefault = true)
)

fun applyStyleAttributes(docId: Int, style: DocTextStyle, start: Int, end: Int) {
    DocFormatRepository.removeSpanTypeRange(docId, "bold", start, end)
    if (style.isBold) DocFormatRepository.applySpan(docId, "bold", "", start, end)

    DocFormatRepository.removeSpanTypeRange(docId, "italic", start, end)
    if (style.isItalic) DocFormatRepository.applySpan(docId, "italic", "", start, end)

    DocFormatRepository.removeSpanTypeRange(docId, "underline", start, end)
    if (style.isUnderline) DocFormatRepository.applySpan(docId, "underline", "", start, end)

    DocFormatRepository.removeSpanTypeRange(docId, "color", start, end)
    if (style.color != null) DocFormatRepository.applySpan(docId, "color", style.color, start, end)

    DocFormatRepository.removeSpanTypeRange(docId, "alignment", start, end)
    if (style.alignment != null) DocFormatRepository.applySpan(docId, "alignment", style.alignment, start, end)

    DocFormatRepository.removeSpanTypeRange(docId, "lineSpacing", start, end)
    if (style.lineSpacing != null) DocFormatRepository.applySpan(docId, "lineSpacing", style.lineSpacing.toString(), start, end)
}

object DocFormatRepository {
    private val spans = mutableMapOf<Int, androidx.compose.runtime.snapshots.SnapshotStateList<DocFormatSpan>>()
    
    fun getSpans(docId: Int): androidx.compose.runtime.snapshots.SnapshotStateList<DocFormatSpan> {
        return spans.getOrPut(docId) { androidx.compose.runtime.mutableStateListOf() }
    }
    
    fun removeSpansRange(docId: Int, start: Int, end: Int) {
        val list = getSpans(docId)
        val toRemove = mutableListOf<DocFormatSpan>()
        val toAdd = mutableListOf<DocFormatSpan>()
        for (span in list) {
            if (span.start >= start && span.end <= end) {
                toRemove.add(span)
            } else if (span.start < start && span.end > end) {
                val oldEnd = span.end
                span.end = start
                toAdd.add(DocFormatSpan(end, oldEnd, span.type, span.value))
            } else if (span.start < start && span.end > start && span.end <= end) {
                span.end = start
            } else if (span.start >= start && span.start < end && span.end > end) {
                span.start = end
            }
        }
        list.removeAll(toRemove)
        list.addAll(toAdd)
    }
    
    fun hasSpan(docId: Int, type: String, start: Int, end: Int): Boolean {
        val list = getSpans(docId)
        return list.any { it.type == type && it.start <= start && it.end >= end }
    }
    
    fun removeSpanTypeRange(docId: Int, type: String, start: Int, end: Int) {
        val list = getSpans(docId)
        val toRemove = mutableListOf<DocFormatSpan>()
        val toAdd = mutableListOf<DocFormatSpan>()
        for (span in list) {
            if (span.type == type) {
                if (span.start >= start && span.end <= end) {
                    toRemove.add(span)
                } else if (span.start < start && span.end > end) {
                    val oldEnd = span.end
                    span.end = start
                    toAdd.add(DocFormatSpan(end, oldEnd, span.type, span.value))
                } else if (span.start < start && span.end > start && span.end <= end) {
                    span.end = start
                } else if (span.start >= start && span.start < end && span.end > end) {
                    span.start = end
                }
            }
        }
        list.removeAll(toRemove)
        list.addAll(toAdd)
    }
    
    fun applySpan(docId: Int, type: String, value: String, start: Int, end: Int) {
        val list = getSpans(docId)
        if (start >= end) return

        val isParagraphLevel = type == "alignment" || type == "lineSpacing"

        removeSpanTypeRange(docId, type, start, end)

        var newStart = start
        var newEnd = end

        val toRemove = mutableListOf<DocFormatSpan>()
        if (!isParagraphLevel) {
            for (span in list) {
                if (span.type == type && span.value == value) {
                    if (span.end == newStart) {
                        newStart = span.start
                        toRemove.add(span)
                    } else if (span.start == newEnd) {
                        newEnd = span.end
                        toRemove.add(span)
                    }
                }
            }
        }

        list.removeAll(toRemove)
        list.add(DocFormatSpan(newStart, newEnd, type, value))
    }
    
    fun shiftSpans(docId: Int, changeStart: Int, deleted: Int, inserted: Int) {
        val list = getSpans(docId)
        val diff = inserted - deleted
        if (diff == 0) return
        val iterator = list.iterator()
        while (iterator.hasNext()) {
            val span = iterator.next()
            if (span.start >= changeStart + deleted) {
                span.start += diff
                span.end += diff
            } else if (span.start >= changeStart && span.end <= changeStart + deleted) {
                iterator.remove()
            } else if (span.start < changeStart && span.end > changeStart + deleted) {
                span.end += diff
            } else if (span.end > changeStart) {
                span.end = maxOf(span.start, span.end + diff)
            }
        }
    }

    fun moveSpanRange(docId: Int, fromStart: Int, fromEnd: Int, toStart: Int) {
        val list = getSpans(docId)
        if (fromStart >= fromEnd) return
        val shift = toStart - fromStart
        val added = mutableListOf<DocFormatSpan>()
        val it = list.iterator()
        while (it.hasNext()) {
            val span = it.next()
            when {
                // entirely within moved range
                span.start >= fromStart && span.end <= fromEnd -> {
                    it.remove()
                    span.start += shift
                    span.end += shift
                    if (span.end > span.start) added.add(span)
                }
                // starts before, ends within moved range
                span.start < fromStart && span.end > fromStart && span.end <= fromEnd -> {
                    val oldEnd = span.end
                    span.end = fromStart
                    val newSpan = DocFormatSpan(toStart, toStart + (oldEnd - fromStart), span.type, span.value)
                    if (newSpan.end > newSpan.start) added.add(newSpan)
                }
                // starts within moved range, ends after
                span.start >= fromStart && span.start < fromEnd && span.end > fromEnd -> {
                    val oldStart = span.start
                    it.remove()
                    val newSpan = DocFormatSpan(toStart + (oldStart - fromStart), toStart + (fromEnd - fromStart), span.type, span.value)
                    if (newSpan.end > newSpan.start) added.add(newSpan)
                    span.start = fromEnd
                    span.end = fromEnd + (span.end - fromEnd)
                    added.add(span)
                }
                // starts before, ends after (covers entire range)
                span.start < fromStart && span.end > fromEnd -> {
                    val oldEnd = span.end
                    span.end = fromStart
                    val newSpan = DocFormatSpan(toStart, toStart + (fromEnd - fromStart), span.type, span.value)
                    if (newSpan.end > newSpan.start) added.add(newSpan)
                    val rightSpan = DocFormatSpan(fromEnd, oldEnd, span.type, span.value)
                    added.add(rightSpan)
                }
            }
        }
        list.addAll(added)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DocEditorScreen(
    viewModel: DocViewModel,
    modifier: Modifier = Modifier
) {
    val documents by viewModel.documents.collectAsStateWithLifecycle()
    val selectedDoc by viewModel.selectedDoc.collectAsStateWithLifecycle()
    val searchQuery by viewModel.searchQuery.collectAsStateWithLifecycle()
    val selectedFilter by viewModel.selectedTypeFilter.collectAsStateWithLifecycle()

    val draftTitle by viewModel.draftTitle.collectAsStateWithLifecycle()
    val draftContent by viewModel.draftContent.collectAsStateWithLifecycle()
    val pageFormat by viewModel.pageFormat.collectAsStateWithLifecycle()
    val customDimensions by viewModel.customPageDimensions.collectAsStateWithLifecycle()
    
    val isPlayingPresentation by viewModel.isPlayingPresentation.collectAsStateWithLifecycle()

    var showCreateDialog by remember { mutableStateOf(false) }
    var listExpanded by remember { mutableStateOf(false) } // For responsive left-right side panes
    var showFullAIChatPanel by remember { mutableStateOf(false) }

    BackHandler(enabled = isPlayingPresentation || listExpanded || selectedDoc != null || showFullAIChatPanel) {
        if (showFullAIChatPanel) {
            showFullAIChatPanel = false
        } else if (isPlayingPresentation) {
            viewModel.togglePresenterMode(false)
        } else if (listExpanded) {
            listExpanded = false
        } else if (selectedDoc != null) {
            viewModel.selectDocument(null)
        }
    }

    Scaffold(
        modifier = modifier.fillMaxSize(),
        contentWindowInsets = WindowInsets.safeDrawing
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
        ) {
            // Main adaptive workspace overlay
            Box(modifier = Modifier.fillMaxSize()) {
                // Workspace pane
                WorkspacePane(
                    selectedDoc = selectedDoc,
                    draftTitle = draftTitle,
                    draftContent = draftContent,
                    onTitleChange = { viewModel.updateDraftTitle(it) },
                    onContentChange = { viewModel.updateDraftContent(it) },
                    onCloseClick = { viewModel.selectDocument(null) },
                    onToggleSidebar = { listExpanded = !listExpanded },
                    isSidebarExpanded = listExpanded,
                    viewModel = viewModel,
                    pageFormat = pageFormat,
                    customDimensions = customDimensions,
                    onFABClick = { showCreateDialog = true },
                    onOpenAICopilot = { showFullAIChatPanel = true },
                    modifier = Modifier.fillMaxSize()
                )

                // Left Document explorer sidebar (Width is dynamic/collapsible overlay)
                AnimatedVisibility(
                    visible = listExpanded,
                    enter = slideInHorizontally() + fadeIn(),
                    exit = slideOutHorizontally() + fadeOut()
                ) {
                    Box(modifier = Modifier.fillMaxSize()) {
                        // Dismiss scrim
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(Color.Black.copy(alpha = 0.32f))
                                .clickable(
                                    interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                    indication = null
                                ) {
                                    listExpanded = false
                                }
                        )

                        // Sidebar itself
                        SidebarExplorer(
                            documents = documents,
                            selectedDoc = selectedDoc,
                            draftTitle = draftTitle,
                            onTitleChange = { viewModel.updateDraftTitle(it) },
                            searchQuery = searchQuery,
                            selectedFilter = selectedFilter,
                            onSearchChange = { viewModel.setSearchQuery(it) },
                            onFilterChange = { viewModel.setTypeFilter(it) },
                            onDocSelect = { viewModel.selectDocument(it) },
                            onDocDelete = { viewModel.deleteDocument(it) },
                            onDocFavoriteToggle = { viewModel.toggleFavorite(it) },
                            onCreateClick = { showCreateDialog = true },
                            viewModel = viewModel,
                            onCloseDrawer = { listExpanded = false },
                            modifier = Modifier
                                .fillMaxWidth(0.7f)
                                .widthIn(min = 240.dp, max = 380.dp)
                                .fillMaxHeight()
                                .clip(RoundedCornerShape(topStart = 0.dp, bottomStart = 0.dp, topEnd = 24.dp, bottomEnd = 24.dp))
                                .background(Color.White)
                                .border(
                                    width = 1.dp,
                                    color = Color(0xFFECECEC),
                                    shape = RoundedCornerShape(topStart = 0.dp, bottomStart = 0.dp, topEnd = 24.dp, bottomEnd = 24.dp)
                                )
                                .clickable(
                                    interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                    indication = null
                                ) {
                                    // Eat clicks to prevent dismiss on clicking sidebar inside
                                }
                        )
                    }
                }
            }

            // Dialog for creating a new document template
            if (showCreateDialog) {
                CreateDocumentDialog(
                    onDismiss = { showCreateDialog = false },
                    onConfirm = { title, type ->
                        viewModel.createNewDocument(title, type)
                        showCreateDialog = false
                    }
                )
            }

            // Full-screen presentation mode overlay
            if (isPlayingPresentation && selectedDoc?.type == "slide") {
                FullscreenPresentationView(
                    viewModel = viewModel,
                    onExit = { viewModel.togglePresenterMode(false) }
                )
            }

            if (showFullAIChatPanel) {
                val context = LocalContext.current
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        // Header matching Ribbon / modern styling
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFF4F46E5))
                                .padding(horizontal = 16.dp, vertical = 12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(
                                    imageVector = Icons.Default.Face,
                                    contentDescription = null,
                                    tint = Color.White,
                                    modifier = Modifier.size(24.dp)
                                )
                                Spacer(modifier = Modifier.width(12.dp))
                                Text(
                                    text = "Mobius AI Copilot",
                                    style = MaterialTheme.typography.titleMedium.copy(color = Color.White, fontWeight = FontWeight.SemiBold)
                                )
                            }
                            IconButton(onClick = { showFullAIChatPanel = false }) {
                                Icon(
                                    imageVector = Icons.Default.Close,
                                    contentDescription = "Close Panel",
                                    tint = Color.White
                                )
                            }
                        }
                        
                        // Chat Panel
                        AIChatPanel(
                            onClose = { showFullAIChatPanel = false },
                            viewModel = viewModel,
                            modifier = Modifier.fillMaxSize().weight(1f),
                            onNavigateToSettings = {
                                viewModel.changeActiveTab("settings")
                                viewModel.selectDocument(null)
                                showFullAIChatPanel = false
                            },
                            onNavigate = { tab ->
                                viewModel.changeActiveTab(tab)
                                showFullAIChatPanel = false
                            },
                            onChangeSetting = { setting, value ->
                                val sp = context.getSharedPreferences("ai_agent_prefs", Context.MODE_PRIVATE)
                                val edit = sp.edit()
                                when (setting) {
                                    "user_email" -> edit.putString("user_email_key", value)
                                    "ai_preferences" -> edit.putString("ai_preferences_key", value)
                                    "default_ai_model" -> edit.putString("default_ai_model_key", value)
                                    "ai_response_style" -> edit.putString("ai_response_style_key", value)
                                    "appearance" -> edit.putString("appearance_key", value)
                                    "language" -> edit.putString("language_key", value)
                                    "security_2fa" -> edit.putBoolean("security_2fa_key", value.toBoolean())
                                    "ai_provider" -> edit.putString("ai_provider", value)
                                }
                                edit.apply()
                                Toast.makeText(context, "Setting updated: $setting to $value", Toast.LENGTH_SHORT).show()
                            },
                            showToast = { Toast.makeText(context, it, Toast.LENGTH_SHORT).show() }
                        )
                    }
                }
            }
        }
    }
}

private fun getDirectorySize(file: java.io.File): Long {
    if (!file.exists()) return 0L
    if (file.isFile) return file.length()
    var size = 0L
    val children = file.listFiles()
    if (children != null) {
        for (child in children) {
            size += getDirectorySize(child)
        }
    }
    return size
}

private fun getTotalDiskStorage(): Long {
    return try {
        val path = android.os.Environment.getExternalStorageDirectory().path
        val stat = android.os.StatFs(path)
        stat.totalBytes
    } catch (e: Exception) {
        128L * 1024 * 1024 * 1024 // Fallback to 128 GB
    }
}

private fun getAppStorageUsed(context: android.content.Context): Long {
    var totalSize = 0L
    try {
        val downloadsDir = android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS)
        val jcDocsDownloadDir = java.io.File(downloadsDir, "JCdocs")
        if (jcDocsDownloadDir.exists()) {
            totalSize += getDirectorySize(jcDocsDownloadDir)
        }
    } catch (e: Exception) {
        e.printStackTrace()
    }
    return totalSize
}

private fun formatStorageSize(bytes: Long): String {
    val kb = 1024.0
    val mb = kb * 1024
    val gb = mb * 1024
    return when {
        bytes >= gb -> String.format("%.1f GB", bytes / gb)
        bytes >= mb -> String.format("%.1f MB", bytes / mb)
        bytes >= kb -> String.format("%.1f KB", bytes / kb)
        else -> "$bytes B"
    }
}

@Composable
fun SidebarExplorer(
    documents: List<DocEntity>,
    selectedDoc: DocEntity?,
    draftTitle: String,
    onTitleChange: (String) -> Unit,
    searchQuery: String,
    selectedFilter: String,
    onSearchChange: (String) -> Unit,
    onFilterChange: (String) -> Unit,
    onDocSelect: (DocEntity) -> Unit,
    onDocDelete: (DocEntity) -> Unit,
    onDocFavoriteToggle: (DocEntity) -> Unit,
    onCreateClick: () -> Unit,
    viewModel: DocViewModel,
    onCloseDrawer: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val scope = rememberCoroutineScope()

    var hasStoragePermission by remember {
        mutableStateOf(
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_MEDIA_IMAGES) == android.content.pm.PackageManager.PERMISSION_GRANTED ||
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_MEDIA_VIDEO) == android.content.pm.PackageManager.PERMISSION_GRANTED
            } else {
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_EXTERNAL_STORAGE) == android.content.pm.PackageManager.PERMISSION_GRANTED
            }
        )
    }

    val storagePermissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestMultiplePermissions()
    ) { permissionsMap ->
        val readGranted = permissionsMap[android.Manifest.permission.READ_EXTERNAL_STORAGE] ?: false
        val writeGranted = permissionsMap[android.Manifest.permission.WRITE_EXTERNAL_STORAGE] ?: false
        val imagesGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_IMAGES] ?: false
        val videosGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_VIDEO] ?: false
        val audioGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_AUDIO] ?: false

        val isGranted = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
            imagesGranted || videosGranted || audioGranted
        } else {
            readGranted || writeGranted
        }
        hasStoragePermission = isGranted
        if (isGranted) {
            Toast.makeText(context, "Storage access granted! Resuming document import...", Toast.LENGTH_SHORT).show()
        } else {
            Toast.makeText(context, "Storage permission is required to import documents.", Toast.LENGTH_LONG).show()
        }
    }

    val importLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let { fileUri ->
            scope.launch(kotlinx.coroutines.Dispatchers.IO) {
                try {
                    val contentResolver = context.contentResolver
                    var fileName = ""
                    try {
                        contentResolver.query(fileUri, null, null, null, null)?.use { cursor ->
                            val nameId = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                            if (nameId != -1 && cursor.moveToFirst()) {
                                fileName = cursor.getString(nameId)
                            }
                        }
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }
                    if (fileName.isEmpty()) {
                        fileName = fileUri.lastPathSegment ?: "Imported Document"
                    }

                    val isPdf = fileName.lowercase().endsWith(".pdf") || contentResolver.getType(fileUri) == "application/pdf"
                    val isDocx = fileName.lowercase().endsWith(".docx") || contentResolver.getType(fileUri) == "application/vnd.openxmlformats-officedocument.wordprocessingml.document"

                    val cleanedTitle = fileName.substringBeforeLast(".")

                    if (isPdf) {
                        try {
                            val pdfFile = java.io.File(context.getExternalFilesDir("backend_data") ?: context.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                            contentResolver.openInputStream(fileUri)?.use { inputStream ->
                                pdfFile.outputStream().use { output ->
                                    inputStream.copyTo(output)
                                }
                            }
                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                viewModel.createNewDocument(
                                    title = cleanedTitle,
                                    type = "pdf",
                                    initialContent = pdfFile.absolutePath
                                )
                                Toast.makeText(context, "Successfully imported PDF $fileName", Toast.LENGTH_SHORT).show()
                            }
                        } catch (e: Exception) {
                            e.printStackTrace()
                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                Toast.makeText(context, "Failed to save PDF: ${e.message}", Toast.LENGTH_SHORT).show()
                            }
                        }
                    } else {
                        contentResolver.openInputStream(fileUri)?.use { inputStream ->
                            val textContent = if (isDocx) {
                                DocumentImportExportHelper.parseDocxText(inputStream)
                            } else {
                                val bytes = inputStream.readBytes()
                                val isPdfBytes = bytes.size > 4 && 
                                    bytes[0] == '%'.code.toByte() && 
                                    bytes[1] == 'P'.code.toByte() && 
                                    bytes[2] == 'D'.code.toByte() && 
                                    bytes[3] == 'F'.code.toByte()
                                if (isPdfBytes) {
                                    val pdfFile = java.io.File(context.getExternalFilesDir("backend_data") ?: context.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                                    pdfFile.writeBytes(bytes)
                                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                        viewModel.createNewDocument(
                                            title = cleanedTitle,
                                            type = "pdf",
                                            initialContent = pdfFile.absolutePath
                                        )
                                        Toast.makeText(context, "Successfully imported PDF $fileName", Toast.LENGTH_SHORT).show()
                                    }
                                    return@use
                                } else {
                                    try {
                                        DocumentImportExportHelper.parseDocxText(java.io.ByteArrayInputStream(bytes))
                                    } catch (e: Exception) {
                                        DocumentImportExportHelper.prePaginateText(String(bytes, Charsets.UTF_8))
                                    }
                                }
                            }

                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                if (textContent != null) {
                                    viewModel.createNewDocument(
                                        title = cleanedTitle,
                                        type = "word",
                                        initialContent = textContent
                                    )
                                    Toast.makeText(context, "Successfully imported $fileName", Toast.LENGTH_SHORT).show()
                                } else {
                                    Toast.makeText(context, "Could not extract text content from $fileName", Toast.LENGTH_SHORT).show()
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                        Toast.makeText(context, "Failed to import file: ${e.message}", Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
    }

    val sharedPreferences = remember { context.getSharedPreferences("ai_agent_prefs", Context.MODE_PRIVATE) }
    var username by remember { mutableStateOf(sharedPreferences.getString("username_key", "Chandan Kumar") ?: "Chandan Kumar") }
    var userRole by remember { mutableStateOf(sharedPreferences.getString("user_role_key", "Lead Editor") ?: "Lead Editor") }

    DisposableEffect(sharedPreferences) {
        val listener = android.content.SharedPreferences.OnSharedPreferenceChangeListener { prefs, key ->
            if (key == "username_key") {
                username = prefs.getString("username_key", "Chandan Kumar") ?: "Chandan Kumar"
            } else if (key == "user_role_key") {
                userRole = prefs.getString("user_role_key", "Lead Editor") ?: "Lead Editor"
            }
        }
        sharedPreferences.registerOnSharedPreferenceChangeListener(listener)
        onDispose {
            sharedPreferences.unregisterOnSharedPreferenceChangeListener(listener)
        }
    }

    val avatarInitials = remember(username) {
        val nameWords = username.trim().split("\\s+".toRegex()).filter { it.isNotEmpty() }
        val first = nameWords.firstOrNull()?.take(1)?.uppercase() ?: "S"
        val last = if (nameWords.size > 1) nameWords[1].take(1).uppercase() else ""
        if (last.isNotEmpty()) first + last else if (username.length > 1) username.take(2).uppercase() else first
    }

    var activeAccessTab by remember { mutableStateOf("Recent") }

    val filteredAccessDocs = remember(documents, activeAccessTab, searchQuery) {
        val sortedDocs = documents.sortedByDescending { it.updatedAt }
        val baseFiltered = when (activeAccessTab) {
            "Favorites" -> sortedDocs.filter { it.isFavorite }
            "Shared" -> sortedDocs.filter { (it.id % 2).toInt() == 1 }
            "Offline" -> sortedDocs
            "Trash" -> emptyList()
            "Activity" -> sortedDocs.take(3)
            "Recent" -> sortedDocs
            "Docs" -> sortedDocs.filter { it.type.equals("word", ignoreCase = true) }
            "Excel" -> sortedDocs.filter { it.type.equals("sheet", ignoreCase = true) }
            "Slides" -> sortedDocs.filter { it.type.equals("slide", ignoreCase = true) }
            "PDF" -> sortedDocs.filter { it.type.equals("pdf", ignoreCase = true) }
            else -> sortedDocs
        }
        if (searchQuery.isBlank()) {
            baseFiltered
        } else {
            baseFiltered.filter { it.title.contains(searchQuery, ignoreCase = true) }
        }
    }

    Column(
        modifier = modifier
            .fillMaxHeight()
            .background(Color.White)
            .statusBarsPadding()
            .navigationBarsPadding(),
        verticalArrangement = Arrangement.SpaceBetween
    ) {
        // --- 1. Top Section (Scrollable) ---
        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
        ) {
            // Profile block
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(CircleShape)
                        .background(Color(0xFFE2E8F0)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Default.Person,
                        contentDescription = "Profile Avatar",
                        tint = Color(0xFF64748B),
                        modifier = Modifier.size(20.dp)
                    )
                }
                Spacer(modifier = Modifier.width(10.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = username,
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = Color(0xFF0F172A),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Text(
                        text = userRole,
                        fontSize = 12.sp,
                        color = Color(0xFF64748B),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                Box(
                    modifier = Modifier
                        .size(32.dp)
                        .clickable {
                            Toast.makeText(context, "No new notifications", Toast.LENGTH_SHORT).show()
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Box {
                        Icon(
                            imageVector = Icons.Outlined.Notifications,
                            contentDescription = "Notifications",
                            tint = Color(0xFF0F172A),
                            modifier = Modifier.size(20.dp)
                        )
                        Box(
                            modifier = Modifier
                                .size(6.dp)
                                .clip(CircleShape)
                                .background(Color(0xFF8B5CF6))
                                .align(Alignment.TopEnd)
                        )
                    }
                }
            }

            // Search block
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 4.dp)
                    .height(42.dp)
                    .clip(RoundedCornerShape(10.dp))
                    .background(Color(0xFFF8FAFC))
                    .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                    .padding(horizontal = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Outlined.Search,
                    contentDescription = "Search",
                    tint = Color(0xFF64748B),
                    modifier = Modifier.size(18.dp)
                )
                Spacer(modifier = Modifier.width(8.dp))
                BasicTextField(
                    value = searchQuery,
                    onValueChange = onSearchChange,
                    textStyle = androidx.compose.ui.text.TextStyle(
                        fontSize = 13.sp,
                        color = Color(0xFF0F172A)
                    ),
                    singleLine = true,
                    modifier = Modifier
                        .weight(1f)
                        .testTag("file_search_bar"),
                    decorationBox = { innerTextField ->
                        if (searchQuery.isEmpty()) {
                            Text(
                                text = "Search office sheets & files",
                                fontSize = 12.sp,
                                color = Color(0xFF94A3B8),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                        innerTextField()
                    }
                )
                Spacer(modifier = Modifier.width(8.dp))
                Icon(
                    imageVector = Icons.Outlined.Tune,
                    contentDescription = "Tune",
                    tint = Color(0xFF64748B),
                    modifier = Modifier
                        .size(18.dp)
                        .clickable {
                            viewModel.changeActiveTab("settings")
                            onCloseDrawer()
                        }
                )
            }

            // Export & Import side-by-side cards
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                // Export Card
                ExportButton(
                    draftContent = "",
                    viewModel = viewModel,
                    style = "sidebar_card",
                    modifier = Modifier.weight(1f)
                )

                // Import Card
                Card(
                    modifier = Modifier
                        .weight(1f)
                        .clickable {
                            if (hasStoragePermission) {
                                importLauncher.launch(arrayOf("*/*"))
                            } else {
                                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                                    storagePermissionLauncher.launch(
                                        arrayOf(
                                            android.Manifest.permission.READ_MEDIA_IMAGES,
                                            android.Manifest.permission.READ_MEDIA_VIDEO
                                        )
                                    )
                                } else {
                                    storagePermissionLauncher.launch(
                                        arrayOf(
                                            android.Manifest.permission.READ_EXTERNAL_STORAGE,
                                            android.Manifest.permission.WRITE_EXTERNAL_STORAGE
                                        )
                                    )
                                }
                            }
                        },
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier
                            .padding(8.dp)
                            .fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(28.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFEFF6FF)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Outlined.FileDownload,
                                contentDescription = "Import icon",
                                tint = Color(0xFF2563EB),
                                modifier = Modifier.size(14.dp)
                            )
                        }
                        Spacer(modifier = Modifier.width(6.dp))
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = "Import",
                                fontWeight = FontWeight.Bold,
                                fontSize = 11.sp,
                                color = Color(0xFF0F172A),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            Text(
                                text = "Import office sheets",
                                fontSize = 8.sp,
                                color = Color(0xFF64748B),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                        Icon(
                            imageVector = Icons.Outlined.ChevronRight,
                            contentDescription = null,
                            tint = Color(0xFF94A3B8),
                            modifier = Modifier.size(10.dp)
                        )
                    }
                }
            }

            // Filters row
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 6.dp)
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                val filterTabs = listOf(
                    "Recent",
                    "Docs",
                    "Excel",
                    "Slides",
                    "PDF"
                )

                filterTabs.forEach { tab ->
                    val isSelected = activeAccessTab == tab
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (isSelected) Color(0xFFF5F3FF) else Color.White)
                            .border(
                                width = 1.dp,
                                color = if (isSelected) Color(0xFF8B5CF6) else Color(0xFFE2E8F0),
                                shape = RoundedCornerShape(8.dp)
                            )
                            .clickable {
                                activeAccessTab = tab
                            }
                            .padding(horizontal = 12.dp, vertical = 6.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = tab,
                            fontSize = 11.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                            color = if (isSelected) Color(0xFF8B5CF6) else Color(0xFF475569),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            }

            // Recent Files Header row
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Recent Files",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = Color(0xFF0F172A),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.clickable {
                        activeAccessTab = "Recent"
                    }
                ) {
                    Text(
                        text = "View all",
                        fontSize = 11.sp,
                        color = Color(0xFF8B5CF6),
                        fontWeight = FontWeight.SemiBold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Spacer(modifier = Modifier.width(2.dp))
                    Icon(
                        imageVector = Icons.Outlined.ChevronRight,
                        contentDescription = "View all",
                        tint = Color(0xFF8B5CF6),
                        modifier = Modifier.size(12.dp)
                    )
                }
            }

            // List of Documents
            if (filteredAccessDocs.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 16.dp, horizontal = 16.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "No files found",
                            fontSize = 11.sp,
                            color = Color.Gray,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            } else {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 6.dp)
                ) {
                    filteredAccessDocs.forEach { doc ->
                        val isSelected = selectedDoc?.id == doc.id
                        
                        val extension = when (doc.type) {
                            "word" -> ".docx"
                            "sheet" -> ".xlsx"
                            "slide" -> ".pptx"
                            "pdf" -> ".pdf"
                            else -> ""
                        }
                        val displayTitle = if (doc.title.endsWith(extension, ignoreCase = true)) {
                            doc.title
                        } else {
                            "${doc.title}$extension"
                        }
                        
                        val typeLabel = when (doc.type) {
                            "word" -> "Docs"
                            "sheet" -> "Excel"
                            "slide" -> "Slides"
                            "pdf" -> "PDF"
                            else -> "File"
                        }
                        
                        val calculatedSize = remember(doc) {
                            val baseKb = 12 + (doc.content.length / 100) + (doc.id * 17) % 2500
                            if (baseKb > 1024) {
                                String.format("%.1f MB", baseKb / 1024.0)
                            } else {
                                "$baseKb KB"
                            }
                        }
                        
                        val timeLabel = remember(doc.updatedAt) {
                            val diff = System.currentTimeMillis() - doc.updatedAt
                            when {
                                diff < 60 * 1000 -> "Just now"
                                diff < 60 * 60 * 1000 -> "${diff / (60 * 1000)} mins ago"
                                diff < 24 * 60 * 60 * 1000 -> "${diff / (60 * 60 * 1000)} hours ago"
                                diff < 2 * 24 * 60 * 60 * 1000 -> "Yesterday"
                                else -> "${diff / (24 * 60 * 60 * 1000)} days ago"
                            }
                        }

                        val iconColor = when (doc.type) {
                            "word" -> Color(0xFF2563EB)
                            "sheet" -> Color(0xFF10B981)
                            "pdf" -> Color(0xFFEF4444)
                            else -> Color(0xFFF59E0B)
                        }

                        val docIcon = when (doc.type) {
                            "word" -> Icons.Outlined.Description
                            "sheet" -> Icons.Outlined.TableChart
                            "pdf" -> Icons.Outlined.PictureAsPdf
                            else -> Icons.Outlined.Slideshow
                        }

                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 3.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            border = BorderStroke(1.dp, Color(0xFFF1F5F9)),
                            shape = RoundedCornerShape(10.dp)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(if (isSelected) Color(0xFFF5F3FF) else Color.Transparent)
                                    .clickable {
                                        onDocSelect(doc)
                                        onCloseDrawer()
                                    }
                                    .padding(horizontal = 8.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(32.dp)
                                        .clip(RoundedCornerShape(6.dp))
                                        .background(Color(0xFFF8FAFC))
                                        .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(6.dp)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = docIcon,
                                        contentDescription = doc.type,
                                        tint = iconColor,
                                        modifier = Modifier.size(18.dp)
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = displayTitle,
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF0F172A),
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    Text(
                                        text = "$typeLabel • $calculatedSize",
                                        fontSize = 10.sp,
                                        color = Color(0xFF64748B),
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                }
                                Spacer(modifier = Modifier.width(4.dp))
                                
                                Text(
                                    text = timeLabel,
                                    fontSize = 10.sp,
                                    color = Color(0xFF94A3B8),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                                Spacer(modifier = Modifier.width(2.dp))
                                
                                var menuExpanded by remember { mutableStateOf(false) }
                                Box {
                                    IconButton(
                                        onClick = { menuExpanded = true },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.MoreVert,
                                            contentDescription = "Options",
                                            tint = Color(0xFF64748B),
                                            modifier = Modifier.size(14.dp)
                                        )
                                    }
                                    
                                    DropdownMenu(
                                        expanded = menuExpanded,
                                        onDismissRequest = { menuExpanded = false }
                                    ) {
                                        DropdownMenuItem(
                                            text = { Text("Favorite") },
                                            onClick = {
                                                onDocFavoriteToggle(doc)
                                                menuExpanded = false
                                            },
                                            leadingIcon = {
                                                Icon(
                                                    imageVector = if (doc.isFavorite) Icons.Outlined.Star else Icons.Outlined.StarBorder,
                                                    contentDescription = "Favorite",
                                                    tint = if (doc.isFavorite) Color(0xFFFF9F00) else Color.Gray,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        )
                                        DropdownMenuItem(
                                            text = { Text("Delete", color = Color.Red) },
                                            onClick = {
                                                onDocDelete(doc)
                                                menuExpanded = false
                                            },
                                            leadingIcon = {
                                                Icon(
                                                    imageVector = Icons.Outlined.Delete,
                                                    contentDescription = "Delete",
                                                    tint = Color.Red,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Storage progress card
        val totalDiskStorage = getTotalDiskStorage()
        val appStorageUsed = remember(documents) { getAppStorageUsed(context) }
        val progressFraction = if (appStorageUsed > 0 && totalDiskStorage > 0) {
            (appStorageUsed.toFloat() / totalDiskStorage).coerceIn(0.0001f..1.0f)
        } else {
            0.0f
        }
        val pctFormatted = if (totalDiskStorage > 0) {
            val percentage = (appStorageUsed.toDouble() / totalDiskStorage.toDouble()) * 100.0
            if (percentage in 0.0..0.01 && appStorageUsed > 0) "<0.01%" else String.format("%.2f%%", percentage)
        } else {
            "0.00%"
        }
        val pctText = if (appStorageUsed > 0) pctFormatted else "0%"

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 4.dp)
                .clip(RoundedCornerShape(12.dp))
                .background(Color.White)
                .border(1.dp, Color(0xFFF1F5F9), RoundedCornerShape(12.dp))
                .padding(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier
                    .size(32.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(Color(0xFFF5F3FF)),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Outlined.Folder,
                    contentDescription = "Storage icon",
                    tint = Color(0xFF8B5CF6),
                    modifier = Modifier.size(18.dp)
                )
            }
            Spacer(modifier = Modifier.width(8.dp))
            
            Row(
                modifier = Modifier.weight(1f),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = "Storage",
                        fontWeight = FontWeight.Bold,
                        fontSize = 12.sp,
                        color = Color(0xFF0F172A),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Text(
                        text = "${formatStorageSize(appStorageUsed)} of ${formatStorageSize(totalDiskStorage)} used",
                        fontSize = 10.sp,
                        color = Color(0xFF64748B),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                Spacer(modifier = Modifier.width(4.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .width(45.dp)
                            .height(4.dp)
                            .clip(CircleShape)
                            .background(Color(0xFFF1F5F9))
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxHeight()
                                .fillMaxWidth(progressFraction)
                                .background(Color(0xFF8B5CF6))
                        )
                    }
                    
                    Text(
                        text = pctText,
                        fontWeight = FontWeight.Bold,
                        fontSize = 10.sp,
                        color = Color(0xFF8B5CF6),
                        style = androidx.compose.ui.text.TextStyle(
                            textDecoration = androidx.compose.ui.text.style.TextDecoration.Underline
                        ),
                        maxLines = 1,
                        overflow = TextOverflow.Clip
                    )
                }
            }
            
            Spacer(modifier = Modifier.width(4.dp))
            Icon(
                imageVector = Icons.Outlined.ChevronRight,
                contentDescription = "Go to storage details",
                tint = Color(0xFF64748B),
                modifier = Modifier.size(14.dp)
            )
        }

        // --- 2. Bottom Navigation Bar (Sticky at bottom, outside the scroll block) ---
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            elevation = CardDefaults.cardElevation(defaultElevation = 6.dp),
            shape = RoundedCornerShape(0.dp)
        ) {
            Column {
                Divider(
                    modifier = Modifier.fillMaxWidth(),
                    color = Color(0xFFF1F5F9),
                    thickness = 0.5.dp
                )

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                    horizontalArrangement = Arrangement.SpaceEvenly,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val activeTabState by viewModel.activeTab.collectAsStateWithLifecycle()

                    // 1. Files Tab
                    val isFilesActive = activeAccessTab != "Favorites" && activeTabState != "settings"
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .clickable {
                                activeAccessTab = "Recent"
                                if (activeTabState == "settings") {
                                    viewModel.changeActiveTab("home")
                                }
                            },
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Folder,
                            contentDescription = "Files",
                            tint = if (isFilesActive) Color(0xFF8B5CF6) else Color(0xFF94A3B8),
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = "Files",
                            fontSize = 10.sp,
                            fontWeight = if (isFilesActive) FontWeight.Bold else FontWeight.Medium,
                            color = if (isFilesActive) Color(0xFF8B5CF6) else Color(0xFF94A3B8),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    // 2. Starred Tab
                    val isStarredActive = activeAccessTab == "Favorites" && activeTabState != "settings"
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .clickable {
                                activeAccessTab = "Favorites"
                                if (activeTabState == "settings") {
                                    viewModel.changeActiveTab("home")
                                }
                            },
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = if (isStarredActive) Icons.Outlined.Star else Icons.Outlined.StarBorder,
                            contentDescription = "Starred",
                            tint = if (isStarredActive) Color(0xFFFF9F00) else Color(0xFF94A3B8),
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = "Starred",
                            fontSize = 10.sp,
                            fontWeight = if (isStarredActive) FontWeight.Bold else FontWeight.Medium,
                            color = if (isStarredActive) Color(0xFFFF9F00) else Color(0xFF94A3B8),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    // 3. Settings Tab
                    val isSettingsActive = activeTabState == "settings"
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .clickable {
                                viewModel.changeActiveTab("settings")
                                onCloseDrawer()
                            },
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Settings,
                            contentDescription = "Settings",
                            tint = if (isSettingsActive) Color(0xFF8B5CF6) else Color(0xFF94A3B8),
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = "Settings",
                            fontSize = 10.sp,
                            fontWeight = if (isSettingsActive) FontWeight.Bold else FontWeight.Medium,
                            color = if (isSettingsActive) Color(0xFF8B5CF6) else Color(0xFF94A3B8),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            }
        }
    }
}

data class FilterItem(val id: String, val displayName: String, val icon: ImageVector)

@Composable
fun DocumentTile(
    doc: DocEntity,
    isSelected: Boolean,
    onClick: () -> Unit,
    onDelete: () -> Unit,
    onFavoriteToggle: () -> Unit,
    modifier: Modifier = Modifier
) {
    val typeColor = when (doc.type) {
        "word" -> DocWordColor
        "sheet" -> DocSheetColor
        "slide" -> DocSlideColor
        else -> JCdocsPrimary
    }

    val typeIconStr = when (doc.type) {
        "word" -> "W"
        "sheet" -> "S"
        "slide" -> "P"
        else -> "D"
    }

    val formattedDate = remember(doc.updatedAt) {
        val sdf = SimpleDateFormat("MMM dd, yyyy HH:mm", Locale.getDefault())
        sdf.format(Date(doc.updatedAt))
    }

    Card(
        onClick = onClick,
        colors = CardDefaults.cardColors(
            containerColor = if (isSelected) {
                typeColor.copy(alpha = 0.08f)
            } else {
                MaterialTheme.colorScheme.surface
            }
        ),
        shape = RoundedCornerShape(10.dp),
        border = BorderStroke(
            1.dp,
            if (isSelected) typeColor.copy(alpha = 0.5f) else Color.Transparent
        ),
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = 10.dp, vertical = 4.dp)
            .testTag("document_tile_${doc.id}")
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 14.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Icon layout matching office suite aesthetic
            Box(
                modifier = Modifier
                    .size(40.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(typeColor),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = typeIconStr,
                    fontWeight = FontWeight.Bold,
                    color = Color.White,
                    fontSize = 17.sp,
                    fontFamily = FontFamily.SansSerif
                )
            }

            Spacer(modifier = Modifier.width(12.dp))

            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = doc.title,
                    fontWeight = FontWeight.SemiBold,
                    fontSize = 15.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    color = MaterialTheme.colorScheme.onSurface
                )
                Spacer(modifier = Modifier.height(2.dp))
                Text(
                    text = formattedDate,
                    fontSize = 12.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
                )
            }

            // Document item actions
            Row(horizontalArrangement = Arrangement.End) {
                IconButton(
                    onClick = onFavoriteToggle,
                    modifier = Modifier.size(40.dp)
                ) {
                    Icon(
                        imageVector = if (doc.isFavorite) Icons.Outlined.Favorite else Icons.Outlined.FavoriteBorder,
                        contentDescription = "Toggle Favorite",
                        tint = if (doc.isFavorite) Color.Red else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.35f),
                        modifier = Modifier.size(22.dp)
                    )
                }
                IconButton(
                    onClick = onDelete,
                    modifier = Modifier.size(40.dp)
                ) {
                    Icon(
                        imageVector = Icons.Outlined.Delete,
                        contentDescription = "Delete Doc",
                        tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.35f),
                        modifier = Modifier.size(22.dp)
                    )
                }
            }
        }
    }
}

// Data class representing high-fidelity Ribbon Tool
data class RibbonTool(
    val id: String,
    val title: String,
    val description: String,
    val icon: ImageVector,
    val category: String,
    val tab: String,
    val actionId: String,
    val hasDropdown: Boolean = false,
    val dropdownOptions: List<String> = emptyList(),
    val onClick: () -> Unit = {},
    val onDropdownOptionClick: (String) -> Unit = {}
)

@OptIn(ExperimentalFoundationApi::class)
@Composable
fun RibbonToolCard(
    tool: RibbonTool,
    isDarkTheme: Boolean,
    modifier: Modifier = Modifier,
    isOptionSelected: ((actionId: String, option: String) -> Boolean)? = null
) {
    var expanded by remember { mutableStateOf(false) }

    Box(
        modifier = modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(6.dp))
            .clickable { 
                if (tool.hasDropdown) expanded = true 
                else tool.onClick() 
            }
            .padding(vertical = 4.dp),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Icon(
                imageVector = tool.icon,
                contentDescription = tool.title,
                tint = if (isDarkTheme) Color.White.copy(alpha = 0.85f) else Color.DarkGray,
                modifier = Modifier.size(20.dp)
            )
            Spacer(modifier = Modifier.height(2.dp))
            Text(
                text = tool.title,
                fontSize = 10.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = if (isDarkTheme) Color.LightGray else Color.DarkGray,
                textAlign = TextAlign.Center
            )
        }
        if (tool.hasDropdown) {
            Icon(
                imageVector = Icons.Outlined.ArrowDropDown,
                contentDescription = null,
                tint = if (isDarkTheme) Color.LightGray else Color.DarkGray,
                modifier = Modifier.size(12.dp).align(Alignment.CenterEnd).padding(end = 4.dp)
            )
            DropdownMenu(
                expanded = expanded,
                onDismissRequest = { expanded = false }
            ) {
                if (tool.dropdownOptions.isEmpty()) {
                    DropdownMenuItem(
                        text = { Text("More Options...", fontSize = 12.sp) },
                        onClick = {
                            expanded = false
                            tool.onClick()
                        }
                    )
                } else {
                    tool.dropdownOptions.forEach { option ->
                        val isSelected = isOptionSelected?.invoke(tool.actionId, option) == true
                        DropdownMenuItem(
                            text = { Text(option, fontSize = 12.sp) },
                            onClick = {
                                expanded = false
                                tool.onDropdownOptionClick(option)
                            },
                            leadingIcon = if (isSelected) {
                                {
                                    Icon(
                                        imageVector = Icons.Default.Check,
                                        contentDescription = "Selected",
                                        tint = if (isDarkTheme) Color.White else Color.Black,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            } else {
                                null
                            }
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun EditingButton(
    label: String,
    icon: ImageVector,
    accentColor: Color,
    isDarkTheme: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val bgColor = if (isDarkTheme) Color(0xFF2B2B30) else Color(0xFFF1F3F6)
    val borderColor = if (isDarkTheme) Color.White.copy(alpha = 0.06f) else Color.Black.copy(alpha = 0.04f)
    Card(
        modifier = modifier
            .clip(RoundedCornerShape(10.dp))
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(10.dp),
        colors = CardDefaults.cardColors(containerColor = bgColor),
        border = BorderStroke(0.5.dp, borderColor),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(vertical = 10.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Box(
                modifier = Modifier
                    .size(36.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(accentColor.copy(alpha = 0.12f)),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = icon,
                    contentDescription = label,
                    tint = accentColor,
                    modifier = Modifier.size(20.dp)
                )
            }
            Spacer(Modifier.height(6.dp))
            Text(
                text = label,
                fontSize = 11.sp,
                fontWeight = FontWeight.SemiBold,
                color = if (isDarkTheme) Color.White else Color.Black,
                maxLines = 1
            )
        }
    }
}

