object DocumentLayoutEngine {
    fun getDimensions(format: String, customDimensions: Pair<Float, Float>, isLandscape: Boolean): Pair<Dp, Dp> {
        val cleanFormat = format.substringBefore(" ").trim()
        val (pw, ph) = when (cleanFormat) {
            "A3" -> 842.dp to 1191.dp
            "A5" -> 420.dp to 595.dp
            "Letter" -> 612.dp to 792.dp
            "Legal" -> 612.dp to 1008.dp
            "Executive" -> 522.dp to 756.dp
            "Custom" -> (customDimensions.first * 72f).dp to (customDimensions.second * 72f).dp
            else -> 595.dp to 842.dp // A4 default
        }
        return if (isLandscape) ph to pw else pw to ph
    }
}

@Composable
fun PageRuler(
    modifier: Modifier = Modifier,
    isHorizontal: Boolean = true,
    totalLength: Dp,
    marginLeft: Dp = 72.dp,
    marginRight: Dp = 72.dp,
    editorTheme: String = "light"
) {
    val isDark = editorTheme == "dark" || isSystemInDarkTheme()
    
    // Aesthetic colors matching Microsoft Office & Word:
    // Solid background with shaded/darkened margin boundaries, crisp tick marks and readable numbers
    val rulerBgColor = if (isDark) Color(0xFF1F1F1F) else Color(0xFFF0F0F0)
    val inactiveAreaColor = if (isDark) Color(0xFF292929) else Color(0xFFDCDCDC) // Darker margin shade
    val activeAreaColor = if (isDark) Color(0xFF3B3B3B) else Color(0xFFFFFFFF) // Bright white/light active text area
    val markerColor = if (isDark) Color(0xFFCCCCCC) else Color(0xFF4A4A4A) // Tick indicators
    val labelColor = if (isDark) Color(0xFFAAAAAA) else Color(0xFF555555) // Number labels
    val boundaryLineColor = if (isDark) Color(0xFF444444) else Color(0xFFCCCCCC) // Bottom border of the ruler

    val density = LocalDensity.current
    val fontSizePx = with(density) { 9.sp.toPx() }

    androidx.compose.foundation.Canvas(
        modifier = modifier
            .width(if (isHorizontal) totalLength else 20.dp)
            .height(if (isHorizontal) 20.dp else totalLength)
            .background(rulerBgColor)
    ) {
        val totalLenPx = if (isHorizontal) size.width else size.height
        val crossLenPx = if (isHorizontal) size.height else size.width

        val leftMarginPx = marginLeft.toPx()
        val rightMarginPx = totalLenPx - marginRight.toPx()

        // 1. Draw Active Writing bounds (White) vs Inactive Margin Areas (Shaded Grey)
        if (isHorizontal) {
            // Draw left margin area (inactive)
            drawRect(
                color = inactiveAreaColor,
                topLeft = androidx.compose.ui.geometry.Offset(0f, 0f),
                size = androidx.compose.ui.geometry.Size(leftMarginPx, crossLenPx)
            )
            // Draw active typing area reference
            drawRect(
                color = activeAreaColor,
                topLeft = androidx.compose.ui.geometry.Offset(leftMarginPx, 0f),
                size = androidx.compose.ui.geometry.Size(rightMarginPx - leftMarginPx, crossLenPx)
            )
            // Draw right margin area (inactive)
            drawRect(
                color = inactiveAreaColor,
                topLeft = androidx.compose.ui.geometry.Offset(rightMarginPx, 0f),
                size = androidx.compose.ui.geometry.Size(totalLenPx - rightMarginPx, crossLenPx)
            )

            // Bottom border line separating ruler from content
            drawLine(
                color = boundaryLineColor,
                start = androidx.compose.ui.geometry.Offset(0f, crossLenPx - 1f),
                end = androidx.compose.ui.geometry.Offset(totalLenPx, crossLenPx - 1f),
                strokeWidth = 1f
            )

            // Margin border dividing brackets/lines
            drawLine(
                color = markerColor.copy(alpha = 0.8f),
                start = androidx.compose.ui.geometry.Offset(leftMarginPx, 0f),
                end = androidx.compose.ui.geometry.Offset(leftMarginPx, crossLenPx),
                strokeWidth = 1.5f
            )
            drawLine(
                color = markerColor.copy(alpha = 0.8f),
                start = androidx.compose.ui.geometry.Offset(rightMarginPx, 0f),
                end = androidx.compose.ui.geometry.Offset(rightMarginPx, crossLenPx),
                strokeWidth = 1.5f
            )
        } else {
            // Vertical Ruler
            drawRect(
                color = activeAreaColor,
                topLeft = androidx.compose.ui.geometry.Offset(0f, 0f),
                size = size
            )
        }

        // 2. Draw ruler scale ticks & inch labels (Scale interval matches 72 Dp = 1 Inch)
        val textPaint = android.graphics.Paint().apply {
            color = labelColor.toArgb()
            textSize = fontSizePx
            isAntiAlias = true
            textAlign = android.graphics.Paint.Align.CENTER
            typeface = android.graphics.Typeface.create("sans-serif", android.graphics.Typeface.BOLD)
        }

        val inchToPx = 72.dp.toPx()
        val subdivision = 8 // 1/8 inch intervals for maximum precision
        val intervalPx = inchToPx / subdivision
        val totalTicks = (totalLength.value / 72.0f * subdivision).toInt()

        for (i in 0..totalTicks) {
            val offsetPx = i * intervalPx
            if (offsetPx > totalLenPx) break

            val subIndex = i % subdivision
            val (tickHeight, isLabel) = when (subIndex) {
                0 -> (8.dp.toPx()) to true       // Major tick (1 inch)
                4 -> (5.dp.toPx()) to false       // Half-inch tick
                2, 6 -> (3.5.dp.toPx()) to false  // Quarter-inch tick
                else -> (2.dp.toPx()) to false    // Eighth-inch tick
            }

            if (isHorizontal) {
                // Bottom-aligned tick mark
                drawLine(
                    color = markerColor,
                    start = androidx.compose.ui.geometry.Offset(offsetPx, crossLenPx - 1f),
                    end = androidx.compose.ui.geometry.Offset(offsetPx, crossLenPx - 1f - tickHeight),
                    strokeWidth = if (subIndex == 0) 1.5f else 1f
                )

                // Render number string centered over major ticks
                if (isLabel && i > 0) {
                    val labelStr = (i / subdivision).toString()
                    val labelY = (crossLenPx / 2f) + (fontSizePx / 3f) - 1.dp.toPx()
                    drawContext.canvas.nativeCanvas.drawText(
                        labelStr,
                        offsetPx,
                        labelY,
                        textPaint
                    )
                }
            } else {
                // Right-aligned tick mark for vertical ruler if rendered
                drawLine(
                    color = markerColor,
                    start = androidx.compose.ui.geometry.Offset(crossLenPx - 1f, offsetPx),
                    end = androidx.compose.ui.geometry.Offset(crossLenPx - 1f - tickHeight, offsetPx),
                    strokeWidth = if (subIndex == 0) 1.5f else 1f
                )

                if (isLabel && i > 0) {
                    val labelStr = (i / subdivision).toString()
                    val labelY = offsetPx + (fontSizePx / 3f)
                    drawContext.canvas.nativeCanvas.drawText(
                        labelStr,
                        crossLenPx / 3f,
                        labelY,
                        textPaint
                    )
                }
            }
        }
    }
}

@Composable
fun WorkspacePane(
    selectedDoc: DocEntity?,
    draftTitle: String,
    draftContent: String,
    onTitleChange: (String) -> Unit,
    onContentChange: (String) -> Unit,
    onCloseClick: () -> Unit,
    onToggleSidebar: () -> Unit,
    isSidebarExpanded: Boolean,
    viewModel: DocViewModel,
    pageFormat: String,
    customDimensions: Pair<Float, Float>,
    onFABClick: () -> Unit = {},
    onOpenAICopilot: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val keyboardController = LocalSoftwareKeyboardController.current
    if (selectedDoc == null) {
        EmptyWorkspaceState(
            viewModel = viewModel,
            onToggleSidebar = onToggleSidebar,
            isSidebarExpanded = isSidebarExpanded,
            onQuickCreate = { title, type -> viewModel.createNewDocument(title, type) },
            onFABClick = onFABClick,
            onOpenAICopilot = onOpenAICopilot,
            modifier = modifier
        )
    } else {
        val editorTheme by viewModel.editorTheme.collectAsStateWithLifecycle()
        val selectedDocumentTheme by viewModel.selectedDocumentTheme.collectAsStateWithLifecycle()
        val selectedThemeEffect by viewModel.selectedThemeEffect.collectAsStateWithLifecycle()
        val pageMarginLeftVal by viewModel.pageMarginLeft.collectAsStateWithLifecycle()
        val pageMarginTopVal by viewModel.pageMarginTop.collectAsStateWithLifecycle()
        val pageMarginBottomVal by viewModel.pageMarginBottom.collectAsStateWithLifecycle()
        val pageMarginRightVal by viewModel.pageMarginRight.collectAsStateWithLifecycle()

        val pageMarginLeft = pageMarginLeftVal.dp
        val pageMarginRight = pageMarginRightVal.dp
        val pageMarginTop = pageMarginTopVal.dp
        val pageMarginBottom = pageMarginBottomVal.dp
        val pageMargins = pageMarginLeft

        val columnCount by viewModel.columnCount.collectAsStateWithLifecycle()
        val fontSizeVal by viewModel.fontSize.collectAsStateWithLifecycle()
        val fontSize = fontSizeVal.sp
        val isLandscape by viewModel.isLandscape.collectAsStateWithLifecycle()
        val pageBackgroundColorHex by viewModel.pageBackgroundColorHex.collectAsStateWithLifecycle()
        val watermarkText by viewModel.watermarkText.collectAsStateWithLifecycle()
        val watermarkType by viewModel.watermarkType.collectAsStateWithLifecycle()
        val watermarkColorHex by viewModel.watermarkColorHex.collectAsStateWithLifecycle()
        val pageBorderType by viewModel.pageBorderType.collectAsStateWithLifecycle()
        val pageBorderColorHex by viewModel.pageBorderColorHex.collectAsStateWithLifecycle()

        // --- REVIEW SYSTEM STATES ---
        var showSpellingDialog by remember { mutableStateOf(false) }
        var showThesaurusDialog by remember { mutableStateOf(false) }
        var showWordCountDialog by remember { mutableStateOf(false) }
        var showAccessibilityDialog by remember { mutableStateOf(false) }
        var showTranslateDialog by remember { mutableStateOf(false) }
        var translateIsSelectionMode by remember { mutableStateOf(false) }
        var showLanguageDialog by remember { mutableStateOf(false) }
        var showCommentsPane by remember { mutableStateOf(false) }
        var showRevisionsPane by remember { mutableStateOf(false) }
        var proofingLanguage by remember { mutableStateOf("English (United States)") }
        var showReadAloudControls by remember { mutableStateOf(false) }
        var readAloudSpeed by remember { mutableStateOf(1.0f) }

        var showCustomWatermarkDialog by remember { mutableStateOf(false) }
        var showPageBordersDialog by remember { mutableStateOf(false) }
        var showCustomMarginsDialog by remember { mutableStateOf(false) }
        var showCustomSizeDialog by remember { mutableStateOf(false) }
        var showPageNumberFormatDialog by remember { mutableStateOf(false) }
        val pageNumberPosition by viewModel.pageNumberPosition.collectAsStateWithLifecycle()
        val pageNumberFormat by viewModel.pageNumberFormat.collectAsStateWithLifecycle()
        val pageNumberStartAtVal by viewModel.pageNumberStartAt.collectAsStateWithLifecycle()
        val pageNumberStartAt = pageNumberStartAtVal.toString()
        var pageNumberPositionMenu by remember { mutableStateOf<String?>(null) }
        val showPageNumberOnFirstPage by viewModel.showPageNumberOnFirstPage.collectAsStateWithLifecycle()

        val headerText by viewModel.headerText.collectAsStateWithLifecycle()
        val footerText by viewModel.footerText.collectAsStateWithLifecycle()
        val headerAlignment by viewModel.headerAlignment.collectAsStateWithLifecycle()
        val footerAlignment by viewModel.footerAlignment.collectAsStateWithLifecycle()
        val showHeaderFooterOnFirstPage by viewModel.showHeaderFooterOnFirstPage.collectAsStateWithLifecycle()
        var showHeaderFooterDialog by remember { mutableStateOf(false) }

        var editorTextFieldValue by remember(selectedDoc.id) {
            mutableStateOf(TextFieldValue(text = draftContent, selection = TextRange(draftContent.length)))
        }

        var lastSelection by remember(selectedDoc.id) {
            mutableStateOf(TextRange(draftContent.length))
        }

        val targetFocusPage = remember(selectedDoc.id) { mutableStateOf<Int?>(null) }
        val targetFocusOffset = remember(selectedDoc.id) { mutableStateOf<Int?>(null) }

        var isEditorFocused by remember { mutableStateOf(false) }
        val context = androidx.compose.ui.platform.LocalContext.current
        val showToast = { msg: String ->
            android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_SHORT).show()
        }

        var tts by remember { mutableStateOf<android.speech.tts.TextToSpeech?>(null) }
        androidx.compose.runtime.DisposableEffect(context) {
            val t = android.speech.tts.TextToSpeech(context) { status ->
                if (status == android.speech.tts.TextToSpeech.SUCCESS) {
                    // Success
                }
            }
            tts = t
            onDispose {
                t.stop()
                t.shutdown()
            }
        }

        val clipboardHistory = remember { mutableStateListOf<String>() }
        var showClipboardHistory by remember { mutableStateOf(false) }
        var copiedFormattedData by remember { mutableStateOf<CopyFormattedData?>(null) }

        val undoRedoManager = remember(selectedDoc.id) { DocUndoRedoManager(selectedDoc.id) }
        var formatVersion by remember { mutableStateOf(0) } // Force recomposition when formatting spans change
        var undoRedoTrigger by remember { mutableStateOf(0) } // To force UI recompose when stacks change
        var isUndoRedoAction by remember(selectedDoc.id) { mutableStateOf(false) }

        var lastDocId by remember { mutableStateOf(-1) }
        var lastDraftContent by remember { mutableStateOf("") }

        if (selectedDoc.id != lastDocId) {
            lastDocId = selectedDoc.id
            lastDraftContent = draftContent
        }

        LaunchedEffect(draftContent) {
            if (isUndoRedoAction) {
                isUndoRedoAction = false
                lastDraftContent = draftContent
                return@LaunchedEffect
            }
            if (draftContent != lastDraftContent) {
                val oldText = lastDraftContent
                val newText = draftContent
                var cp = 0
                while (cp < oldText.length && cp < newText.length && oldText[cp] == newText[cp]) { cp++ }
                var cs = 0
                while (cp + cs < oldText.length && cp + cs < newText.length && oldText[oldText.length - 1 - cs] == newText[newText.length - 1 - cs]) { cs++ }
                val delLen = oldText.length - cp - cs
                val insLen = newText.length - cp - cs
                if (delLen > 0 || insLen > 0) {
                    DocFormatRepository.shiftSpans(selectedDoc.id, cp, delLen, insLen)
                }
                lastDraftContent = draftContent
            }
        }
        
        val activeFormatting by remember {
            derivedStateOf {
                formatVersion
                val spans = DocFormatRepository.getSpans(selectedDoc.id)
                val pos = editorTextFieldValue.selection.start
                if (pos < 0) emptySet()
                else spans.filter { it.start <= pos && it.end > pos }.map { it.type }.toSet()
            }
        }
        val cursorFontColorVal by remember {
            derivedStateOf {
                formatVersion
                val spans = DocFormatRepository.getSpans(selectedDoc.id)
                val pos = editorTextFieldValue.selection.start
                if (pos < 0) null else spans.find { it.type == "color" && it.start <= pos && it.end > pos }?.value
            }
        }
        val cursorHighlightColorVal by remember {
            derivedStateOf {
                formatVersion
                val spans = DocFormatRepository.getSpans(selectedDoc.id)
                val pos = editorTextFieldValue.selection.start
                if (pos < 0) null else spans.find { it.type == "highlight" && it.start <= pos && it.end > pos }?.value
            }
        }
        val cursorAlignmentVal by remember {
            derivedStateOf {
                formatVersion
                val spans = DocFormatRepository.getSpans(selectedDoc.id)
                val pos = editorTextFieldValue.selection.start
                if (pos < 0) null else spans.find { it.type == "alignment" && it.start <= pos && it.end > pos }?.value
            }
        }
        val cursorLineSpacingVal by remember {
            derivedStateOf {
                formatVersion
                val spans = DocFormatRepository.getSpans(selectedDoc.id)
                val pos = editorTextFieldValue.selection.start
                if (pos < 0) null else spans.find { it.type == "lineSpacing" && it.start <= pos && it.end > pos }?.value
            }
        }
        
        fun showUndoRedoFeedback(msg: String) {
            android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_SHORT).show()
        }

        val captureSnapshot = {
            DocEditorSnapshot(
                title = draftTitle,
                draftContent = editorTextFieldValue.text,
                textFieldValue = editorTextFieldValue,
                spans = DocFormatRepository.getSpans(selectedDoc.id).toList(),
                editorTheme = editorTheme,
                pageMargins = pageMargins,
                columnCount = columnCount,
                fontSize = fontSize,
                isLandscape = isLandscape,
                pageNumberPosition = pageNumberPosition,
                pageNumberFormat = pageNumberFormat,
                pageNumberStartAt = pageNumberStartAt,
                showPageNumberOnFirstPage = showPageNumberOnFirstPage,
                headerText = headerText,
                footerText = footerText,
                headerAlignment = headerAlignment,
                footerAlignment = footerAlignment,
                showHeaderFooterOnFirstPage = showHeaderFooterOnFirstPage,
                pageMarginTop = pageMarginTop,
                pageMarginBottom = pageMarginBottom,
                pageMarginLeft = pageMarginLeft,
                pageMarginRight = pageMarginRight,
                selectedDocumentTheme = selectedDocumentTheme,
                selectedThemeEffect = selectedThemeEffect,
                pageBackgroundColorHex = pageBackgroundColorHex,
                watermarkText = watermarkText,
                watermarkType = watermarkType,
                watermarkColorHex = watermarkColorHex,
                pageBorderType = pageBorderType,
                pageBorderColorHex = pageBorderColorHex,
                pageFormat = pageFormat,
                customPageWidth = customDimensions.first,
                customPageHeight = customDimensions.second,
                shapes = DocShapeRepository.getShapes(selectedDoc.id).toList(),
                tables = DocTableRepository.getTables(selectedDoc.id).toList(),
                pictures = DocPictureRepository.getPictures(selectedDoc.id).toList()
            )
        }

        val pushSnapshot: () -> Unit = {
            undoRedoManager.pushState(captureSnapshot())
            undoRedoTrigger++
        }

        val imagePickerLauncher = rememberLauncherForActivityResult(
            contract = ActivityResultContracts.GetContent()
        ) { uri ->
            uri?.let { selectedUri ->
                // Copy the picked image to app internal storage to ensure permanent read permission
                val localUriStr = try {
                    val inputStream = context.contentResolver.openInputStream(selectedUri)
                    val ext = when (context.contentResolver.getType(selectedUri)) {
                        "image/png" -> "png"
                        "image/gif" -> "gif"
                        "image/webp" -> "webp"
                        else -> "jpg"
                    }
                    val file = java.io.File(context.getExternalFilesDir("backend_data") ?: context.filesDir, "inserted_image_${System.currentTimeMillis()}.$ext")
                    inputStream?.use { input ->
                        file.outputStream().use { output ->
                            input.copyTo(output)
                        }
                    }
                    file.absolutePath
                } catch (e: Exception) {
                    selectedUri.toString()
                }

                val pos = editorTextFieldValue.selection.start
                val pages = draftContent.split("\u000C")
                var accumulated = 0
                var targetIndex = 0
                for (i in pages.indices) {
                    val pageLen = pages[i].length
                    if (pos >= accumulated && pos <= accumulated + pageLen) {
                        targetIndex = i
                        break
                    }
                    accumulated += pageLen + 1
                }
                DocPictureRepository.addPicture(
                    docId = selectedDoc.id,
                    picture = DocPicture(
                        uri = localUriStr,
                        pageIndex = targetIndex,
                        x = 50.dp,
                        y = 100.dp,
                        width = 180.dp,
                        height = 180.dp
                    )
                )
                android.widget.Toast.makeText(context, "Inserted picture on Page ${targetIndex + 1}!", android.widget.Toast.LENGTH_SHORT).show()
                formatVersion++
            }
        }

        val performUndo = {
            val restored = undoRedoManager.undo(captureSnapshot())
            if (restored != null) {
                showUndoRedoFeedback("Undo")
                undoRedoManager.isRestoring = true
                isUndoRedoAction = true
                onTitleChange(restored.title)
                editorTextFieldValue = restored.textFieldValue
                onContentChange(restored.draftContent)
                
                val currentSpans = DocFormatRepository.getSpans(selectedDoc.id)
                currentSpans.clear()
                currentSpans.addAll(restored.spans.map { it.copy() })
                
                viewModel.setEditorTheme(restored.editorTheme)
                viewModel.setColumnCount(restored.columnCount)
                viewModel.setFontSize(restored.fontSize.value)
                viewModel.setIsLandscape(restored.isLandscape)
                viewModel.setPageNumbering(
                    restored.pageNumberPosition,
                    restored.pageNumberFormat,
                    restored.pageNumberStartAt.toIntOrNull() ?: 1,
                    restored.showPageNumberOnFirstPage
                )
                viewModel.setHeaderFooter(
                    restored.headerText,
                    restored.footerText,
                    restored.headerAlignment,
                    restored.footerAlignment,
                    restored.showHeaderFooterOnFirstPage
                )
                viewModel.setPageMargins(
                    restored.pageMarginLeft.value,
                    restored.pageMarginTop.value,
                    restored.pageMarginRight.value,
                    restored.pageMarginBottom.value
                )
                viewModel.setSelectedDocumentTheme(restored.selectedDocumentTheme)
                viewModel.setSelectedThemeEffect(restored.selectedThemeEffect)
                viewModel.setPageBackgroundColorHex(restored.pageBackgroundColorHex)
                viewModel.setWatermark(restored.watermarkText, restored.watermarkType, restored.watermarkColorHex)
                viewModel.setPageBorder(restored.pageBorderType, restored.pageBorderColorHex)
                viewModel.setPageFormat(restored.pageFormat)
                viewModel.setCustomPageDimensions(restored.customPageWidth, restored.customPageHeight)

                // Restore shapes
                val currentShapes = DocShapeRepository.getShapes(selectedDoc.id)
                currentShapes.clear()
                currentShapes.addAll(restored.shapes.map { it.copy() })

                // Restore tables
                val currentTables = DocTableRepository.getTables(selectedDoc.id)
                currentTables.clear()
                currentTables.addAll(restored.tables.map { it.copy() })

                // Restore pictures
                val currentPictures = DocPictureRepository.getPictures(selectedDoc.id)
                currentPictures.clear()
                currentPictures.addAll(restored.pictures.map { it.copy() })
                
                undoRedoTrigger++
                undoRedoManager.isRestoring = false
            }
        }

        val performRedo = {
            val restored = undoRedoManager.redo(captureSnapshot())
            if (restored != null) {
                showUndoRedoFeedback("Redo")
                undoRedoManager.isRestoring = true
                isUndoRedoAction = true
                onTitleChange(restored.title)
                editorTextFieldValue = restored.textFieldValue
                onContentChange(restored.draftContent)
                
                val currentSpans = DocFormatRepository.getSpans(selectedDoc.id)
                currentSpans.clear()
                currentSpans.addAll(restored.spans.map { it.copy() })
                
                viewModel.setEditorTheme(restored.editorTheme)
                viewModel.setColumnCount(restored.columnCount)
                viewModel.setFontSize(restored.fontSize.value)
                viewModel.setIsLandscape(restored.isLandscape)
                viewModel.setPageNumbering(
                    restored.pageNumberPosition,
                    restored.pageNumberFormat,
                    restored.pageNumberStartAt.toIntOrNull() ?: 1,
                    restored.showPageNumberOnFirstPage
                )
                viewModel.setHeaderFooter(
                    restored.headerText,
                    restored.footerText,
                    restored.headerAlignment,
                    restored.footerAlignment,
                    restored.showHeaderFooterOnFirstPage
                )
                viewModel.setPageMargins(
                    restored.pageMarginLeft.value,
                    restored.pageMarginTop.value,
                    restored.pageMarginRight.value,
                    restored.pageMarginBottom.value
                )
                viewModel.setSelectedDocumentTheme(restored.selectedDocumentTheme)
                viewModel.setSelectedThemeEffect(restored.selectedThemeEffect)
                viewModel.setPageBackgroundColorHex(restored.pageBackgroundColorHex)
                viewModel.setWatermark(restored.watermarkText, restored.watermarkType, restored.watermarkColorHex)
                viewModel.setPageBorder(restored.pageBorderType, restored.pageBorderColorHex)
                viewModel.setPageFormat(restored.pageFormat)
                viewModel.setCustomPageDimensions(restored.customPageWidth, restored.customPageHeight)

                // Restore shapes
                val currentShapes = DocShapeRepository.getShapes(selectedDoc.id)
                currentShapes.clear()
                currentShapes.addAll(restored.shapes.map { it.copy() })

                // Restore tables
                val currentTables = DocTableRepository.getTables(selectedDoc.id)
                currentTables.clear()
                currentTables.addAll(restored.tables.map { it.copy() })

                // Restore pictures
                val currentPictures = DocPictureRepository.getPictures(selectedDoc.id)
                currentPictures.clear()
                currentPictures.addAll(restored.pictures.map { it.copy() })
                
                undoRedoTrigger++
                undoRedoManager.isRestoring = false
            }
        }

        LaunchedEffect(draftContent) {
            if (editorTextFieldValue.text != draftContent) {
                editorTextFieldValue = editorTextFieldValue.copy(
                    text = draftContent,
                    selection = TextRange(
                        editorTextFieldValue.selection.start.coerceIn(0, draftContent.length),
                        editorTextFieldValue.selection.end.coerceIn(0, draftContent.length)
                    )
                )
                lastSelection = TextRange(
                    lastSelection.start.coerceIn(0, draftContent.length),
                    lastSelection.end.coerceIn(0, draftContent.length)
                )
            }
        }

        var activeRibbonTab by remember { mutableStateOf("Home") }
        var isRibbonExpanded by remember { mutableStateOf(true) }
        var ribbonHeightDp by remember { mutableStateOf(300.dp) }
        var ribbonSearchQuery by remember { mutableStateOf("") }
        val ribbonSearchFocusRequester = remember { androidx.compose.ui.focus.FocusRequester() }

        var isFontExpanded by remember { mutableStateOf(true) }
        var isClipboardExpanded by remember { mutableStateOf(true) }
        var isStylesExpanded by remember { mutableStateOf(true) }
        var isEditingExpanded by remember { mutableStateOf(true) }
        var isStatsExpanded by remember { mutableStateOf(true) }

        var activeFontFamily by remember { mutableStateOf("Default") }
        var activeFontSize by remember { mutableStateOf("16") }
        var showPasteSpecialDialog by remember { mutableStateOf(false) }
        var showInsertPictureDialog by remember { mutableStateOf(false) }
        var showInsertTableDialog by remember { mutableStateOf(false) }
        var showInsertShapeDialog by remember { mutableStateOf(false) }
        var selectedTableId by remember { mutableStateOf<String?>(null) }
        var selectedShapeId by remember { mutableStateOf<String?>(null) }
        var pendingPasteSelStart by remember { mutableIntStateOf(0) }
        var pendingPasteSelEnd by remember { mutableIntStateOf(0) }
        var pendingPasteText by remember { mutableStateOf("") }
        var showFontColorPicker by remember { mutableStateOf(false) }
        var showHighlightPicker by remember { mutableStateOf(false) }

        var showBulletStyleDialog by remember { mutableStateOf(false) }
        var showNumberFormatDialog by remember { mutableStateOf(false) }
        var showLineSpacingDialog by remember { mutableStateOf(false) }
        var showBordersDialog by remember { mutableStateOf(false) }
        var showFindDialog by remember { mutableStateOf(false) }
        var showGoToDialog by remember { mutableStateOf(false) }
        var findQuery by remember { mutableStateOf("") }
        var replaceQuery by remember { mutableStateOf("") }
        var findMode by remember { mutableStateOf("find") }
        var matchCase by remember { mutableStateOf(false) }
        var wholeWord by remember { mutableStateOf(false) }
        var currentMatchIndex by remember { mutableIntStateOf(0) }
        var textStyles by remember { mutableStateOf(getDefaultTextStyles()) }
        var showStyleManager by remember { mutableStateOf(false) }
        var showStyleEditor by remember { mutableStateOf(false) }
        var editingStyleIndex by remember { mutableIntStateOf(-1) }
        var editingStyleName by remember { mutableStateOf("") }
        var editingStyleFontSize by remember { mutableIntStateOf(16) }
        var editingStyleBold by remember { mutableStateOf(false) }
        var editingStyleItalic by remember { mutableStateOf(false) }
        var editingStyleUnderline by remember { mutableStateOf(false) }
        var editingStyleColor by remember { mutableStateOf("#000000") }
        var editingStyleAlignment by remember { mutableStateOf("left") }
        var editingStyleLineSpacing by remember { mutableStateOf("1.0") }
        var showShadingPicker by remember { mutableStateOf(false) }
        val pageBackgroundColor: Color? by remember {
            derivedStateOf {
                if (pageBackgroundColorHex.isNotEmpty()) {
                    try { Color(android.graphics.Color.parseColor(pageBackgroundColorHex)) } catch (e: Exception) { null }
                } else null
            }
        }
        var pendingParaAction by remember { mutableStateOf<String?>(null) }

        val coroutineScope = rememberCoroutineScope()
        val snackbarHostState = remember { SnackbarHostState() }

        var isSpeaking by remember { mutableStateOf(false) }

        val handleRibbonAction: (String) -> Unit = { action ->
            pushSnapshot()
            if (action == "insert_table" || action == "table") {
                showInsertTableDialog = true
            } else if (action == "shapes") {
                showInsertShapeDialog = true
            } else if (action == "picture" || action == "pictures") {
                showInsertPictureDialog = true
            } else {
                executeRibbonAction(
                    actionId = action,
                    context = context,
                    draftContent = draftContent,
                    onContentChange = onContentChange,
                    selectedDoc = selectedDoc,
                    viewModel = viewModel,
                    editorTheme = editorTheme,
                    onThemeChange = { viewModel.setEditorTheme(it) },
                    selectedDocumentTheme = selectedDocumentTheme,
                    onDocumentThemeChange = { viewModel.setSelectedDocumentTheme(it) },
                    selectedThemeEffect = selectedThemeEffect,
                    onThemeEffectChange = { viewModel.setSelectedThemeEffect(it) },
                    onMarginsChange = { top, bottom, left, right ->
                        viewModel.setPageMargins(left.value, top.value, right.value, bottom.value)
                    },
                    onColumnsChange = { viewModel.setColumnCount(it) },
                    onFontSizeChange = { viewModel.setFontSize(it.value) },
                    onLandscapeChange = { viewModel.setIsLandscape(it) },
                    onShowCustomMarginsDialog = { showCustomMarginsDialog = true },
                    onShowCustomSizeDialog = { showCustomSizeDialog = true },
                    onShowPageNumberFormatDialog = { showPageNumberFormatDialog = true },
                    onShowHeaderFooterDialog = { showHeaderFooterDialog = true },
                    onShowPageNumberPositionMenu = { pageNumberPositionMenu = it },
                    onPageNumberPositionChange = { viewModel.setPageNumbering(it, pageNumberFormat, pageNumberStartAt.toIntOrNull() ?: 1, showPageNumberOnFirstPage) },
                    pageNumberFormat = pageNumberFormat,
                    pageNumberStartAt = pageNumberStartAt.toIntOrNull() ?: 1,
                    snackbarScope = coroutineScope,
                    snackbarState = snackbarHostState,
                    tts = tts,
                    isSpeaking = isSpeaking,
                    onSpeakStateChange = { isSpeaking = it },
                    textFieldValue = editorTextFieldValue,
                    onTextFieldValueChange = { newVal ->
                        val textChanged = newVal.text != editorTextFieldValue.text
                        val selectionChanged = newVal.selection != editorTextFieldValue.selection
                        if (textChanged || selectionChanged) {
                            pushSnapshot()
                        }
                        editorTextFieldValue = newVal
                        if (isEditorFocused) {
                            lastSelection = newVal.selection
                        }
                        if (textChanged) {
                            onContentChange(newVal.text)
                        }
                    },
                    lastSelection = lastSelection,
                    formatVersion = formatVersion,
                    onFormatVersionChange = { formatVersion = it },
                    onHistoryAdd = { clipboardHistory.add(it) },
                    onCopyFormatted = { text, spans, off -> copiedFormattedData = CopyFormattedData(text, spans, off) },
                    onTargetFocusChange = { page, offset ->
                        targetFocusPage.value = page
                        targetFocusOffset.value = offset
                    },
                    pageBackgroundColorHex = pageBackgroundColorHex,
                    onPageBackgroundColorHexChange = { viewModel.setPageBackgroundColorHex(it) },
                    watermarkText = watermarkText,
                    onWatermarkSet = { text, type ->
                        if (text == "CUSTOM_PROMPT") {
                            showCustomWatermarkDialog = true
                        } else {
                            viewModel.setWatermark(text, type, watermarkColorHex)
                        }
                    },
                    pageBorderType = pageBorderType,
                    onPageBorderChange = { 
                        if (it == "Custom Borders...") {
                            showPageBordersDialog = true
                        } else {
                            viewModel.setPageBorder(it, pageBorderColorHex)
                        }
                    },
                    onShowShadingPicker = { showShadingPicker = true },
                    onShowSpellingDialog = { showSpellingDialog = true },
                    onShowThesaurusDialog = { showThesaurusDialog = true },
                    onShowWordCountDialog = { showWordCountDialog = true },
                    onShowAccessibilityDialog = { showAccessibilityDialog = true },
                    onShowTranslateDialog = { isSel ->
                        translateIsSelectionMode = isSel
                        showTranslateDialog = true
                    },
                    onShowLanguageDialog = { showLanguageDialog = true },
                    onNewComment = {
                        pushSnapshot()
                        val sel = editorTextFieldValue.selection
                        DocReviewManager.addComment(
                            docId = selectedDoc.id,
                            text = "Please review this text segment.",
                            author = "User",
                            startOffset = sel.start,
                            endOffset = if (sel.collapsed) sel.start + 10 else sel.end
                        )
                        showCommentsPane = true
                        formatVersion++
                    },
                    onDeleteComment = {
                        val comments = DocReviewManager.getCommentsForDoc(selectedDoc.id)
                        if (comments.isNotEmpty()) {
                            DocReviewManager.deleteComment(selectedDoc.id, comments.last().id)
                            formatVersion++
                        }
                    },
                    onShowCommentsToggle = {
                        showCommentsPane = !showCommentsPane
                    },
                    onToggleTrackChanges = {
                        val currentVal = DocReviewManager.isTrackingEnabled(selectedDoc.id)
                        DocReviewManager.toggleTracking(selectedDoc.id)
                        showToast(if (!currentVal) "Track Changes ENABLED" else "Track Changes DISABLED")
                    },
                    onShowReviewPane = {
                        showRevisionsPane = !showRevisionsPane
                    },
                    onAcceptAllTrackChanges = {
                        pushSnapshot()
                        var current = draftContent
                        DocReviewManager.getTrackedChangesForDoc(selectedDoc.id).forEach { chg ->
                            DocReviewManager.acceptTrackedChange(selectedDoc.id, chg, current) { current = it }
                        }
                        onContentChange(current)
                        editorTextFieldValue = TextFieldValue(current, TextRange(current.length))
                        formatVersion++
                        showToast("Accepted all tracked changes.")
                    },
                    onRejectAllTrackChanges = {
                        pushSnapshot()
                        var current = draftContent
                        DocReviewManager.getTrackedChangesForDoc(selectedDoc.id).forEach { chg ->
                            DocReviewManager.rejectTrackedChange(selectedDoc.id, chg, current) { current = it }
                        }
                        onContentChange(current)
                        editorTextFieldValue = TextFieldValue(current, TextRange(current.length))
                        formatVersion++
                        showToast("Rejected all tracked changes.")
                    }
                )
            }
        }

        BoxWithConstraints(
            modifier = modifier
                .fillMaxSize()
                .background(Color(0xFFEAECF0).copy(alpha = 0.5f))
        ) {
            val totalHeight = maxHeight
            val totalWidth = maxWidth

            val isLandscapeLayout = totalWidth > totalHeight
            val sideNavBarWidth = 64.dp

            val minHeightDp = 120.dp
            val maxHeightDp = totalHeight * 0.85f

            val coercedRibbonHeight = ribbonHeightDp.coerceIn(minHeightDp, maxHeightDp)
            val bottomNavBarHeight = 68.dp
            
            val imeBottom = WindowInsets.ime.getBottom(LocalDensity.current)
            val isImeVisible = imeBottom > 0

            LaunchedEffect(isImeVisible, activeRibbonTab) {
                if (isImeVisible && activeRibbonTab != "AI") {
                    isRibbonExpanded = false
                }
            }
            
            val targetRibbonHeight = if (isRibbonExpanded) {
                if (isImeVisible) {
                    if (activeRibbonTab == "AI") coercedRibbonHeight
                    else 0.dp
                } else coercedRibbonHeight
            } else {
                if (!isImeVisible || activeRibbonTab == "AI") (bottomNavBarHeight + 12.dp) else 0.dp
            }
            val animatedRibbonHeight by androidx.compose.animation.core.animateDpAsState(
                targetValue = targetRibbonHeight,
                animationSpec = spring(dampingRatio = 0.82f, stiffness = 400f),
                label = "ribbonHeight"
            )

            val targetRibbonWidth = if (isRibbonExpanded) (sideNavBarWidth + 296.dp) else sideNavBarWidth
            val animatedRibbonWidth by androidx.compose.animation.core.animateDpAsState(
                targetValue = targetRibbonWidth,
                animationSpec = spring(dampingRatio = 0.82f, stiffness = 400f),
                label = "ribbonWidth"
            )

            val isPdfType = selectedDoc.type == "pdf"
            val editorBottomPadding = (if (isPdfType) 0.dp else (if (isLandscapeLayout) 0.dp else (if (isImeVisible && activeRibbonTab != "AI") 0.dp else animatedRibbonHeight))).coerceAtLeast(0.dp)
            val editorEndPadding = (if (isPdfType) 0.dp else (if (isLandscapeLayout) animatedRibbonWidth else 0.dp)).coerceAtLeast(0.dp)

            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(bottom = editorBottomPadding, end = editorEndPadding)
            ) {
                WorkspaceMenuBar(
                    doc = selectedDoc,
