                        ) {
                            Icon(
                                imageVector = if (isRibbonExpanded) Icons.Outlined.KeyboardArrowUp else Icons.Outlined.KeyboardArrowDown,
                                contentDescription = if (isRibbonExpanded) "Collapse Ribbon" else "Expand Ribbon",
                                tint = if (isDarkTheme) Color.LightGray else Color.DarkGray,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                    }
                } else {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(bottomNavBarHeight)
                            .background(if (isDarkTheme) Color(0xFF1A1C20) else Color(0xFFFAFBFF))
                            .drawBehind {
                                drawLine(
                                    color = if (isDarkTheme) Color.White.copy(alpha = 0.08f) else Color.Black.copy(alpha = 0.06f),
                                    start = Offset(0f, size.height),
                                    end = Offset(size.width, size.height),
                                    strokeWidth = 1f
                                )
                            },
                        horizontalArrangement = Arrangement.SpaceEvenly,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        ribbonTabs.forEach { (tabName, icon, tag) ->
