                    title = { Text("Clipboard History") },
                    text = {
                        if (clipboardHistory.isEmpty()) {
                            Text("No clipboard history yet")
                        } else {
                            Column(modifier = Modifier.verticalScroll(rememberScrollState())) {
                                clipboardHistory.reversed().forEach { entry ->
                                    TextButton(
                                        onClick = {
                                            val sel = editorTextFieldValue.selection
                                            val start = minOf(sel.start, sel.end)
                                            val end = maxOf(sel.start, sel.end)
                                            val newText = draftContent.substring(0, start) + entry + draftContent.substring(end)
                                            onContentChange(newText)
                                            val newCursor = start + entry.length
                                            editorTextFieldValue = TextFieldValue(text = newText, selection = TextRange(newCursor))
                                            showClipboardHistory = false
                                        },
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Text(
                                            text = entry.take(80) + if (entry.length > 80) "..." else "",
                                            textAlign = TextAlign.Start,
                                            modifier = Modifier.fillMaxWidth()
                                        )
                                    }
                                }
                            }
                        }
                    },
                    confirmButton = {
                        TextButton(onClick = {
                            clipboardHistory.clear()
                            showClipboardHistory = false
                        }) {
                            Text("Clear All")
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showClipboardHistory = false }) {
                            Text("Close")
                        }
                    }
                )
            }
        }
    }
}

@Composable
fun EmptyWorkspaceState(
    viewModel: DocViewModel,
    onToggleSidebar: () -> Unit,
    isSidebarExpanded: Boolean,
    onQuickCreate: (String, String) -> Unit,
    onFABClick: () -> Unit,
    onOpenAICopilot: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val documents by viewModel.documents.collectAsStateWithLifecycle()
    val searchQuery by viewModel.searchQuery.collectAsStateWithLifecycle()
    val activeTabState by viewModel.activeTab.collectAsStateWithLifecycle()
    var activeTab by remember { mutableStateOf("home") } // "home", "files", "shared", "settings"

    val isDark = isSystemInDarkTheme()
    val cardBgColor = if (isDark) Color(0xFF1E1E22) else Color.White
    val cardBorderColor = if (isDark) Color.White.copy(alpha = 0.12f) else Color(0xFFE2E8F0)
    val textMainColor = if (isDark) Color.White else Color(0xFF0F172A)
    val textSubColor = if (isDark) Color(0xFF94A3B8) else Color(0xFF64748B)
    val dividerColor1 = if (isDark) Color.White.copy(alpha = 0.08f) else Color(0xFFF1F5F9)
    val screenBgColor = if (isDark) Color(0xFF121212) else Color(0xFFFDFBFF)
    val searchBgColor = if (isDark) Color(0xFF1E1E22) else Color(0xFFF8FAFC)

    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    val permissionSharedPrefs = remember { context.getSharedPreferences("jc_docs_startup_perm_prefs", android.content.Context.MODE_PRIVATE) }
    var showStartupPermissionsSequence by remember {
        mutableStateOf(!permissionSharedPrefs.getBoolean("has_completed_startup_permissions_seq2", false))
    }
    var startupStep by remember { mutableStateOf(0) } // 0 = start, 1 = storage requested, 2 = storage back/camera ready, 3 = camera requested, 4 = camera back/notifications ready, 5 = notifications requested, 6 = all finish

    var hasStoragePermission by remember {
        mutableStateOf(
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_MEDIA_IMAGES) == android.content.pm.PackageManager.PERMISSION_GRANTED ||
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_MEDIA_VIDEO) == android.content.pm.PackageManager.PERMISSION_GRANTED
            } else {
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.READ_EXTERNAL_STORAGE) == android.content.pm.PackageManager.PERMISSION_GRANTED
            }
        )
    }
    var hasCameraPermission by remember {
        mutableStateOf(
            androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.CAMERA) == android.content.pm.PackageManager.PERMISSION_GRANTED
        )
    }
    var hasNotificationPermission by remember {
        mutableStateOf(
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.POST_NOTIFICATIONS) == android.content.pm.PackageManager.PERMISSION_GRANTED
            } else {
                true
            }
        )
    }

    var showStorageRationaleDialog by remember { mutableStateOf(false) }
    var showCameraRationaleDialog by remember { mutableStateOf(false) }
    var showNotificationRationaleDialog by remember { mutableStateOf(false) }

    val storagePermissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestMultiplePermissions()
    ) { permissionsMap ->
        val readGranted = permissionsMap[android.Manifest.permission.READ_EXTERNAL_STORAGE] ?: false
        val writeGranted = permissionsMap[android.Manifest.permission.WRITE_EXTERNAL_STORAGE] ?: false
        val imagesGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_IMAGES] ?: false
        val videosGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_VIDEO] ?: false
        val audioGranted = permissionsMap[android.Manifest.permission.READ_MEDIA_AUDIO] ?: false

        hasStoragePermission = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
            imagesGranted || videosGranted || audioGranted
        } else {
            readGranted || writeGranted
        }
        if (showStartupPermissionsSequence) {
            startupStep = 2 // proceed directly to camera
        } else {
            if (!hasStoragePermission) {
                showStorageRationaleDialog = true
            } else {
                Toast.makeText(context, "Storage permission granted! Workspace export is fully operational.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    val cameraPermissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        hasCameraPermission = isGranted
        if (showStartupPermissionsSequence) {
            startupStep = 4 // proceed directly to notification
        } else {
            if (!isGranted) {
                showCameraRationaleDialog = true
            } else {
                Toast.makeText(context, "Camera access granted! Ready to snap pictures.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    val notificationPermissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        hasNotificationPermission = isGranted
        if (showStartupPermissionsSequence) {
            permissionSharedPrefs.edit().putBoolean("has_completed_startup_permissions_seq2", true).apply()
            showStartupPermissionsSequence = false
            startupStep = 6
        } else {
            if (!isGranted) {
                showNotificationRationaleDialog = true
            } else {
                Toast.makeText(context, "Notifications enabled! You'll receive live document alerts.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    LaunchedEffect(showStartupPermissionsSequence, startupStep) {
        if (showStartupPermissionsSequence) {
            when (startupStep) {
                0 -> {
                    // Delay for 2 seconds (2000 milliseconds) on first launch
                    kotlinx.coroutines.delay(2000L)
                    startupStep = 1
                }
                1 -> {
                    // Start requesting storage permissions sequentially when user taps button (step 1)
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                        storagePermissionLauncher.launch(
                            arrayOf(
                                android.Manifest.permission.READ_MEDIA_IMAGES,
                                android.Manifest.permission.READ_MEDIA_VIDEO
                            )
                        )
                    } else {
                        storagePermissionLauncher.launch(
                            arrayOf(
                                android.Manifest.permission.READ_EXTERNAL_STORAGE,
                                android.Manifest.permission.WRITE_EXTERNAL_STORAGE
                            )
                        )
                    }
                    // Stay on step 1 to await callback
                }
                2 -> {
                    // Start requesting camera permission sequentially
                    cameraPermissionLauncher.launch(android.Manifest.permission.CAMERA)
                    startupStep = 3
                }
                4 -> {
                    // Start requesting notification permission sequentially on Tiramisu+
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                        notificationPermissionLauncher.launch(android.Manifest.permission.POST_NOTIFICATIONS)
                        startupStep = 5
                    } else {
                        hasNotificationPermission = true
                        permissionSharedPrefs.edit().putBoolean("has_completed_startup_permissions_seq2", true).apply()
                        showStartupPermissionsSequence = false
                        startupStep = 6
                    }
                }
            }
        }
    }

    // --- Permissions Rationale Dialogs ---
    if (showStorageRationaleDialog) {
        AlertDialog(
            onDismissRequest = { showStorageRationaleDialog = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Outlined.Folder,
                        contentDescription = null,
                        tint = Color(0xFF5B2BE0),
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Storage Access Required")
                }
            },
            text = {
                Text(
                    text = "JCDocs requires storage permissions to import and export files directly on your device storage. To use this feature, please enable storage access manually in Settings.",
                    fontSize = 13.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        try {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                                data = android.net.Uri.fromParts("package", context.packageName, null)
                            }
                            context.startActivity(intent)
                        } catch (e: Exception) {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_SETTINGS)
                            context.startActivity(intent)
                        }
                        showStorageRationaleDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                ) {
                    Text("Go to Settings", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showStorageRationaleDialog = false }) {
                    Text("Skip Feature", color = Color.Gray)
                }
            }
        )
    }

    if (showCameraRationaleDialog) {
        AlertDialog(
            onDismissRequest = { showCameraRationaleDialog = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Outlined.Camera,
                        contentDescription = null,
                        tint = Color(0xFFEA580C),
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Camera Access Required")
                }
            },
            text = {
                Text(
                    text = "Camera permission allows you to snap live photos and embed them directly inside your word documents or spreadsheets. To use this feature, please enable camera access in app settings.",
                    fontSize = 13.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        try {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                                data = android.net.Uri.fromParts("package", context.packageName, null)
                            }
                            context.startActivity(intent)
                        } catch (e: Exception) {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_SETTINGS)
                            context.startActivity(intent)
                        }
                        showCameraRationaleDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                ) {
                    Text("Go to Settings", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showCameraRationaleDialog = false }) {
                    Text("Skip Feature", color = Color.Gray)
                }
            }
        )
    }

    if (showNotificationRationaleDialog) {
        AlertDialog(
            onDismissRequest = { showNotificationRationaleDialog = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Outlined.Notifications,
                        contentDescription = null,
                        tint = Color(0xFF3B82F6),
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Notifications Required")
                }
            },
            text = {
                Text(
                    text = "Notification access keeps you updated with background document syncs, active collaboration alerts, and storage limits. Enable it in app settings manually to resume notifications.",
                    fontSize = 13.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        try {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                                data = android.net.Uri.fromParts("package", context.packageName, null)
                            }
                            context.startActivity(intent)
                        } catch (e: Exception) {
                            val intent = android.content.Intent(android.provider.Settings.ACTION_SETTINGS)
                            context.startActivity(intent)
                        }
                        showNotificationRationaleDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                ) {
                    Text("Go to Settings", color = Color.White)
                }
            },
            dismissButton = {
                TextButton(onClick = { showNotificationRationaleDialog = false }) {
                    Text("Skip Feature", color = Color.Gray)
                }
            }
        )
    }

    val importLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.OpenDocument()
    ) { uri ->
        uri?.let { fileUri ->
            scope.launch(kotlinx.coroutines.Dispatchers.IO) {
                try {
                    val cr = context.contentResolver
                    var displayName = ""
                    try {
                        cr.query(fileUri, null, null, null, null)?.use { cursor ->
                            val nameIndex = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                            if (nameIndex != -1 && cursor.moveToFirst()) {
                                displayName = cursor.getString(nameIndex)
                            }
                        }
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }
                    if (displayName.isEmpty()) {
                        displayName = fileUri.lastPathSegment ?: "Imported Document"
                    }

                    val extension = displayName.substringAfterLast(".").lowercase()
                    val cleanTitle = displayName.substringBeforeLast(".")

                    if (extension == "pdf") {
                        try {
                            val pdfFile = java.io.File(context.getExternalFilesDir("backend_data") ?: context.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                            cr.openInputStream(fileUri)?.use { inputStream ->
                                pdfFile.outputStream().use { output ->
                                    inputStream.copyTo(output)
                                }
                            }
                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                viewModel.createNewDocument(cleanTitle, "pdf", pdfFile.absolutePath)
                                Toast.makeText(context, "Successfully imported PDF $displayName", Toast.LENGTH_SHORT).show()
                            }
                        } catch (e: Exception) {
                            e.printStackTrace()
                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                Toast.makeText(context, "Failed to import PDF: ${e.message}", Toast.LENGTH_SHORT).show()
                            }
                        }
                    } else {
                        cr.openInputStream(fileUri)?.use { inputStream ->
                            val importedText = when (extension) {
                                "docx", "doc" -> DocumentImportExportHelper.parseDocxText(inputStream)
                                "txt", "csv", "xml", "json" -> {
                                    DocumentImportExportHelper.prePaginateText(inputStream.reader(Charsets.UTF_8).readText())
                                }
                                else -> {
                                    val bytes = inputStream.readBytes()
                                    val isPdfBytes = bytes.size > 4 && 
                                        bytes[0] == '%'.code.toByte() && 
                                        bytes[1] == 'P'.code.toByte() && 
                                        bytes[2] == 'D'.code.toByte() && 
                                        bytes[3] == 'F'.code.toByte()
                                    if (isPdfBytes) {
                                        val pdfFile = java.io.File(context.getExternalFilesDir("backend_data") ?: context.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                                        pdfFile.writeBytes(bytes)
                                        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                            viewModel.createNewDocument(cleanTitle, "pdf", pdfFile.absolutePath)
                                            Toast.makeText(context, "Successfully imported PDF $displayName", Toast.LENGTH_SHORT).show()
                                        }
                                        return@use
                                    } else {
                                        try {
                                            DocumentImportExportHelper.parseDocxText(java.io.ByteArrayInputStream(bytes))
                                        } catch (e: Exception) {
                                            DocumentImportExportHelper.prePaginateText(String(bytes, Charsets.UTF_8))
                                        }
                                    }
                                }
                            }

                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                if (importedText != null && importedText.isNotEmpty()) {
                                    viewModel.createNewDocument(cleanTitle, "word", importedText)
                                    Toast.makeText(context, "Successfully imported $displayName", Toast.LENGTH_SHORT).show()
                                } else {
                                    Toast.makeText(context, "Could not read text content from $displayName", Toast.LENGTH_SHORT).show()
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                        Toast.makeText(context, "Import failed: ${e.message}", Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
    }

    LaunchedEffect(activeTabState) {
        activeTab = activeTabState
    }

    LaunchedEffect(activeTab) {
        if (activeTab != activeTabState) {
            viewModel.changeActiveTab(activeTab)
        }
    }

    BackHandler(enabled = activeTab != "home" && !isSidebarExpanded) {
        activeTab = "home"
    }

    // Simulate username personalization in SQLite workspace
    val settingsContext = androidx.compose.ui.platform.LocalContext.current
    val settingsSharedPreferences = remember { settingsContext.getSharedPreferences("ai_agent_prefs", android.content.Context.MODE_PRIVATE) }
    var username by remember { mutableStateOf(settingsSharedPreferences.getString("username_key", "Chandan Kumar") ?: "Chandan Kumar") }
    var userRole by remember { mutableStateOf(settingsSharedPreferences.getString("user_role_key", "Lead Editor") ?: "Lead Editor") }

    // State to toggle mock collaboration notifications
    var showSimulatedStatus by remember { mutableStateOf(false) }
    var activeCollaborators by remember { mutableStateOf(7) }

    // State for selected file category inside Files tab
    var filesCategoryTab by remember { mutableStateOf("all") }
    var folderSelectedMenu by remember { mutableStateOf<String?>(null) }

    // Determine featured document (most recently updated/created document)
    val featuredDoc = remember(documents) {
        documents.maxByOrNull { it.updatedAt }
    }

    // SQLite data stats
    val totalFiles = documents.size
    val favoriteFiles = remember(documents) { documents.count { it.isFavorite } }
    val sheetsCount = remember(documents) { documents.count { it.type == "sheet" } }
    val writerCount = remember(documents) { documents.count { it.type == "word" } }
    val slidesCount = remember(documents) { documents.count { it.type == "slide" } }

    // We removed the custom visual permissions setup layout so that native dialogs prompt directly over the main UI instead.

    Column(
        modifier = modifier
            .fillMaxSize()
            .background(screenBgColor) // Matching design body background
    ) {
        // --- Greeting, Profile Header & Search Bar (Polished Mockup Design) ---
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 20.dp, end = 20.dp, top = 20.dp, bottom = 12.dp)
        ) {
            // Top Row: Hamburger, Greeting, Profile Badge + Arrow
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(
                    onClick = onToggleSidebar,
                    modifier = Modifier.size(48.dp)
                ) {
                    Icon(
                        imageVector = if (isSidebarExpanded) Icons.Outlined.Close else Icons.Outlined.Menu,
                        contentDescription = "Toggle Drawer Menu",
                        tint = textMainColor,
                        modifier = Modifier.size(28.dp)
                    )
                }

                Spacer(modifier = Modifier.width(12.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = when (activeTab) {
                            "files" -> "Files"
                            "shared" -> "Shared"
                            "trash" -> "Trash"
                            else -> "Hello, $username 👋"
                        },
                        style = MaterialTheme.typography.titleLarge.copy(
                            fontWeight = FontWeight.ExtraBold,
                            color = textMainColor,
                            fontSize = 22.sp,
                            letterSpacing = (-0.5).sp
                        ),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        if (activeTab != "files" && activeTab != "shared" && activeTab != "trash") {
                            Text(
                                text = "$userRole",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Medium,
                                color = textSubColor
                            )
                        }
                    }
                }

                // Profile Badge and Chevron Down
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.clickable { activeTab = "settings" }.padding(end = 4.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(42.dp)
                            .clip(CircleShape)
                            .background(Color(0xFF1E1B4B)), // Dark Navy background as seen in the blue badge "SA"
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = username.take(2).uppercase(),
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = Color.White,
                                fontSize = 15.sp
                            )
                        )
                    }
                    Spacer(modifier = Modifier.width(6.dp))
                    Icon(
                        imageVector = Icons.Default.KeyboardArrowDown,
                        contentDescription = "Profile dropdown",
                        tint = textSubColor,
                        modifier = Modifier.size(20.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Search Bar Row (Clean White/Gray Pill with Filter/Download Icons)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(44.dp)
                    .clip(RoundedCornerShape(12.dp))
                    .background(searchBgColor) // Match Light search panel background
                    .border(
                        width = 1.dp,
                        color = cardBorderColor,
                        shape = RoundedCornerShape(12.dp)
                    )
                    .padding(horizontal = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Outlined.Search,
                    contentDescription = "Search",
                    tint = textSubColor,
                    modifier = Modifier.size(18.dp)
                )
                
                Spacer(modifier = Modifier.width(8.dp))

                BasicTextField(
                    value = searchQuery,
                    onValueChange = { 
                        viewModel.setSearchQuery(it)
                        if (it.isNotEmpty() && activeTab != "files" && activeTab != "shared") {
                            activeTab = "files"
                        }
                    },
                    textStyle = MaterialTheme.typography.bodyLarge.copy(
                        color = textMainColor,
                        fontWeight = FontWeight.Medium,
                        fontSize = 13.sp
                    ),
                    singleLine = true,
                    modifier = Modifier.weight(1f),
                    decorationBox = { innerTextField ->
                        if (searchQuery.isEmpty()) {
                            Text(
                                text = when (activeTab) {
                                    "files" -> "Search files and folders..."
                                    "shared" -> "Search shared documents..."
                                    "trash" -> "Search deleted files..."
                                    else -> "Search JCDocs Suite..."
                                },
                                style = MaterialTheme.typography.bodyLarge,
                                fontSize = 13.sp,
                                color = textSubColor
                            )
                        }
                        innerTextField()
                    }
                )

                // Tune/Filters click option
                IconButton(
                    onClick = {
                        activeTab = "files"
                    },
                    modifier = Modifier.size(32.dp)
                ) {
                    Icon(
                        imageVector = Icons.Outlined.Tune,
                        contentDescription = "Search filters",
                        tint = textSubColor,
                        modifier = Modifier.size(18.dp)
                    )
                }
            }
        }

        // --- 2. Interactive Workspace Tabs ---
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
        ) {
            when (activeTab) {
                "home" -> {
                    val scrollState = rememberScrollState()
                    val homeContext = LocalContext.current
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(scrollState)
                            .padding(horizontal = 20.dp, vertical = 4.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        // 3. Mobius AI Card
                        Card(
                            onClick = {
                                onOpenAICopilot()
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            border = BorderStroke(1.dp, cardBorderColor),
                            colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1B1838) else Color(0xFFEEF2FF))
                        ) {
                            Row(
                                modifier = Modifier
                                    .padding(14.dp)
                                    .fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                // Draw a beautiful custom Mobius visual representation using canvas/boxes
                                Box(
                                    modifier = Modifier
                                        .size(42.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    // Overlapping circles gradient mimicking infinity/Mobius strip
                                    Canvas(modifier = Modifier.fillMaxSize()) {
                                        val p1 = center.copy(x = center.x - 8.dp.toPx())
                                        val p2 = center.copy(x = center.x + 8.dp.toPx())
                                        
                                        drawCircle(
                                            brush = Brush.linearGradient(listOf(Color(0xFF8B5CF6), Color(0xFF4F46E5))),
                                            radius = 15.dp.toPx(),
                                            center = p1,
                                            alpha = 0.8f
                                        )
                                        drawCircle(
                                            brush = Brush.linearGradient(listOf(Color(0xFF3B82F6), Color(0xFF8B5CF6))),
                                            radius = 15.dp.toPx(),
                                            center = p2,
                                            alpha = 0.8f
                                        )
                                    }
                                }

                                Column(modifier = Modifier.weight(1.2f)) {
                                    Text(
                                        text = "Mobius AI",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 15.sp,
                                        color = textMainColor
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text(
                                        text = "Edit, manage, analyze and do anything with your documents using AI.",
                                        fontSize = 12.sp,
                                        color = textSubColor,
                                        lineHeight = 16.sp,
                                        maxLines = 2,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                }

                                Button(
                                    onClick = { 
                                        onOpenAICopilot()
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF4F46E5)),
                                    shape = RoundedCornerShape(8.dp),
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp),
                                    modifier = Modifier.height(30.dp)
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.AutoAwesome, // Star/Sparkle AI icon
                                            contentDescription = null,
                                            tint = Color.White,
                                            modifier = Modifier.size(12.dp)
                                        )
                                        Text(
                                            "Ask Mobius",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color.White
                                        )
                                    }
                                }
                            }
                        }

                        // 2. Grid of 6 Quick-Access Cards
                        val gridData = listOf(
                            Triple("Recent Files", "Continue where you left off", Icons.Outlined.History to Color(0xFF3B82F6)),
                            Triple("Favorites", "View starred documents", Icons.Outlined.StarRate to Color(0xFFF59E0B)),
                            Triple("Shared with Me", "Files shared by your team", Icons.Outlined.People to Color(0xFF10B981)),
                            Triple("Offline Files", "Access files without internet", Icons.Outlined.CloudDownload to Color(0xFFEF4444)),
                            Triple("Trash", "Recently deleted documents", Icons.Outlined.DeleteOutline to Color(0xFF8B5CF6)),
                            Triple("Activity", "See recent workspace activity", Icons.Outlined.ShowChart to Color(0xFF06B6D4))
                        )

                        Column(
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            for (i in gridData.indices step 3) {
                                val firstItem = gridData[i]
                                val secondItem = gridData.getOrNull(i + 1)
                                val thirdItem = gridData.getOrNull(i + 2)
                                
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    listOfNotNull(firstItem, secondItem, thirdItem).forEach { item ->
                                        Card(
                                            onClick = {
                                                when (item.first) {
                                                    "Recent Files" -> {
                                                        activeTab = "files"
                                                        filesCategoryTab = "all"
                                                    }
                                                    "Shared with Me" -> activeTab = "shared"
                                                    "Trash" -> {
                                                        activeTab = "trash"
                                                    }
                                                    "Favorites" -> {
                                                        activeTab = "files"
                                                        filesCategoryTab = "all"
                                                    }
                                                    "Offline Files" -> {
                                                        activeTab = "files"
                                                    }
                                                    "Activity" -> {
                                                        activeTab = "shared"
                                                    }
                                                }
                                            },
                                            modifier = Modifier.weight(1f),
                                            shape = RoundedCornerShape(12.dp),
                                            colors = CardDefaults.cardColors(containerColor = cardBgColor),
                                            border = BorderStroke(1.dp, cardBorderColor)
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(10.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(34.dp)
                                                        .clip(RoundedCornerShape(8.dp))
                                                        .background(item.third.second.copy(alpha = 0.1f)),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Icon(
                                                        imageVector = item.third.first,
                                                        contentDescription = item.first,
                                                        tint = item.third.second,
                                                        modifier = Modifier.size(18.dp)
                                                    )
                                                }
                                                
                                                Spacer(modifier = Modifier.height(10.dp))
                                                
                                                Text(
                                                    text = item.first,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 12.sp,
                                                    color = textMainColor,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis
                                                )
                                                
                                                Spacer(modifier = Modifier.height(4.dp))
                                                
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(
                                                        text = item.second,
                                                        fontSize = 9.sp,
                                                        color = textSubColor,
                                                        maxLines = 2,
                                                        overflow = TextOverflow.Ellipsis,
                                                        lineHeight = 11.sp,
                                                        modifier = Modifier.weight(1f)
                                                    )
                                                    Spacer(modifier = Modifier.width(2.dp))
                                                    Icon(
                                                        imageVector = Icons.Outlined.ChevronRight,
                                                        contentDescription = null,
                                                        tint = textSubColor,
                                                        modifier = Modifier.size(12.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                    
                                    val rowItemCount = listOfNotNull(firstItem, secondItem, thirdItem).size
                                    if (rowItemCount < 3) {
                                        repeat(3 - rowItemCount) {
                                            Spacer(modifier = Modifier.weight(1f))
                                        }
                                    }
                                }
                            }
                        }


                        // 4. Recent Documents Section Header
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "Recent Documents",
                                fontWeight = FontWeight.ExtraBold,
                                fontSize = 18.sp,
                                color = textMainColor
                            )
                            Row(
                                modifier = Modifier.clickable { activeTab = "files" },
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(
                                    text = "View all",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isDark) Color(0xFF818CF8) else Color(0xFF4F46E5)
                                )
                                Icon(
                                    imageVector = Icons.Outlined.ChevronRight,
                                    contentDescription = null,
                                    tint = if (isDark) Color(0xFF818CF8) else Color(0xFF4F46E5),
                                    modifier = Modifier.size(16.dp)
                                )
                            }
                        }

                        // Recent Documents Dynamic List (taking up to 5 elements)
                        val recentDocs = remember(documents) {
                            documents.sortedByDescending { it.updatedAt }.take(5)
                        }

                        if (recentDocs.isEmpty()) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, cardBorderColor),
                                colors = CardDefaults.cardColors(containerColor = cardBgColor)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .padding(24.dp)
                                        .fillMaxWidth(),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = "No documents found. Click 'Create New' to start!",
                                        fontSize = 11.sp,
                                        color = textSubColor
                                    )
                                }
                            }
                        } else {
                            Column(
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                recentDocs.forEach { doc ->
                                    val formattedTime = remember(doc.updatedAt) {
                                        val diff = System.currentTimeMillis() - doc.updatedAt
                                        val mins = diff / (60 * 1000)
                                        val hours = mins / 60
                                        val days = hours / 24
                                        when {
                                            mins < 1 -> "Just now"
                                            mins < 60 -> "${mins}m ago"
                                            hours < 24 -> "${hours}h ago"
                                            else -> "${days}d ago"
                                        }
                                    }
                                    
                                    val docColor = when (doc.type) {
                                        "word" -> Color(0xFF2563EB) // Blue
                                        "sheet" -> Color(0xFF16A34A) // Green
                                        "pdf" -> Color(0xFFDC2626) // Red
                                        else -> Color(0xFFD97706) // Yellow/Orange
                                    }
                                    
                                    val typeIcon = when (doc.type) {
                                        "word" -> "W"
                                        "sheet" -> "X"
                                        "pdf" -> "PDF"
                                        else -> "P"
                                    }
                                    
                                    val typeLabelText = when (doc.type) {
                                        "word" -> "Docs"
                                        "sheet" -> "Excel"
                                        "pdf" -> "PDF"
                                        else -> "Slides"
                                    }
                                    
                                    val simulatedSizeText = remember(doc.id) {
                                        val sizeMb = 1.0 + (kotlin.math.abs(doc.id.hashCode()) % 40) / 10.0
                                        String.format("%.1f MB", sizeMb)
                                    }

                                    var showItemMenu by remember { mutableStateOf(false) }

                                    Card(
                                        onClick = { viewModel.selectDocument(doc) },
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(8.dp),
                                        colors = CardDefaults.cardColors(containerColor = cardBgColor),
                                        border = BorderStroke(1.dp, dividerColor1)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .padding(horizontal = 14.dp, vertical = 12.dp)
                                                .fillMaxWidth(),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            // Circular colored type icon (Matching W / X / PDF mockup style)
                                            Box(
                                                modifier = Modifier
                                                    .size(40.dp)
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(docColor),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = typeIcon,
                                                    fontSize = if (typeIcon == "PDF") 11.sp else 15.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = Color.White
                                                )
                                            }
                                            
                                            Spacer(modifier = Modifier.width(12.dp))
                                            
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = doc.title,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 15.sp,
                                                    color = textMainColor,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis
                                                )
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = "$typeLabelText • $simulatedSizeText",
                                                    fontSize = 12.sp,
                                                    color = textSubColor
                                                )
                                            }

                                            Text(
                                                text = formattedTime,
                                                fontSize = 12.sp,
                                                color = Color(0xFF94A3B8)
                                            )
                                            
                                            Spacer(modifier = Modifier.width(6.dp))
                                            
                                            Box {
                                                IconButton(
                                                    onClick = { showItemMenu = true },
                                                    modifier = Modifier.size(40.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.MoreVert,
                                                        contentDescription = "Options",
                                                        tint = textSubColor,
                                                        modifier = Modifier.size(22.dp)
                                                    )
                                                }
                                                
                                                DropdownMenu(
                                                    expanded = showItemMenu,
                                                    onDismissRequest = { showItemMenu = false },
                                                    modifier = Modifier.background(cardBgColor)
                                                ) {
                                                    DropdownMenuItem(
                                                        text = { Text("Delete Document", fontSize = 14.sp, color = Color.Red) },
                                                        onClick = {
                                                            showItemMenu = false
                                                            viewModel.deleteDocument(doc)
                                                        }
                                                    )
                                                    DropdownMenuItem(
                                                        text = { Text(if (doc.isFavorite) "Unfavorite" else "Favorite", fontSize = 14.sp, color = textMainColor) },
                                                        onClick = {
                                                            showItemMenu = false
                                                            viewModel.toggleFavorite(doc)
                                                        }
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Bottom Spacer to scroll nicely above static bottom navigation
                        Spacer(modifier = Modifier.height(140.dp))
                    }
                }
                "files" -> {
                    // Modern styled adaptive Files tab screen matching Mockup CSS exactly
                    val filesContext = LocalContext.current
                    val filesScope = rememberCoroutineScope()
                    val foldersStateList by viewModel.allFolders.collectAsStateWithLifecycle()
                    val favoriteFoldersSet by viewModel.favoriteFolders.collectAsStateWithLifecycle()
                    
                    // State variables for Files section
                    var selectedCategoryTab by remember { mutableStateOf("All Files") }
                    val categoryTabs = listOf("All Files", "Folders", "Recent", "Favorites", "Offline")
                    
                    var isGridView by remember { mutableStateOf(false) }
                    var sortByField by remember { mutableStateOf("Name") }

                    var showCreateFolderDialog by remember { mutableStateOf(false) }
                    var folderToCreateName by remember { mutableStateOf("") }
                    
                    var docToMoveToFolder by remember { mutableStateOf<DocEntity?>(null) }
                    var showMoveFolderDialog by remember { mutableStateOf(false) }
                    
                    var selectedFolderFilter by remember { mutableStateOf<String?>(null) }

                    // Dialog states for renaming files and folders
                    var showRenameFolderDialog by remember { mutableStateOf(false) }
                    var folderToRenameOldName by remember { mutableStateOf("") }
                    var folderToRenameNewName by remember { mutableStateOf("") }

                    var showRenameDocDialog by remember { mutableStateOf(false) }
                    var docToRename by remember { mutableStateOf<DocEntity?>(null) }
                    var docToRenameNewTitle by remember { mutableStateOf("") }

                    val uploadLauncher = rememberLauncherForActivityResult(
                        contract = ActivityResultContracts.OpenDocument()
                    ) { uri ->
                        uri?.let { fileUri ->
                            filesScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                                try {
                                    val contentResolver = filesContext.contentResolver
                                    var fileName = ""
                                    try {
                                        contentResolver.query(fileUri, null, null, null, null)?.use { cursor ->
                                            val nameId = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                                            if (nameId != -1 && cursor.moveToFirst()) {
                                                fileName = cursor.getString(nameId)
                                            }
                                        }
                                    } catch (e: Exception) {
                                        e.printStackTrace()
                                    }
                                    if (fileName.isEmpty()) {
                                        fileName = fileUri.lastPathSegment ?: "Uploaded Document"
                                    }

                                    val isPdf = fileName.lowercase().endsWith(".pdf") || contentResolver.getType(fileUri) == "application/pdf"
                                    val isDocx = fileName.lowercase().endsWith(".docx") || contentResolver.getType(fileUri) == "application/vnd.openxmlformats-officedocument.wordprocessingml.document"

                                    val cleanedTitle = fileName.substringBeforeLast(".")

                                    if (isPdf) {
                                        try {
                                            val pdfFile = java.io.File(filesContext.getExternalFilesDir("backend_data") ?: filesContext.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                                            contentResolver.openInputStream(fileUri)?.use { inputStream ->
                                                pdfFile.outputStream().use { output ->
                                                    inputStream.copyTo(output)
                                                }
                                            }
                                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                viewModel.createNewDocument(
                                                    title = cleanedTitle,
                                                    type = "pdf",
                                                    initialContent = pdfFile.absolutePath,
                                                    folderName = selectedFolderFilter
                                                )
                                                Toast.makeText(filesContext, "Successfully uploaded PDF: $fileName", Toast.LENGTH_SHORT).show()
                                            }
                                        } catch (e: Exception) {
                                            e.printStackTrace()
                                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                Toast.makeText(filesContext, "Failed to save PDF: ${e.message}", Toast.LENGTH_SHORT).show()
                                            }
                                        }
                                    } else {
                                        contentResolver.openInputStream(fileUri)?.use { inputStream ->
                                            val textContent = if (isDocx) {
                                                DocumentImportExportHelper.parseDocxText(inputStream)
                                            } else {
                                                val bytes = inputStream.readBytes()
                                                val isPdfBytes = bytes.size > 4 && 
                                                    bytes[0] == '%'.code.toByte() && 
                                                    bytes[1] == 'P'.code.toByte() && 
                                                    bytes[2] == 'D'.code.toByte() && 
                                                    bytes[3] == 'F'.code.toByte()
                                                if (isPdfBytes) {
                                                    val pdfFile = java.io.File(filesContext.getExternalFilesDir("backend_data") ?: filesContext.filesDir, "pdf_${System.currentTimeMillis()}.pdf")
                                                    pdfFile.writeBytes(bytes)
                                                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                        viewModel.createNewDocument(
                                                            title = cleanedTitle,
                                                            type = "pdf",
                                                            initialContent = pdfFile.absolutePath,
                                                            folderName = selectedFolderFilter
                                                        )
                                                        Toast.makeText(filesContext, "Successfully uploaded PDF: $fileName", Toast.LENGTH_SHORT).show()
                                                    }
                                                    return@use
                                                } else {
                                                    try {
                                                        DocumentImportExportHelper.parseDocxText(java.io.ByteArrayInputStream(bytes))
                                                    } catch (e: Exception) {
                                                        DocumentImportExportHelper.prePaginateText(String(bytes, Charsets.UTF_8))
                                                    }
                                                }
                                            }

                                            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                if (textContent != null) {
                                                    viewModel.createNewDocument(
                                                        title = cleanedTitle,
                                                        type = "word",
                                                        initialContent = textContent,
                                                        folderName = selectedFolderFilter
                                                    )
                                                    Toast.makeText(filesContext, "Successfully uploaded: $fileName", Toast.LENGTH_SHORT).show()
                                                } else {
                                                    Toast.makeText(filesContext, "Could not extract text content from $fileName", Toast.LENGTH_SHORT).show()
                                                }
                                            }
                                        }
                                    }
                                } catch (e: Exception) {
                                    e.printStackTrace()
                                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                        Toast.makeText(filesContext, "Failed to upload file: ${e.message}", Toast.LENGTH_LONG).show()
                                    }
                                }
                            }
                        }
                    }

                    if (showCreateFolderDialog) {
                        AlertDialog(
                            onDismissRequest = { showCreateFolderDialog = false },
                            title = { Text("Create New Folder", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
                            text = {
                                Column {
                                    Text("Enter folder name:", fontSize = 14.sp, color = Color.Gray)
                                    Spacer(modifier = Modifier.height(8.dp))
                                    OutlinedTextField(
                                        value = folderToCreateName,
                                        onValueChange = { folderToCreateName = it },
                                        placeholder = { Text("e.g. Invoices") },
                                        singleLine = true,
                                        modifier = Modifier.fillMaxWidth()
                                    )
                                }
                            },
                            confirmButton = {
                                Button(
                                    onClick = {
                                        if (folderToCreateName.isNotBlank()) {
                                            viewModel.createFolder(folderToCreateName.trim())
                                            Toast.makeText(filesContext, "Folder '${folderToCreateName.trim()}' created", Toast.LENGTH_SHORT).show()
                                            folderToCreateName = ""
                                            showCreateFolderDialog = false
                                        }
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                                ) {
                                    Text("Create")
                                }
                            },
                            dismissButton = {
                                TextButton(onClick = { showCreateFolderDialog = false }) {
                                    Text("Cancel", color = Color.Gray)
                                }
                            }
                        )
                    }

                    if (showRenameFolderDialog) {
                        AlertDialog(
                            onDismissRequest = { showRenameFolderDialog = false },
                            title = { Text("Rename Folder", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
                            text = {
                                Column {
                                    Text("Enter new name for folder '$folderToRenameOldName':", fontSize = 14.sp, color = Color.Gray)
                                    Spacer(modifier = Modifier.height(8.dp))
                                    OutlinedTextField(
                                        value = folderToRenameNewName,
                                        onValueChange = { folderToRenameNewName = it },
                                        placeholder = { Text("New Folder Name") },
                                        singleLine = true,
                                        modifier = Modifier.fillMaxWidth()
                                    )
                                }
                            },
                            confirmButton = {
                                Button(
                                    onClick = {
                                        if (folderToRenameNewName.isNotBlank()) {
                                            viewModel.renameFolder(folderToRenameOldName, folderToRenameNewName.trim())
                                            Toast.makeText(filesContext, "Folder renamed to '${folderToRenameNewName.trim()}'", Toast.LENGTH_SHORT).show()
                                            showRenameFolderDialog = false
                                        }
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                                ) {
                                    Text("Rename")
                                }
                            },
                            dismissButton = {
                                TextButton(onClick = { showRenameFolderDialog = false }) {
                                    Text("Cancel", color = Color.Gray)
                                }
                            }
                        )
                    }

                    if (showRenameDocDialog && docToRename != null) {
                        AlertDialog(
                            onDismissRequest = { showRenameDocDialog = false },
                            title = { Text("Rename File", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
                            text = {
                                Column {
                                    Text("Enter new title for '${docToRename?.title}':", fontSize = 14.sp, color = Color.Gray)
                                    Spacer(modifier = Modifier.height(8.dp))
                                    OutlinedTextField(
                                        value = docToRenameNewTitle,
                                        onValueChange = { docToRenameNewTitle = it },
                                        placeholder = { Text("New Title") },
                                        singleLine = true,
                                        modifier = Modifier.fillMaxWidth()
                                    )
                                }
                            },
                            confirmButton = {
                                Button(
                                    onClick = {
                                        if (docToRenameNewTitle.isNotBlank()) {
                                            docToRename?.let { doc ->
                                                viewModel.renameDocument(doc, docToRenameNewTitle.trim())
                                                Toast.makeText(filesContext, "File renamed to '${docToRenameNewTitle.trim()}'", Toast.LENGTH_SHORT).show()
                                            }
                                            showRenameDocDialog = false
                                        }
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0))
                                ) {
                                    Text("Rename")
                                }
                            },
                            dismissButton = {
                                TextButton(onClick = { showRenameDocDialog = false }) {
                                    Text("Cancel", color = Color.Gray)
                                }
                            }
                        )
                    }

                    if (showMoveFolderDialog && docToMoveToFolder != null) {
                        val foldersList = foldersStateList
                        AlertDialog(
                            onDismissRequest = { showMoveFolderDialog = false },
                            title = { Text("Organize File: ${docToMoveToFolder?.title}", fontWeight = FontWeight.Bold, fontSize = 16.sp) },
                            text = {
                                Column {
                                    Text("Move to a folder:", fontSize = 14.sp, color = Color.Gray)
                                    Spacer(modifier = Modifier.height(12.dp))
                                    
                                    // Option to clear folder
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable {
                                                docToMoveToFolder?.let { viewModel.updateDocumentFolder(it, null) }
                                                showMoveFolderDialog = false
                                                Toast.makeText(filesContext, "Removed from folder", Toast.LENGTH_SHORT).show()
                                            }
                                            .padding(vertical = 10.dp, horizontal = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(Icons.Outlined.Folder, contentDescription = null, tint = Color.Gray, modifier = Modifier.size(20.dp))
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Text("None (Root)", fontSize = 14.sp, fontWeight = FontWeight.Medium)
                                    }
                                    
                                    LazyColumn(
                                        modifier = Modifier.heightIn(max = 200.dp)
                                    ) {
                                        items(foldersList) { fName ->
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .clickable {
                                                        docToMoveToFolder?.let { viewModel.updateDocumentFolder(it, fName) }
                                                        showMoveFolderDialog = false
                                                        Toast.makeText(filesContext, "Moved to '$fName'", Toast.LENGTH_SHORT).show()
                                                    }
                                                    .padding(vertical = 10.dp, horizontal = 4.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Icon(Icons.Filled.Folder, contentDescription = null, tint = Color(0xFFFBBF24), modifier = Modifier.size(20.dp))
                                                Spacer(modifier = Modifier.width(12.dp))
                                                Text(fName, fontSize = 14.sp, fontWeight = FontWeight.Medium)
                                            }
                                        }
                                    }
                                }
                            },
                            confirmButton = {},
                            dismissButton = {
                                TextButton(onClick = { showMoveFolderDialog = false }) {
                                    Text("Cancel", color = Color.Gray)
                                }
                            }
                        )
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(horizontal = 16.dp)
                    ) {
                        LazyColumn(
                            modifier = Modifier
                                .fillMaxSize(),
                            verticalArrangement = Arrangement.spacedBy(12.dp),
                            contentPadding = PaddingValues(bottom = 140.dp)
                        ) {
                            // --- 1. Storage Usage Card ---
                            item {
                                val filesAppStorageUsed = remember(documents) { getAppStorageUsed(filesContext) }
                                val totalFilesDiskStorage = getTotalDiskStorage()
                                val filesProgressFraction = if (filesAppStorageUsed > 0 && totalFilesDiskStorage > 0) {
                                    (filesAppStorageUsed.toFloat() / totalFilesDiskStorage).coerceIn(0.0001f..1.0f)
                                } else {
                                    0.02f
                                }
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1C1A38) else Color(0xFFF5F3FF)), // Light purple/lavender background
                                    border = BorderStroke(1.dp, cardBorderColor),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(horizontal = 12.dp, vertical = 10.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        // Light purple folder badge
                                        Box(
                                            modifier = Modifier
                                                .size(36.dp)
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(if (isDark) Color(0xFF2C255F) else Color(0xFFEBE9FE)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Box(contentAlignment = Alignment.Center) {
                                                Icon(
                                                    imageVector = Icons.Outlined.Folder,
                                                    contentDescription = "Storage",
                                                    tint = if (isDark) Color(0xFF818CF8) else Color(0xFF7C3AED),
                                                    modifier = Modifier.size(20.dp)
                                                )
                                                // Small disk overlay badge
                                                Box(
                                                    modifier = Modifier
                                                        .size(8.dp)
                                                        .background(if (isDark) Color(0xFF818CF8) else Color(0xFF8B5CF6), CircleShape)
                                                        .align(Alignment.BottomEnd)
                                                )
                                            }
                                        }
                                        Spacer(modifier = Modifier.width(12.dp))
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(
                                                text = "Storage",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 13.sp,
                                                color = textMainColor
                                            )
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(
                                                text = "${formatStorageSize(filesAppStorageUsed)} of ${formatStorageSize(totalFilesDiskStorage)} used",
                                                fontSize = 11.sp,
                                                color = textSubColor
                                            )
                                            Spacer(modifier = Modifier.height(6.dp))
                                            // Progress bar indicator
                                            LinearProgressIndicator(
                                                progress = filesProgressFraction,
                                                color = if (isDark) Color(0xFF818CF8) else Color(0xFF7C3AED),
                                                trackColor = if (isDark) Color(0xFF2A2A35) else Color(0xFFEDE9FE),
                                                strokeCap = StrokeCap.Round,
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .height(4.dp)
                                             )
                                        }
                                        Spacer(modifier = Modifier.width(10.dp))
                                        Text(
                                            text = "View details",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isDark) Color(0xFF818CF8) else Color(0xFF7C3AED),
                                            modifier = Modifier.clickable {
                                                Toast.makeText(filesContext, "Opening detailed storage breakdown...", Toast.LENGTH_SHORT).show()
                                            }
                                        )
                                        Icon(
                                            imageVector = Icons.Outlined.ChevronRight,
                                            contentDescription = "Details",
                                            tint = if (isDark) Color(0xFF818CF8) else Color(0xFF7C3AED),
                                            modifier = Modifier.size(14.dp)
                                        )
                                    }
                                }
                            }

                            // --- 2. Category Tabs Row ---
                            item {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .horizontalScroll(rememberScrollState())
                                        .padding(vertical = 8.dp),
                                    horizontalArrangement = Arrangement.spacedBy(20.dp)
                                ) {
                                    categoryTabs.forEach { tab ->
                                        val isSelected = selectedCategoryTab == tab
                                        Column(
                                            modifier = Modifier
                                                .clickable { selectedCategoryTab = tab }
                                                .padding(horizontal = 4.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally
                                        ) {
                                            Text(
                                                text = tab,
                                                fontSize = 14.sp,
                                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                                color = if (isSelected) (if (isDark) Color(0xFF818CF8) else Color(0xFF5B2BE0)) else textSubColor
                                            )
                                            Spacer(modifier = Modifier.height(6.dp))
                                            if (isSelected) {
                                                Box(
                                                    modifier = Modifier
                                                        .height(3.dp)
                                                        .width(44.dp)
                                                        .background(if (isDark) Color(0xFF818CF8) else Color(0xFF5B2BE0), RoundedCornerShape(100.dp))
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            // --- 3. Quick Action Colorful Tiles ---
                            item {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .horizontalScroll(rememberScrollState())
                                        .padding(vertical = 8.dp),
                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    val quickActions = listOf(
                                        Triple("New Folder", Icons.Outlined.NoteAdd, Color(0xFFF5F3FF) to Color(0xFF7C3AED)),
                                        Triple("Upload File", Icons.Outlined.FileDownload, Color(0xFFF0F9FF) to Color(0xFF0284C7)),
                                        Triple("Add to Favorites", Icons.Outlined.StarBorder, Color(0xFFFEF3C7) to Color(0xFFD97706))
                                    )
                                    quickActions.forEach { (label, icon, colors) ->
                                        val (bg, fg) = colors
                                        Card(
                                            modifier = Modifier
                                                .width(108.dp)
                                                .height(94.dp),
                                            shape = RoundedCornerShape(16.dp),
                                            colors = CardDefaults.cardColors(containerColor = bg),
                                            onClick = {
                                                if (label == "New Folder") {
                                                    folderToCreateName = ""
                                                    showCreateFolderDialog = true
                                                } else if (label == "Upload File") {
                                                    try {
                                                        uploadLauncher.launch(arrayOf("*/*"))
                                                    } catch (e: Exception) {
                                                        Toast.makeText(filesContext, "Could not open file picker", Toast.LENGTH_SHORT).show()
                                                    }
                                                } else if (label == "Add to Favorites") {
                                                    selectedCategoryTab = "Favorites"
                                                }
                                            }
                                        ) {
                                            Column(
                                                modifier = Modifier
                                                    .fillMaxSize()
                                                    .padding(8.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.Center
                                            ) {
                                                Icon(
                                                    imageVector = icon,
                                                    contentDescription = label,
                                                    tint = fg,
                                                    modifier = Modifier.size(24.dp)
                                                )
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color(0xFF1E293B),
                                                    maxLines = 2,
                                                    textAlign = TextAlign.Center,
                                                    lineHeight = 12.sp
                                                )
                                            }
                                        }
                                    }
                                }
                            }

                            // --- 4. Filtering, Sorting, and List/Grid switcher ---
                            item {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(top = 12.dp, bottom = 4.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.clickable {
                                            sortByField = if (sortByField == "Name") "Recent" else "Name"
                                        }
                                    ) {
                                        Text(
                                            text = "Sort by: ",
                                            fontSize = 12.sp,
                                            color = Color(0xFF64748B)
                                        )
                                        Text(
                                            text = sortByField,
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF5B2BE0)
                                        )
                                        Icon(
                                            imageVector = Icons.Default.KeyboardArrowDown,
                                            contentDescription = "Sort Dropdown",
                                            tint = Color(0xFF5B2BE0),
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.ViewAgenda, // list icon
                                            contentDescription = "List View",
                                            tint = if (!isGridView) Color(0xFF5B2BE0) else Color(0xFF94A3B8),
                                            modifier = Modifier
                                                .size(24.dp)
                                                .clickable { isGridView = false }
                                        )
                                        Icon(
                                            imageVector = Icons.Outlined.Category, // grid representation
                                            contentDescription = "Grid View",
                                            tint = if (isGridView) Color(0xFF5B2BE0) else Color(0xFF94A3B8),
                                            modifier = Modifier
                                                .size(24.dp)
                                                .clickable { isGridView = true }
                                        )
                                    }
                                 }
                             }
                             // --- 5. Data elements mapping (Folders + Real database documents) ---
                             // Already declared at top-level Composable
                            val dynamicFolders = foldersStateList.filter { fName ->
                                val matchesSearch = searchQuery.isEmpty() || fName.contains(searchQuery, ignoreCase = true)
                                val matchesCategory = selectedCategoryTab != "Favorites" || favoriteFoldersSet.contains(fName)
                                matchesSearch && matchesCategory
                            }.map { fName ->
                                val docCount = documents.count { it.folderName == fName }
                                val lastUpdatedDoc = documents.filter { it.folderName == fName }.maxByOrNull { it.updatedAt }
                                val folderTimeText = if (lastUpdatedDoc != null) {
                                    val diff = System.currentTimeMillis() - lastUpdatedDoc.updatedAt
                                    if (diff < 60_000) "Just now"
                                    else if (diff < 3600_000) "${diff / 60_000}m ago"
                                    else if (diff < 86400_000) "${diff / 3600_000}h ago"
                                    else "${diff / 86400_000}d ago"
                                } else {
                                    "Empty"
                                }
                                var colors = if (isDark) {
                                    when (fName.hashCode() % 3) {
                                        0 -> Color(0xFFFCD34D) to Color(0xFF3E2B00) // Dark Yellow
                                        1 -> Color(0xFF34D399) to Color(0xFF063A25) // Dark Green
                                        else -> Color(0xFF60A5FA) to Color(0xFF132A55) // Dark Blue
                                    }
                                } else {
                                    when (fName.hashCode() % 3) {
                                        0 -> Color(0xFFFBBF24) to Color(0xFFFEF3C7) // Yellow
                                        1 -> Color(0xFF10B981) to Color(0xFFD1FAE5) // Green
                                        else -> Color(0xFF3B82F6) to Color(0xFFDBEAFE) // Blue
                                    }
                                }
                                Triple(fName, colors, docCount to folderTimeText)
                            }

                            // Determine actual database documents list based on Category tab selected and folder filter
                            val filteredDbDocs = documents.filter { doc ->
                                val matchesSearch = searchQuery.isEmpty() || doc.title.contains(searchQuery, ignoreCase = true)
                                val matchesCategory = when (selectedCategoryTab) {
                                    "Favorites" -> doc.isFavorite
                                    "Folders" -> false // Folders tab only shows simulated/real directory folders
                                    "Offline" -> true // Simulated offline mode displays documents too
                                    else -> true
                                }
                                val matchesFolder = if (selectedFolderFilter != null) {
                                    doc.folderName == selectedFolderFilter
                                } else {
                                    true
                                }
                                matchesSearch && matchesCategory && matchesFolder
                            }.let { list ->
                                // Apply Sorting
                                if (sortByField == "Name") {
                                    list.sortedBy { it.title.lowercase() }
                                } else {
                                    list.sortedByDescending { it.updatedAt }
                                }
                            }

                            // Optional folder breadcrumbs bar at the top of listings
                            if (selectedFolderFilter != null) {
                                item {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clip(RoundedCornerShape(8.dp))
                                            .background(if (isDark) Color(0xFF1E1B4B) else Color(0xFFEDE9FE))
                                            .padding(horizontal = 12.dp, vertical = 6.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(
                                                imageVector = Icons.Filled.Folder,
                                                contentDescription = null,
                                                tint = if (isDark) Color(0xFF818CF8) else Color(0xFF7C3AED),
                                                modifier = Modifier.size(16.dp)
                                            )
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text(
                                                text = "Folder: $selectedFolderFilter",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                color = if (isDark) Color.White else Color(0xFF4C1D95)
                                            )
                                        }
                                        Icon(
                                            imageVector = Icons.Default.Close,
                                            contentDescription = "Clear folder filter",
                                            tint = if (isDark) Color.White else Color(0xFF4C1D95),
                                            modifier = Modifier
                                                .size(16.dp)
                                                .clickable { selectedFolderFilter = null }
                                        )
                                    }
                                }
                            }

                            // Display directories/folders if "Folders" or "All Files" or "Favorites" tab is selected
                            if (selectedFolderFilter == null && (selectedCategoryTab == "All Files" || selectedCategoryTab == "Folders" || selectedCategoryTab == "Favorites")) {
                                items(dynamicFolders) { (folderName, colors, stats) ->
                                    val (folderIconColor, folderBgColor) = colors
                                    val (folderItems, folderTime) = stats
                                    
                                    if (isGridView) {
                                        // Grid item layout is not shown in mock folders for simplicity, fallback to standard list or tiny folder card
                                    } else {
                                        // Precise Folder List Item Design matching screenshots
                                        val isFolderFavorite = favoriteFoldersSet.contains(folderName)
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable {
                                                    selectedFolderFilter = folderName
                                                    Toast.makeText(filesContext, "Opening folder $folderName...", Toast.LENGTH_SHORT).show()
                                                }
                                                .padding(vertical = 8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .clip(RoundedCornerShape(10.dp))
                                                    .background(folderBgColor),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.Folder,
                                                    contentDescription = "Folder $folderName",
                                                    tint = folderIconColor,
                                                    modifier = Modifier.size(24.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(16.dp))
                                            Column(modifier = Modifier.weight(1f)) {
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(
                                                        text = folderName,
                                                        fontWeight = FontWeight.Bold,
                                                        fontSize = 15.sp,
                                                        color = textMainColor
                                                    )
                                                    if (isFolderFavorite) {
                                                        Spacer(modifier = Modifier.width(6.dp))
                                                        Icon(
                                                            imageVector = Icons.Filled.Star,
                                                            contentDescription = "Starred Folder",
                                                            tint = if (isDark) Color(0xFFFCD34D) else Color(0xFF5B2BE0),
                                                            modifier = Modifier.size(14.dp)
                                                        )
                                                    }
                                                }
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = "Folder • $folderItems items",
                                                    fontSize = 12.sp,
                                                    color = textSubColor
                                                )
                                            }
                                            Text(
                                                text = folderTime,
                                                fontSize = 12.sp,
                                                color = textSubColor
                                            )
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Box {
                                                Icon(
                                                    imageVector = Icons.Outlined.MoreVert,
                                                    contentDescription = "Folder options",
                                                    tint = textSubColor,
                                                    modifier = Modifier
                                                        .size(20.dp)
                                                        .clickable { folderSelectedMenu = folderName }
                                                )
                                                DropdownMenu(
                                                    expanded = folderSelectedMenu == folderName,
                                                    onDismissRequest = { folderSelectedMenu = null },
                                                    modifier = Modifier.background(cardBgColor)
                                                ) {
                                                    DropdownMenuItem(
                                                        onClick = {
                                                            folderSelectedMenu = null
                                                            viewModel.toggleFolderFavorite(folderName)
                                                            Toast.makeText(filesContext, if (isFolderFavorite) "Removed '$folderName' from Favorites" else "Added '$folderName' to Favorites", Toast.LENGTH_SHORT).show()
                                                        },
                                                        text = { Text(if (isFolderFavorite) "Remove from Favorites" else "Add to Favorites", fontSize = 14.sp, color = textMainColor) }
                                                    )
                                                    DropdownMenuItem(
                                                        onClick = {
                                                            folderSelectedMenu = null
                                                            folderToRenameOldName = folderName
                                                            folderToRenameNewName = folderName
                                                            showRenameFolderDialog = true
                                                        },
                                                        text = { Text("Rename Folder", fontSize = 14.sp, color = textMainColor) }
                                                    )
                                                    DropdownMenuItem(
                                                        onClick = {
                                                            folderSelectedMenu = null
                                                            viewModel.deleteFolderEntirely(folderName)
                                                            Toast.makeText(filesContext, "Moved folder '$folderName' and its documents to Trash", Toast.LENGTH_LONG).show()
                                                        },
                                                        text = { Text("Delete Folder", color = Color.Red, fontSize = 14.sp) }
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            // Display actual database documents
                            if (filteredDbDocs.isEmpty() && (!dynamicFolders.isNotEmpty() || selectedFolderFilter != null || (selectedCategoryTab != "All Files" && selectedCategoryTab != "Folders"))) {
                                item {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 48.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Outlined.Folder,
                                            contentDescription = "Empty",
                                            tint = Color.LightGray,
                                            modifier = Modifier.size(44.dp)
                                        )
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Text(
                                            text = "No files found",
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = Color.Gray
                                        )
                                    }
                                }
                            } else {
                                if (isGridView) {
                                    // Custom Grid layout view representation
                                    item {
                                        Column(
                                            modifier = Modifier.fillMaxWidth(),
                                            verticalArrangement = Arrangement.spacedBy(12.dp)
                                        ) {
                                            val chunks = filteredDbDocs.chunked(3)
                                            chunks.forEach { chunk ->
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                                ) {
                                                    chunk.forEach { doc ->
                                                        val typeColor = when (doc.type) {
                                                            "word" -> Color(0xFF1B63C1)
                                                            "sheet" -> Color(0xFF107C41)
                                                            "slide" -> Color(0xFFC43E1C)
                                                            else -> Color(0xFFE11D48)
                                                        }
                                                        val typeIconText = when (doc.type) {
                                                            "word" -> "W"
                                                            "sheet" -> "X"
                                                            "slide" -> "P"
                                                            else -> "PDF"
                                                        }
                                                        Card(
                                                            modifier = Modifier
                                                                .weight(1f)
                                                                .clickable { viewModel.selectDocument(doc) },
                                                            shape = RoundedCornerShape(12.dp),
                                                            colors = CardDefaults.cardColors(containerColor = cardBgColor),
                                                            border = BorderStroke(1.dp, cardBorderColor)
                                                        ) {
                                                            Column(
                                                                modifier = Modifier.padding(12.dp),
                                                                horizontalAlignment = Alignment.CenterHorizontally
                                                            ) {
                                                                Box(
                                                                    modifier = Modifier
                                                                        .size(40.dp)
                                                                        .clip(RoundedCornerShape(8.dp))
                                                                        .background(typeColor),
                                                                    contentAlignment = Alignment.Center
                                                                ) {
                                                                    Text(
                                                                        text = typeIconText,
                                                                        color = Color.White,
                                                                        fontWeight = FontWeight.Bold,
                                                                        fontSize = 14.sp
                                                                    )
                                                                }
                                                                Spacer(modifier = Modifier.height(8.dp))
                                                                Text(
                                                                    text = doc.title,
                                                                    fontWeight = FontWeight.Bold,
                                                                    fontSize = 12.sp,
                                                                    maxLines = 1,
                                                                    overflow = TextOverflow.Ellipsis,
                                                                    color = textMainColor
                                                                )
                                                            }
                                                        }
                                                    }
                                                    // Add spacers for unfilled grid spots
                                                    repeat(3 - chunk.size) {
                                                        Spacer(modifier = Modifier.weight(1f))
                                                    }
                                                }
                                            }
                                        }
                                    }
                                } else {
                                    // Beautiful list view matching Mockup
                                    items(filteredDbDocs, key = { it.id }) { doc ->
                                        val isSelected = featuredDoc?.id == doc.id
                                        
                                        // Determine file type styling matching office suite
                                        val typeColor = when (doc.type) {
                                            "word" -> Color(0xFF1B63C1) // Royal Blue Word
                                            "sheet" -> Color(0xFF107C41) // Emerald Green Excel
                                            "slide" -> Color(0xFFC43E1C) // Powerpoint Orange
                                            else -> Color(0xFFE11D48) // PDF Red
                                        }
                                        val typeLabel = when (doc.type) {
                                            "word" -> "Docs"
                                            "sheet" -> "Excel"
                                            "slide" -> "Slides"
                                            else -> "PDF"
                                        }
                                        val typeIconText = when (doc.type) {
                                            "word" -> "W"
                                            "sheet" -> "X"
                                            "slide" -> "P"
                                            else -> "PDF"
                                        }

                                        // Beautiful formatted time difference
                                        val docTimeAgo = remember(doc.updatedAt) {
                                            val diff = System.currentTimeMillis() - doc.updatedAt
                                            if (diff < 60_000) "Just now"
                                            else if (diff < 3600_000) "${diff / 60_000}m ago"
                                            else if (diff < 86400_000) "${diff / 3600_000}h ago"
                                            else "${diff / 86400_000}d ago"
                                        }

                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { viewModel.selectDocument(doc) }
                                                .padding(vertical = 8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            // Office App styled square icon badge
                                            Box(
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .clip(RoundedCornerShape(8.dp))
                                                    .background(typeColor),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = typeIconText,
                                                    color = Color.White,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 14.sp
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(16.dp))
                                            Column(modifier = Modifier.weight(1f)) {
                                                val displayName = if (doc.title.contains(".")) doc.title else when(doc.type) {
                                                    "word" -> "${doc.title}.docx"
                                                    "sheet" -> "${doc.title}.xlsx"
                                                    "slide" -> "${doc.title}.pptx"
                                                    else -> "${doc.title}.pdf"
                                                }
                                                Text(
                                                    text = displayName,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 15.sp,
                                                    color = textMainColor
                                                )
                                                Spacer(modifier = Modifier.height(2.dp))
                                                Text(
                                                    text = "$typeLabel • ${formatStorageSize(doc.content.length.toLong())}",
                                                    fontSize = 12.sp,
                                                    color = textSubColor
                                                )
                                            }

                                            if (doc.isFavorite) {
                                                Icon(
                                                    imageVector = Icons.Filled.Star,
                                                    contentDescription = "Starred Document",
                                                    tint = if (isDark) Color(0xFFFCD34D) else Color(0xFF5B2BE0), // Purple star icon matches mockup color schemes
                                                    modifier = Modifier
                                                        .size(16.dp)
                                                        .padding(end = 4.dp)
                                                )
                                            }

                                            Text(
                                                text = docTimeAgo,
                                                fontSize = 12.sp,
                                                color = textSubColor
                                            )
                                            Spacer(modifier = Modifier.width(8.dp))
                                            
                                            // Options drop-menu trigger
                                            Box {
                                                var optExpanded by remember { mutableStateOf(false) }
                                                IconButton(
                                                    onClick = { optExpanded = true },
                                                    modifier = Modifier.size(36.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Outlined.MoreVert,
                                                        contentDescription = "Doc Actions",
                                                        tint = textSubColor,
                                                        modifier = Modifier.size(20.dp)
