                    val foldersStateList by viewModel.allFolders.collectAsStateWithLifecycle()
                    val deletedCustomFoldersState by viewModel.deletedCustomFolders.collectAsStateWithLifecycle()
                    
                    val deletedFolders = remember(deletedDocs, foldersStateList, deletedCustomFoldersState) {
                        val foldersFromDocs = deletedDocs.mapNotNull { it.folderName }.filter { it.isNotBlank() && !foldersStateList.contains(it) }
                        (foldersFromDocs + deletedCustomFoldersState).distinct()
                    }
                    
                    val standaloneDeletedDocs = remember(deletedDocs, foldersStateList) {
                        deletedDocs.filter { it.folderName.isNullOrBlank() || foldersStateList.contains(it.folderName) }
                    }
                    
                    val isTrashTrulyEmpty = deletedDocs.isEmpty() && deletedCustomFoldersState.isEmpty()

                    Column(
