                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                        ) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(12.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                                    Box(
                                                        modifier = Modifier
                                                            .size(36.dp)
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(
                                                                when (doc.type.lowercase()) {
                                                                    "sheet" -> Color(0xFFD1FAE5)
                                                                    "slide" -> Color(0xFFFFEDD5)
                                                                    "pdf" -> Color(0xFFFEE2E2)
                                                                    else -> Color(0xFFDBEAFE)
                                                                }
                                                            ),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Icon(
                                                            imageVector = when (doc.type.lowercase()) {
                                                                "sheet" -> Icons.Outlined.GridOn
                                                                "slide" -> Icons.Outlined.CoPresent
                                                                "pdf" -> Icons.Outlined.PictureAsPdf
                                                                else -> Icons.Outlined.Description
                                                            },
                                                            contentDescription = null,
                                                            tint = when (doc.type.lowercase()) {
                                                                "sheet" -> Color(0xFF059669)
                                                                "slide" -> Color(0xFFD97706)
                                                                "pdf" -> Color(0xFFDC2626)
                                                                else -> Color(0xFF2563EB)
                                                            },
                                                            modifier = Modifier.size(20.dp)
                                                        )
