                    }
                }
                "settings" -> {
                    val settingsContext = LocalContext.current
                    val settingsSharedPreferences = remember { settingsContext.getSharedPreferences("ai_agent_prefs", Context.MODE_PRIVATE) }
                    
                    var aiProvider by remember { mutableStateOf(settingsSharedPreferences.getString("ai_provider", "Gemini") ?: "Gemini") }
                    var openRouterKey by remember { mutableStateOf(settingsSharedPreferences.getString("openrouter_key", "") ?: "") }
                    var geminiApiKey by remember { mutableStateOf(settingsSharedPreferences.getString("gemini_api_key", "") ?: "") }

                    var userEmail by remember { mutableStateOf(settingsSharedPreferences.getString("user_email_key", "chandan.kumar@example.com") ?: "chandan.kumar@example.com") }
                    var aiPreferences by remember { mutableStateOf(settingsSharedPreferences.getString("ai_preferences_key", "Smart") ?: "Smart") }
                    var defaultAiModel by remember { mutableStateOf(settingsSharedPreferences.getString("default_ai_model_key", "Gemini 2.5 Flash") ?: "Gemini 2.5 Flash") }
                    var aiResponseStyle by remember { mutableStateOf(settingsSharedPreferences.getString("ai_response_style_key", "Balanced") ?: "Balanced") }
                    var appearance by remember { mutableStateOf(settingsSharedPreferences.getString("appearance_key", "System") ?: "System") }
                    var language by remember { mutableStateOf(settingsSharedPreferences.getString("language_key", "English") ?: "English") }
                    var security2FA by remember { mutableStateOf(settingsSharedPreferences.getBoolean("security_2fa_key", true)) }

                    LaunchedEffect(aiProvider) { settingsSharedPreferences.edit().putString("ai_provider", aiProvider).apply() }
                    LaunchedEffect(openRouterKey) { settingsSharedPreferences.edit().putString("openrouter_key", openRouterKey).apply() }
                    LaunchedEffect(geminiApiKey) { settingsSharedPreferences.edit().putString("gemini_api_key", geminiApiKey).apply() }
                    LaunchedEffect(userEmail) { settingsSharedPreferences.edit().putString("user_email_key", userEmail).apply() }
                    LaunchedEffect(aiPreferences) { settingsSharedPreferences.edit().putString("ai_preferences_key", aiPreferences).apply() }
                    LaunchedEffect(defaultAiModel) { settingsSharedPreferences.edit().putString("default_ai_model_key", defaultAiModel).apply() }
                    LaunchedEffect(aiResponseStyle) { settingsSharedPreferences.edit().putString("ai_response_style_key", aiResponseStyle).apply() }
                    LaunchedEffect(appearance) { settingsSharedPreferences.edit().putString("appearance_key", appearance).apply() }
                    LaunchedEffect(language) { settingsSharedPreferences.edit().putString("language_key", language).apply() }
                    LaunchedEffect(security2FA) { settingsSharedPreferences.edit().putBoolean("security_2fa_key", security2FA).apply() }

                    var activeSubSettingsGroup by remember { mutableStateOf<String?>(null) }
                    val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current

                    val settingsHeaderColor = if (isSystemInDarkTheme()) Color.White else Color(0xFF0F172A)
                    val settingsCardBgColor = if (isSystemInDarkTheme()) Color(0xFF1E1E22) else Color.White
                    val settingsCardBorderColor = if (isSystemInDarkTheme()) Color.White.copy(alpha = 0.12f) else Color(0xFFE2E8F0)
                    val settingsTextColor = if (isSystemInDarkTheme()) Color.White else Color(0xFF1E293B)
                    val settingsSubtextColor = if (isSystemInDarkTheme()) Color.LightGray else Color(0xFF64748B)
                    val settingsDividerColor = if (isSystemInDarkTheme()) Color.White.copy(alpha = 0.08f) else Color(0xFFF1F5F9)

                    val settingsRow = @Composable { icon: ImageVector, iconBgColor: Color, iconColor: Color, title: String, subtitle: String, badgeText: String?, onClick: () -> Unit ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable(onClick = onClick)
                                .padding(horizontal = 12.dp, vertical = 6.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(iconBgColor),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = icon,
                                    contentDescription = null,
                                    tint = iconColor,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Spacer(modifier = Modifier.width(14.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = title,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp,
                                    color = settingsTextColor
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = subtitle,
                                    fontSize = 10.sp,
                                    color = settingsSubtextColor
                                )
                            }
                            if (badgeText != null) {
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(Color(0xFFEEF2FF))
                                        .padding(horizontal = 10.dp, vertical = 3.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = badgeText,
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF4F46E5)
                                    )
                                }
                                Spacer(modifier = Modifier.width(8.dp))
                            }
                            Icon(
                                imageVector = Icons.Default.ChevronRight,
                                contentDescription = null,
                                tint = Color(0xFF94A3B8),
                                modifier = Modifier.size(16.dp)
                            )
                        }
                    }

                    if (activeSubSettingsGroup != null) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(16.dp)
                                .verticalScroll(rememberScrollState()),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            // Back Header Clickable row
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { activeSubSettingsGroup = null }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(
                                    imageVector = Icons.Default.ArrowBack,
                                    contentDescription = "Back",
                                    tint = Color(0xFF5B2BE0),
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = "Back to Settings",
                                    color = Color(0xFF5B2BE0),
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp
                                )
                            }

                            when (activeSubSettingsGroup) {
                                "Profile Information" -> {
                                    Text("Profile Information", style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold), color = Color(0xFF0F172A))
                                    Text("Customize your display identification and workspace metadata tags.", fontSize = 12.sp, color = Color(0xFF64748B))

                                    Card(
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
                                            OutlinedTextField(
                                                value = username,
                                                onValueChange = { 
                                                    username = it
                                                    settingsSharedPreferences.edit().putString("username_key", it).apply()
                                                },
                                                label = { Text("Display Name") },
                                                singleLine = true,
                                                modifier = Modifier.fillMaxWidth()
                                            )
                                            OutlinedTextField(
                                                value = userRole,
                                                onValueChange = { 
                                                    userRole = it
                                                    settingsSharedPreferences.edit().putString("user_role_key", it).apply()
                                                },
                                                label = { Text("Workspace Role Title") },
                                                singleLine = true,
                                                modifier = Modifier.fillMaxWidth()
                                            )
                                            OutlinedTextField(
                                                value = userEmail,
                                                onValueChange = { userEmail = it },
                                                label = { Text("Email Address") },
                                                singleLine = true,
                                                modifier = Modifier.fillMaxWidth()
                                            )
                                            Button(
                                                onClick = {
                                                    activeSubSettingsGroup = null
                                                    Toast.makeText(settingsContext, "Profile changes saved!", Toast.LENGTH_SHORT).show()
                                                },
                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF5B2BE0)),
                                                shape = RoundedCornerShape(12.dp),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Text("Keep & Save Changes", color = Color.White, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                                "App Permissions" -> {
                                    Text("App Permissions", style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold), color = Color(0xFF0F172A))
                                    Text("Manage storage, camera, and notification alert permissions on-demand.", fontSize = 12.sp, color = Color(0xFF64748B))

                                    Card(
                                        shape = RoundedCornerShape(16.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
                                            // Storage permission row
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text("Device Storage Access", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                                    Text("For bulk exporting backups and direct file actions.", fontSize = 11.sp, color = Color.Gray)
                                                }
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(
                                                        text = if (hasStoragePermission) "Granted" else "Denied / Skipped",
                                                        color = if (hasStoragePermission) Color(0xFF16A34A) else Color(0xFFDC2626),
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier.padding(end = 8.dp)
                                                    )
                                                    Switch(
                                                        checked = hasStoragePermission,
                                                        onCheckedChange = { checked ->
                                                            if (checked) {
                                                                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                                                                    storagePermissionLauncher.launch(
                                                                        arrayOf(
                                                                            android.Manifest.permission.READ_MEDIA_IMAGES,
                                                                            android.Manifest.permission.READ_MEDIA_VIDEO
                                                                        )
                                                                    )
                                                                } else {
                                                                    storagePermissionLauncher.launch(
                                                                        arrayOf(
                                                                            android.Manifest.permission.READ_EXTERNAL_STORAGE,
                                                                            android.Manifest.permission.WRITE_EXTERNAL_STORAGE
                                                                        )
                                                                    )
                                                                }
                                                            } else {
                                                                Toast.makeText(context, "To revoke storage access, please disable it in system settings.", Toast.LENGTH_LONG).show()
                                                            }
                                                        }
                                                    )
                                                }
                                            }

                                            HorizontalDivider(color = Color(0xFFF1F5F9))

                                            // Camera permission row
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text("Camera Access", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                                    Text("Snaps live pictures to embed directly within documents.", fontSize = 11.sp, color = Color.Gray)
                                                }
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(
                                                        text = if (hasCameraPermission) "Granted" else "Denied / Skipped",
                                                        color = if (hasCameraPermission) Color(0xFF16A34A) else Color(0xFFDC2626),
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier.padding(end = 8.dp)
                                                    )
                                                    Switch(
                                                        checked = hasCameraPermission,
                                                        onCheckedChange = { checked ->
                                                            if (checked) {
                                                                cameraPermissionLauncher.launch(android.Manifest.permission.CAMERA)
                                                            } else {
                                                                Toast.makeText(context, "To revoke camera access, please disable it in system settings.", Toast.LENGTH_LONG).show()
                                                            }
                                                        }
                                                    )
                                                }
                                            }

                                            HorizontalDivider(color = Color(0xFFF1F5F9))

                                            // Notifications permission row
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column(modifier = Modifier.weight(1f)) {
                                                    Text("Notification Alerts", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                                    Text("Get real-time notification alerts on backup completed.", fontSize = 11.sp, color = Color.Gray)
                                                }
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(
                                                        text = if (hasNotificationPermission) "Granted" else "Denied / Skipped",
                                                        color = if (hasNotificationPermission) Color(0xFF16A34A) else Color(0xFFDC2626),
                                                        fontSize = 12.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        modifier = Modifier.padding(end = 8.dp)
                                                    )
                                                    Switch(
                                                        checked = hasNotificationPermission,
                                                        onCheckedChange = { checked ->
                                                            if (checked) {
                                                                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                                                                    notificationPermissionLauncher.launch(android.Manifest.permission.POST_NOTIFICATIONS)
                                                                } else {
                                                                    hasNotificationPermission = true
                                                                    Toast.makeText(context, "Notifications are automatically enabled on this Android version.", Toast.LENGTH_SHORT).show()
                                                                }
                                                            } else {
                                                                Toast.makeText(context, "To revoke notifications, please disable them in system settings.", Toast.LENGTH_LONG).show()
                                                            }
                                                        }
                                                    )
                                                }
                                            }
                                        }
                                    }

                                    // Button to open app details directly in system settings
                                    Button(
                                        onClick = {
                                            try {
                                                val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                                                    data = android.net.Uri.fromParts("package", context.packageName, null)
                                                }
                                                context.startActivity(intent)
                                            } catch (e: Exception) {
                                                val intent = android.content.Intent(android.provider.Settings.ACTION_SETTINGS)
                                                context.startActivity(intent)
                                            }
