@Composable
fun FeaturedDocBentoCard(
    featuredDoc: DocEntity?,
    onDocClick: (DocEntity) -> Unit,
    onQuickCreate: () -> Unit,
    modifier: Modifier = Modifier
) {
    val cardGradient = Brush.linearGradient(
        colors = listOf(Color(0xFFD9E2FF), Color(0xFFC0D1FF))
    )
    val textColor = Color(0xFF001D36)
    val subtextColor = Color(0xFF44474E)

    val lastEditedFormatted = remember(featuredDoc?.updatedAt) {
        if (featuredDoc != null) {
            val sdf = SimpleDateFormat("HH:mm", Locale.getDefault())
            "Modified Today at ${sdf.format(Date(featuredDoc.updatedAt))}"
        } else {
            "No recent modifications recorded"
        }
    }

    Card(
        onClick = { if (featuredDoc != null) onDocClick(featuredDoc) else onQuickCreate() },
        shape = RoundedCornerShape(28.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Transparent),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
        modifier = modifier
            .fillMaxWidth()
            .heightIn(min = 160.dp)
            .background(cardGradient, shape = RoundedCornerShape(28.dp))
            .border(width = 1.dp, color = Color.White.copy(alpha = 0.6f), shape = RoundedCornerShape(28.dp))
            .testTag("bento_featured_card")
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(20.dp),
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.Top
            ) {
                // Icon layout inspired by Bento layouts
                Box(
                    modifier = Modifier
                        .size(46.dp)
                        .clip(RoundedCornerShape(14.dp))
                        .background(Color.White.copy(alpha = 0.45f)),
                    contentAlignment = Alignment.Center
                ) {
                    val symbolStr = when (featuredDoc?.type) {
                        "word" -> "W"
                        "sheet" -> "S"
                        "slide" -> "P"
                        else -> "O"
                    }
                    Text(
                        text = symbolStr,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF005AC1),
                        fontSize = 18.sp
                    )
                }

                // Dynamic badges
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(100.dp))
                        .background(Color(0xFF005AC1).copy(alpha = 0.08f))
                        .padding(horizontal = 10.dp, vertical = 4.dp)
                ) {
                    Text(
                        text = if (featuredDoc != null) "Resume Editing" else "Create Now",
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        color = textColor,
                        letterSpacing = 0.5.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            Column {
                Text(
                    text = featuredDoc?.title ?: "Welcome To JCdocs Workspace",
                    style = MaterialTheme.typography.titleLarge.copy(
                        fontWeight = FontWeight.Bold,
                        lineHeight = 26.sp
                    ),
                    color = textColor,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
                
                Spacer(modifier = Modifier.height(4.dp))
                
                Text(
                    text = if (featuredDoc != null) lastEditedFormatted else "Get started immediately by clicking to build your proposal note.",
                    style = MaterialTheme.typography.bodySmall,
                    color = subtextColor
                )
            }
        }
    }
}

@Composable
fun CollaborationBentoCard(
    sheetsCount: Int,
    writerCount: Int,
    slidesCount: Int,
    onClick: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val cardGradient = Brush.linearGradient(
        colors = listOf(Color(0xFFE1E2E9), Color(0xFFECEEF4))
    )
    val textColor = Color(0xFF1A1C1E)

    Card(
        onClick = onClick,
        shape = RoundedCornerShape(28.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Transparent),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
        modifier = modifier
            .fillMaxWidth()
            .heightIn(min = 140.dp)
            .background(cardGradient, shape = RoundedCornerShape(28.dp))
            .border(width = 1.dp, color = Color.White.copy(alpha = 0.6f), shape = RoundedCornerShape(28.dp))
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    text = "SANDBOX ENGAGEMENT",
                    style = MaterialTheme.typography.labelSmall.copy(
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    ),
                    color = Color(0xFF44474E)
                )

                // Pulsing indicator dot
                val infiniteTransition = rememberInfiniteTransition(label = "pulse")
                val alpha by infiniteTransition.animateFloat(
                    initialValue = 0.4f,
                    targetValue = 1f,
                    animationSpec = infiniteRepeatable(
                        animation = tween(1000, easing = LinearEasing),
                        repeatMode = RepeatMode.Reverse
                    ),
                    label = "alpha"
                )
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Box(
                        modifier = Modifier
                            .size(8.dp)
                            .clip(CircleShape)
                            .background(Color(0xFF2E7D32).copy(alpha = alpha))
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = "Live Sync",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF2E7D32)
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Avatar stacking overlay exactly replicating Tailwind CSS markup
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy((-8).dp)
            ) {
                // Color dots simulating users
                listOf(Color(0xFF42A5F5), Color(0xFF66BB6A), Color(0xFFAB47BC)).forEachIndexed { i, color ->
                    Box(
                        modifier = Modifier
                            .size(28.dp)
                            .clip(CircleShape)
                            .background(color)
                            .border(1.5.dp, Color(0xFFECEEF4), CircleShape)
                    )
                }
                Box(
                    modifier = Modifier
                        .size(28.dp)
                        .clip(CircleShape)
                        .background(Color.White.copy(alpha = 0.6f))
                        .border(1.5.dp, Color(0xFFECEEF4), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = "+4",
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color.DarkGray
                    )
                }
                
                Spacer(modifier = Modifier.width(16.dp))
                
                Text(
                    text = "7 simulated sandboxes active",
                    style = MaterialTheme.typography.bodySmall,
                    fontWeight = FontWeight.SemiBold,
                    color = textColor
                )
            }

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = "Robust offline operations utilizing local cache streams across $writerCount documents, $sheetsCount sheets, and $slidesCount decks.",
                style = MaterialTheme.typography.bodyMedium,
                color = Color(0xFF44474E).copy(alpha = 0.85f)
            )
        }
    }
}

