@Composable
fun RoomDbStorageBentoSquare(
    totalFiles: Int,
    modifier: Modifier = Modifier
) {
    val cardGradient = Brush.linearGradient(
        colors = listOf(Color(0xFFD3E8D3), Color(0xFFB5DBB5))
    )
    val textColor = Color(0xFF00210B)
    val progressColor = Color(0xFF116C31)

    // Arbitrary percentage showcasing offline health
    val percentage = if (totalFiles == 0) 0f else minOf(100f, 15f + (totalFiles * 12f))

    Card(
        shape = RoundedCornerShape(28.dp),
        colors = CardDefaults.cardColors(containerColor = Color.Transparent),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
        modifier = modifier
            .heightIn(min = 130.dp)
            .background(cardGradient, shape = RoundedCornerShape(28.dp))
            .border(width = 1.dp, color = Color.White.copy(alpha = 0.6f), shape = RoundedCornerShape(28.dp))
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(16.dp),
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "SQL DATABASE",
                    style = MaterialTheme.typography.labelSmall.copy(
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 0.5.sp
                    ),
                    color = textColor.copy(alpha = 0.6f)
                )
                
                Text(
                    text = "${percentage.toInt()}%",
                    style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                    color = textColor
                )
            }

            // Custom green percentage progress bar representing sqlite memory limits
            Column {
                LinearProgressIndicator(
                    progress = percentage / 100f,
                    color = progressColor,
                    trackColor = textColor.copy(alpha = 0.08f),
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(8.dp)
                        .clip(RoundedCornerShape(4.dp))
                )
                
                Spacer(modifier = Modifier.height(8.dp))
                
                Text(
                    text = "SQLite schema integrity secure",
                    fontSize = 10.sp,
                    fontWeight = FontWeight.SemiBold,
                    color = progressColor
                )
            }
        }
    }
}

