@Composable
fun ReadAloudPlayerControls(
    text: String,
    tts: android.speech.tts.TextToSpeech?,
    onClose: () -> Unit
) {
    var isPlaying by remember { mutableStateOf(true) }
    var speed by remember { mutableStateOf(1.0f) }

    Card(
        elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
        shape = RoundedCornerShape(16.dp),
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp)
            .testTag("read_aloud_floating_controls")
    ) {
        Row(
            modifier = Modifier.padding(12.dp).fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                IconButton(
                    onClick = {
                        isPlaying = !isPlaying
                        if (isPlaying) {
                            tts?.setSpeechRate(speed)
                            val clean = text.replace("[#*_|\\-<>]+".toRegex(), " ")
                            tts?.speak(clean, android.speech.tts.TextToSpeech.QUEUE_FLUSH, null, null)
                        } else {
                            tts?.stop()
                        }
                    }
                ) {
                    Icon(
                        imageVector = if (isPlaying) Icons.Default.Pause else Icons.Default.PlayArrow,
                        contentDescription = "Play/Pause"
                    )
                }
                IconButton(
                    onClick = {
                        tts?.stop()
                        isPlaying = false
                    }
                ) {
                    Icon(imageVector = Icons.Default.Stop, contentDescription = "Stop")
                }
                
                Spacer(modifier = Modifier.width(12.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text("Speech rate: ", style = MaterialTheme.typography.bodySmall)
                    var expandedSpeedMenu by remember { mutableStateOf(false) }
                    Box {
                        TextButton(onClick = { expandedSpeedMenu = true }) {
                            Text("${speed}x", style = MaterialTheme.typography.bodySmall, fontWeight = FontWeight.Bold)
                        }
                        DropdownMenu(expanded = expandedSpeedMenu, onDismissRequest = { expandedSpeedMenu = false }) {
                            listOf(0.5f, 0.75f, 1.0f, 1.25f, 1.5f, 2.0f).forEach { s ->
                                DropdownMenuItem(
                                    text = { Text("${s}x") },
                                    onClick = {
                                        speed = s
                                        tts?.setSpeechRate(s)
                                        expandedSpeedMenu = false
                                        if (isPlaying) {
                                            val clean = text.replace("[#*_|\\-<>]+".toRegex(), " ")
                                            tts?.speak(clean, android.speech.tts.TextToSpeech.QUEUE_FLUSH, null, null)
                                        }
                                    }
                                )
                            }
                        }
                    }
                }
            }
            IconButton(onClick = {
                tts?.stop()
                onClose()
            }) {
                Icon(imageVector = Icons.Default.Close, contentDescription = "Close speaker controls")
            }
        }
    }
}

private fun drawPictureOnPdf(
    context: android.content.Context,
    canvas: android.graphics.Canvas,
    docPicture: DocPicture,
    density: Float,
    themeProps: OfficeThemeProperties,
    selectedThemeEffect: String = "None"
) {
    val x = docPicture.x.value * density
    val y = docPicture.y.value * density
    val w = docPicture.width.value * density
    val h = docPicture.height.value * density
    val rotation = docPicture.rotation
    val opacity = docPicture.opacity

    val bitmap = loadBitmapFromUri(context, docPicture.uri) ?: return

    val bmWidth = bitmap.width
    val bmHeight = bitmap.height

    val srcRect = android.graphics.Rect(0, 0, bmWidth, bmHeight)
    val destRect = android.graphics.RectF(0f, 0f, w, h)

    val cm = android.graphics.ColorMatrix()
    if (docPicture.isGrayscale) {
        cm.setSaturation(0f)
    } else if (docPicture.saturation != 1.0f) {
        cm.setSaturation(docPicture.saturation)
    }
    val b = (docPicture.brightness - 1.0f) * 255f
    val c = docPicture.contrast
    val array = floatArrayOf(
        c, 0f, 0f, 0f, b,
        0f, c, 0f, 0f, b,
        0f, 0f, c, 0f, b,
        0f, 0f, 0f, 1f, 0f
    )
    val brightnessContrastMatrix = android.graphics.ColorMatrix(array)

    val finalMatrix = android.graphics.ColorMatrix()
    if (docPicture.isInverted) {
        val invertArray = floatArrayOf(
            -1f, 0f, 0f, 0f, 255f,
            0f, -1f, 0f, 0f, 255f,
            0f, 0f, -1f, 0f, 255f,
            0f, 0f, 0f, 1f, 0f
        )
        val invertMatrix = android.graphics.ColorMatrix(invertArray)
        finalMatrix.set(brightnessContrastMatrix)
        finalMatrix.postConcat(invertMatrix)
        finalMatrix.postConcat(cm)
    } else {
        finalMatrix.set(brightnessContrastMatrix)
        finalMatrix.postConcat(cm)
    }
    val colorFilter = android.graphics.ColorMatrixColorFilter(finalMatrix)

    val rx = docPicture.borderRadiusDp.value * density
    val ry = docPicture.borderRadiusDp.value * density

    canvas.save()
    canvas.translate(x, y)

    // 1. Draw container shadow under-effects (unrotated)
    val shadowPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.FILL
    }
    var shadowDx = 0f
    var shadowDy = 0f
    var shadowAlpha = 0
    if (selectedThemeEffect == "Default Office") {
        shadowDx = 2f * density
        shadowDy = 2f * density
        shadowAlpha = (0.12f * 255).toInt()
    } else if (selectedThemeEffect == "Drop Shadow") {
        shadowDx = 3.5f * density
        shadowDy = 4.5f * density
        shadowAlpha = (0.2f * 255).toInt()
    } else if (selectedThemeEffect == "Glossy Reflex") {
        shadowDx = 1f * density
        shadowDy = 1f * density
        shadowAlpha = (0.1f * 255).toInt()
    } else if (docPicture.elevation.value > 0f) {
        val elev = docPicture.elevation.value
        shadowDx = elev * density
        shadowDy = elev * density
        shadowAlpha = (0.15f * 255).toInt()
    }
    if (shadowAlpha > 0) {
        shadowPaint.color = android.graphics.Color.argb(shadowAlpha, 0, 0, 0)
        canvas.save()
        canvas.translate(shadowDx, shadowDy)
        if (rx > 0f || ry > 0f) {
            canvas.drawRoundRect(destRect, rx, ry, shadowPaint)
        } else {
            canvas.drawRect(destRect, shadowPaint)
        }
        canvas.restore()
    }

    // 2. Draw rotated image bitmap and custom border
    canvas.save()
    if (rotation != 0f) {
        canvas.rotate(rotation, w / 2f, h / 2f)
    }

    // Clip crop bounds
    val cropRect = android.graphics.RectF(
        w * docPicture.cropLeft,
        h * docPicture.cropTop,
        w * (1f - docPicture.cropRight),
        h * (1f - docPicture.cropBottom)
    )
    canvas.clipRect(cropRect)

    // Clip to rounded corners for image content
    canvas.save()
    val clipPath = android.graphics.Path().apply {
        addRoundRect(destRect, rx, ry, android.graphics.Path.Direction.CW)
    }
    canvas.clipPath(clipPath)

    val paint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG or android.graphics.Paint.FILTER_BITMAP_FLAG or android.graphics.Paint.DITHER_FLAG).apply {
        this.colorFilter = colorFilter
        this.alpha = (opacity * 255).toInt()
        this.isFilterBitmap = true
        this.isDither = true
        this.isAntiAlias = true
    }
    canvas.drawBitmap(bitmap, srcRect, destRect, paint)
    canvas.restore()

    // Draw custom picture border (which is rotated and cropped)
    if (docPicture.borderWidthDp.value > 0f) {
        val borderPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
            style = android.graphics.Paint.Style.STROKE
            strokeWidth = docPicture.borderWidthDp.value * density
            color = try {
                if (docPicture.borderColorHex.isBlank() || docPicture.borderColorHex == "DocWordColor") {
                    themeProps.primaryAccent.toArgb()
                } else {
                    android.graphics.Color.parseColor(if (docPicture.borderColorHex.startsWith("#")) docPicture.borderColorHex else "#${docPicture.borderColorHex}")
                }
            } catch (e: Exception) {
                android.graphics.Color.parseColor("#CCCCCC")
            }
            alpha = (opacity * 255).toInt()
        }
        canvas.drawRoundRect(destRect, rx, ry, borderPaint)
    }
    canvas.restore() // restore rotation & crop

    // 3. Draw theme effect over-effects (unrotated on container bounds)
    val effectPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.STROKE
    }
    when (selectedThemeEffect) {
        "Glossy Reflex" -> {
            // Gradient overlay
            val glossPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                style = android.graphics.Paint.Style.FILL
            }
            val colors = intArrayOf(
                android.graphics.Color.argb((0.15f * 255).toInt(), 255, 255, 255),
                android.graphics.Color.argb(0, 255, 255, 255),
                android.graphics.Color.argb((0.05f * 255).toInt(), 0, 0, 0)
            )
            val positions = floatArrayOf(0f, 0.5f, 1f)
            glossPaint.shader = android.graphics.LinearGradient(
                0f, 0f, 0f, h,
                colors, positions, android.graphics.Shader.TileMode.CLAMP
            )
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, glossPaint)
            } else {
                canvas.drawRect(destRect, glossPaint)
            }
            // White border
            effectPaint.color = android.graphics.Color.argb((0.4f * 255).toInt(), 255, 255, 255)
            effectPaint.strokeWidth = 1f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
        }
        "Matte Border" -> {
            effectPaint.color = android.graphics.Color.parseColor("#333333")
            effectPaint.strokeWidth = 2.5f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
        }
        "Soft Edges Blurry" -> {
            // Outer border: 4.dp, alpha 0.1f
            effectPaint.color = android.graphics.Color.argb((0.1f * 255).toInt(), 128, 128, 128)
            effectPaint.strokeWidth = 4f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
            // Inner border: 2.dp, alpha 0.25f
            effectPaint.color = android.graphics.Color.argb((0.25f * 255).toInt(), 128, 128, 128)
            effectPaint.strokeWidth = 2f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
        }
        "Glow Neon Blue" -> {
            // Outer glow: 4.dp, alpha 0.25f
            effectPaint.color = android.graphics.Color.argb((0.25f * 255).toInt(), 0, 0xF5, 0xFF)
            effectPaint.strokeWidth = 4f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
            // Inner glow: 2.dp, alpha 0.7f
            effectPaint.color = android.graphics.Color.argb((0.7f * 255).toInt(), 0, 0xF5, 0xFF)
            effectPaint.strokeWidth = 2f * density
            if (rx > 0f || ry > 0f) {
                canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            } else {
                canvas.drawRect(destRect, effectPaint)
            }
        }
    }

    canvas.restore()
}

private fun drawShapeOnPdf(
    canvas: android.graphics.Canvas,
    shape: DocShape,
    density: Float,
    themeProps: OfficeThemeProperties,
    selectedThemeEffect: String = "None"
) {
    val x = shape.x.value * density
    val y = shape.y.value * density
    val w = shape.width.value * density
    val h = shape.height.value * density
    val borderPx = shape.borderWidthDp.value * density

    val fillColor = try {
        if (shape.fillColorHex.isBlank() || shape.fillColorHex == "default" || shape.fillColorHex.equals("#4F81BD", ignoreCase = true)) {
            themeProps.secondaryAccent.toArgb()
        } else {
            android.graphics.Color.parseColor(shape.fillColorHex)
        }
    } catch (e: Exception) {
        themeProps.secondaryAccent.toArgb()
    }

    val borderColor = try {
        if (shape.borderColorHex.isBlank() || shape.borderColorHex == "default" || shape.borderColorHex.equals("#1B365D", ignoreCase = true)) {
            themeProps.primaryAccent.toArgb()
        } else {
            android.graphics.Color.parseColor(shape.borderColorHex)
        }
    } catch (e: Exception) {
        themeProps.primaryAccent.toArgb()
    }

    val textColor = try {
        android.graphics.Color.parseColor(shape.textColorHex)
    } catch (e: Exception) {
        android.graphics.Color.WHITE
    }

    val path = android.graphics.Path()
    when (shape.type) {
        "triangle" -> {
            path.moveTo(w / 2f, 0f)
            path.lineTo(w, h)
            path.lineTo(0f, h)
            path.close()
        }
        "right_triangle" -> {
            path.moveTo(0f, 0f)
            path.lineTo(0f, h)
            path.lineTo(w, h)
            path.close()
        }
        "diamond" -> {
            path.moveTo(w / 2f, 0f)
            path.lineTo(w, h / 2f)
            path.lineTo(w / 2f, h)
            path.lineTo(0f, h / 2f)
            path.close()
        }
        "hexagon" -> {
            path.moveTo(w * 0.25f, 0f)
            path.lineTo(w * 0.75f, 0f)
            path.lineTo(w, h / 2f)
            path.lineTo(w * 0.75f, h)
            path.lineTo(w * 0.25f, h)
            path.lineTo(0f, h / 2f)
            path.close()
        }
        "cloud" -> {
            path.moveTo(w * 0.25f, h * 0.75f)
            path.cubicTo(w * 0.05f, h * 0.75f, w * 0.05f, h * 0.45f, w * 0.25f, h * 0.45f)
            path.cubicTo(w * 0.25f, h * 0.2f, w * 0.55f, h * 0.2f, w * 0.55f, h * 0.45f)
            path.cubicTo(w * 0.75f, h * 0.3f, w * 0.95f, h * 0.5f, w * 0.85f, h * 0.65f)
            path.cubicTo(w * 0.95f, h * 0.85f, w * 0.75f, h * 0.85f, w * 0.65f, h * 0.85f)
            path.lineTo(w * 0.25f, h * 0.85f)
            path.close()
        }
        "heart" -> {
            path.moveTo(w / 2f, h * 0.25f)
            path.cubicTo(w * 0.2f, h * -0.05f, w * -0.1f, h * 0.35f, w / 2f, h * 0.85f)
            path.cubicTo(w * 1.1f, h * 0.35f, w * 0.8f, h * -0.05f, w / 2f, h * 0.25f)
            path.close()
        }
        "right_arrow" -> {
            path.moveTo(0f, h * 0.3f)
            path.lineTo(w * 0.6f, h * 0.3f)
            path.lineTo(w * 0.6f, 0f)
            path.lineTo(w, h / 2f)
            path.lineTo(w * 0.6f, h)
            path.lineTo(w * 0.6f, h * 0.7f)
            path.lineTo(0f, h * 0.7f)
            path.close()
        }
        "left_arrow" -> {
            path.moveTo(w, h * 0.3f)
            path.lineTo(w * 0.4f, h * 0.3f)
            path.lineTo(w * 0.4f, 0f)
            path.lineTo(0f, h / 2f)
            path.lineTo(w * 0.4f, h)
            path.lineTo(w * 0.4f, h * 0.7f)
            path.lineTo(w, h * 0.7f)
            path.close()
        }
        "up_arrow" -> {
            path.moveTo(w * 0.3f, h)
            path.lineTo(w * 0.3f, h * 0.4f)
            path.lineTo(0f, h * 0.4f)
            path.lineTo(w / 2f, 0f)
            path.lineTo(w, h * 0.4f)
            path.lineTo(w * 0.7f, h * 0.4f)
            path.lineTo(w * 0.7f, h)
            path.close()
        }
        "down_arrow" -> {
            path.moveTo(w * 0.3f, 0f)
            path.lineTo(w * 0.3f, h * 0.6f)
            path.lineTo(0f, h * 0.6f)
            path.lineTo(w / 2f, h)
            path.lineTo(w, h * 0.6f)
            path.lineTo(w * 0.7f, h * 0.6f)
            path.lineTo(w * 0.7f, 0f)
            path.close()
        }
        "plus_eq" -> {
            path.moveTo(w * 0.35f, 0f)
            path.lineTo(w * 0.65f, 0f)
            path.lineTo(w * 0.65f, h * 0.35f)
            path.lineTo(w, h * 0.35f)
            path.lineTo(w, h * 0.65f)
            path.lineTo(w * 0.65f, h * 0.65f)
            path.lineTo(w * 0.65f, h)
            path.lineTo(w * 0.35f, h)
            path.lineTo(w * 0.35f, h * 0.65f)
            path.lineTo(0f, h * 0.65f)
            path.lineTo(0f, h * 0.35f)
            path.lineTo(w * 0.35f, h * 0.35f)
            path.close()
        }
        "minus_eq" -> {
            path.moveTo(0f, h * 0.35f)
            path.lineTo(w, h * 0.35f)
            path.lineTo(w, h * 0.65f)
            path.lineTo(0f, h * 0.65f)
            path.close()
        }
        "star_5" -> {
            val cx = w / 2f
            val cy = h / 2f
            val r = w / 2f
            val innerRadius = r * 0.4f
            var angle = -Math.PI / 2.0
            val dAngle = Math.PI / 5.0
            for (i in 0 until 10) {
                val currentRadius = if (i % 2 == 0) r else innerRadius
                val curX = cx + currentRadius * Math.cos(angle)
                val curY = cy + currentRadius * Math.sin(angle)
                if (i == 0) path.moveTo(curX.toFloat(), curY.toFloat())
                else path.lineTo(curX.toFloat(), curY.toFloat())
                angle += dAngle
            }
            path.close()
        }
    }

    canvas.save()
    canvas.translate(x, y)
    if (shape.rotation != 0f) {
        canvas.rotate(shape.rotation, w / 2f, h / 2f)
    }

    val drawShapeContent = fun(
        colorOverride: Int?,
        isOutlineOnly: Boolean,
        outlineWidth: Float?,
        outlineColor: Int?,
        isGlossyOverlay: Boolean
    ) {
        val fill = colorOverride ?: fillColor
        val borderCol = outlineColor ?: borderColor
        val strokeW = outlineWidth ?: borderPx

        val paint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG)
        paint.alpha = (shape.opacity * 255).toInt()

        if (!isOutlineOnly) {
            paint.style = android.graphics.Paint.Style.FILL
            if (isGlossyOverlay) {
                val colors = intArrayOf(
                    android.graphics.Color.argb((0.25f * 255).toInt(), 255, 255, 255),
                    android.graphics.Color.argb(0, 255, 255, 255),
                    android.graphics.Color.argb((0.12f * 255).toInt(), 0, 0, 0)
                )
                val positions = floatArrayOf(0f, 0.5f, 1f)
                val shader = android.graphics.LinearGradient(
                    0f, 0f, 0f, h,
                    colors, positions, android.graphics.Shader.TileMode.CLAMP
                )
                paint.shader = shader
            } else {
                paint.color = fill
            }

            when (shape.type) {
                "rectangle" -> canvas.drawRect(0f, 0f, w, h, paint)
                "round_rectangle" -> {
                    val radius = 16f * density
                    canvas.drawRoundRect(0f, 0f, w, h, radius, radius, paint)
                }
                "ellipse" -> canvas.drawOval(0f, 0f, w, h, paint)
                "smiley" -> {
                    val r = minOf(w, h) / 2f
                    canvas.drawCircle(w / 2f, h / 2f, r, paint)
                }
                else -> canvas.drawPath(path, paint)
            }
            paint.shader = null
        }

        if (strokeW > 0f) {
            paint.style = android.graphics.Paint.Style.STROKE
            paint.strokeWidth = strokeW
            paint.color = borderCol

            when (shape.type) {
                "rectangle" -> canvas.drawRect(0f, 0f, w, h, paint)
                "round_rectangle" -> {
                    val radius = 16f * density
                    canvas.drawRoundRect(0f, 0f, w, h, radius, radius, paint)
                }
                "ellipse" -> canvas.drawOval(0f, 0f, w, h, paint)
                "smiley" -> {
                    val r = minOf(w, h) / 2f
                    canvas.drawCircle(w / 2f, h / 2f, r, paint)
                    val eyeR = r * 0.06f
                    paint.style = android.graphics.Paint.Style.FILL
                    canvas.drawCircle(w * 0.35f, h * 0.4f, eyeR, paint)
                    canvas.drawCircle(w * 0.65f, h * 0.4f, eyeR, paint)

                    paint.style = android.graphics.Paint.Style.STROKE
                    val mouthRect = android.graphics.RectF(w * 0.3f, h * 0.5f, w * 0.7f, h * 0.75f)
                    canvas.drawArc(mouthRect, 0f, 180f, false, paint)
                }
                else -> {
                    paint.strokeJoin = android.graphics.Paint.Join.ROUND
                    canvas.drawPath(path, paint)
                }
            }
        }
    }

    // 1. Draw shape shadow under-effects
    when (selectedThemeEffect) {
        "Default Office" -> {
            val shadowOffset = 2f * density
            canvas.save()
            canvas.translate(shadowOffset, shadowOffset)
            val shadowColor = android.graphics.Color.argb((0.12f * 255).toInt(), 0, 0, 0)
            drawShapeContent(shadowColor, false, borderPx, shadowColor, false)
            canvas.restore()
        }
        "Drop Shadow" -> {
            val dx = 3.5f * density
            val dy = 4.5f * density
            canvas.save()
            canvas.translate(dx, dy)
            val shadowColor = android.graphics.Color.argb((0.2f * 255).toInt(), 0, 0, 0)
            drawShapeContent(shadowColor, false, borderPx, shadowColor, false)
            canvas.restore()
        }
        "Glow Neon Blue" -> {
            val neonColor = android.graphics.Color.parseColor("#00F5FF")
            val alpha1 = android.graphics.Color.argb((0.15f * 255).toInt(), 0, 0xF5, 0xFF)
            val alpha2 = android.graphics.Color.argb((0.35f * 255).toInt(), 0, 0xF5, 0xFF)
            val alpha3 = android.graphics.Color.argb((0.7f * 255).toInt(), 0, 0xF5, 0xFF)
            drawShapeContent(null, true, 8f * density, alpha1, false)
            drawShapeContent(null, true, 4f * density, alpha2, false)
            drawShapeContent(null, true, 2f * density, alpha3, false)
        }
        "Soft Edges Blurry" -> {
            val softColor = android.graphics.Color.parseColor("#BBBBBB")
            val alpha1 = android.graphics.Color.argb((0.08f * 255).toInt(), 0xBB, 0xBB, 0xBB)
            val alpha2 = android.graphics.Color.argb((0.18f * 255).toInt(), 0xBB, 0xBB, 0xBB)
            val alpha3 = android.graphics.Color.argb((0.35f * 255).toInt(), 0xBB, 0xBB, 0xBB)
            drawShapeContent(null, true, 9f * density, alpha1, false)
            drawShapeContent(null, true, 6f * density, alpha2, false)
            drawShapeContent(null, true, 3f * density, alpha3, false)
        }
    }

    // 2. Draw base shape (Fill and Stroke)
    val baseBorderColor = if (selectedThemeEffect == "Matte Border") {
        android.graphics.Color.parseColor("#333333")
    } else {
        borderColor
    }
    val baseBorderWidth = if (selectedThemeEffect == "Matte Border") {
        3.5f * density
    } else {
        borderPx
    }
    drawShapeContent(null, false, baseBorderWidth, baseBorderColor, false)

    // 3. Draw glossy highlights on top
    if (selectedThemeEffect == "Glossy Reflex") {
        drawShapeContent(null, false, 0f, null, true)
        val glossOutlineColor = android.graphics.Color.argb((0.45f * 255).toInt(), 255, 255, 255)
        drawShapeContent(null, true, 1f * density, glossOutlineColor, false)
    }

    // 4. Draw internal text
    if (shape.textInside.isNotEmpty()) {
        val textPaint = android.text.TextPaint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
            color = textColor
            textSize = shape.textSizeSp * density
            typeface = android.graphics.Typeface.create(
                android.graphics.Typeface.DEFAULT,
                if (shape.isBold && shape.isItalic) android.graphics.Typeface.BOLD_ITALIC
                else if (shape.isBold) android.graphics.Typeface.BOLD
                else if (shape.isItalic) android.graphics.Typeface.ITALIC
                else android.graphics.Typeface.NORMAL
            )
            alpha = (shape.opacity * 255).toInt()
        }

        val padding = 8f * density
        val allowedWidth = maxOf(20f, w - padding * 2)
        val emojiTf = getEmojiTypeface()
        val spannableText = createEmojiSpannable(shape.textInside, emojiTf)
        val textLayout = android.text.StaticLayout.Builder.obtain(spannableText, 0, spannableText.length, textPaint, allowedWidth.toInt())
            .setAlignment(when (shape.textAlignment) {
                "left" -> android.text.Layout.Alignment.ALIGN_NORMAL
                "right" -> android.text.Layout.Alignment.ALIGN_OPPOSITE
                else -> android.text.Layout.Alignment.ALIGN_CENTER
            })
            .setLineSpacing(0f, 1f)
            .setIncludePad(false)
            .build()

        val textHeight = textLayout.height
        val startY = (h - textHeight) / 2f
        val startX = (w - allowedWidth) / 2f
        canvas.save()
        canvas.translate(startX, startY)
        textLayout.draw(canvas)
        canvas.restore()
    }

    canvas.restore()
}

private fun drawTableOnPdf(
    canvas: android.graphics.Canvas,
    table: DocTable,
    density: Float,
    themeProps: OfficeThemeProperties,
    selectedThemeEffect: String = "None"
) {
    val x = table.x.value * density
    val y = table.y.value * density
    val w = table.width.value * density
    val h = table.height.value * density
    val borderWidthPx = table.borderWidth.value * density

    val themeColor = try {
        if (table.themeColorHex.isBlank() || table.themeColorHex == "default" || table.themeColorHex == "#5B9BD5") {
            themeProps.primaryAccent.toArgb()
        } else {
            val hex = if (table.themeColorHex.startsWith("#")) table.themeColorHex else "#${table.themeColorHex}"
            android.graphics.Color.parseColor(hex)
        }
    } catch (e: Exception) {
        themeProps.primaryAccent.toArgb()
    }

    val cellWidth = w / table.columns
    val cellHeight = h / table.rows

    canvas.save()
    canvas.translate(x, y)

    val destRect = android.graphics.RectF(0f, 0f, w, h)
    val rx = 4f * density
    val ry = 4f * density

    // 1. Draw table container shadow under-effects
    val shadowPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.FILL
    }
    var shadowDx = 0f
    var shadowDy = 0f
    var shadowAlpha = 0
    if (selectedThemeEffect == "Default Office") {
        shadowDx = 2f * density
        shadowDy = 2f * density
        shadowAlpha = (0.12f * 255).toInt()
    } else if (selectedThemeEffect == "Drop Shadow") {
        shadowDx = 3.5f * density
        shadowDy = 4.5f * density
        shadowAlpha = (0.2f * 255).toInt()
    } else if (selectedThemeEffect == "Glossy Reflex") {
        shadowDx = 1f * density
        shadowDy = 1f * density
        shadowAlpha = (0.1f * 255).toInt()
    }
    if (shadowAlpha > 0) {
        shadowPaint.color = android.graphics.Color.argb(shadowAlpha, 0, 0, 0)
        canvas.save()
        canvas.translate(shadowDx, shadowDy)
        canvas.drawRoundRect(destRect, rx, ry, shadowPaint)
        canvas.restore()
    }

    // 2. Draw cells (clip to table border radius)
    canvas.save()
    val tableClipPath = android.graphics.Path().apply {
        addRoundRect(destRect, rx, ry, android.graphics.Path.Direction.CW)
    }
    canvas.clipPath(tableClipPath)

    val borderPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.STROKE
        strokeWidth = borderWidthPx
        color = themeColor
        alpha = (0.6f * 255).toInt()
    }

    for (r in 0 until table.rows) {
        for (c in 0 until table.columns) {
            val cellX = c * cellWidth
            val cellY = r * cellHeight
            val isHeader = table.hasHeaderRow && r == 0

            val customBg = table.cellBgColors["$r,$c"]
            val bgColor = if (customBg != null) {
                try {
                    android.graphics.Color.parseColor(customBg)
                } catch (e: Exception) {
                    android.graphics.Color.WHITE
                }
            } else {
                if (isHeader) {
                    themeColor
                } else if (table.alternateRows && r % 2 == 1) {
                    val alpha = 0.08f
                    val tr = android.graphics.Color.red(themeColor)
                    val tg = android.graphics.Color.green(themeColor)
                    val tb = android.graphics.Color.blue(themeColor)
                    android.graphics.Color.rgb(
                        (tr * alpha + 255 * (1f - alpha)).toInt(),
                        (tg * alpha + 255 * (1f - alpha)).toInt(),
                        (tb * alpha + 255 * (1f - alpha)).toInt()
                    )
                } else {
                    android.graphics.Color.WHITE
                }
            }

            val cellRect = android.graphics.RectF(cellX, cellY, cellX + cellWidth, cellY + cellHeight)
            val bgPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                style = android.graphics.Paint.Style.FILL
                color = bgColor
            }
            canvas.drawRect(cellRect, bgPaint)

            if (borderWidthPx > 0f) {
                canvas.drawRect(cellRect, borderPaint)
            }

            val cellText = table.getCellText(r, c)
            if (cellText.isNotEmpty()) {
                val isBold = table.cellBold["$r,$c"] ?: isHeader
                val isItalic = table.cellItalic["$r,$c"] ?: false
                val isUnderline = table.cellUnderline["$r,$c"] ?: false

                val textColor = if (isHeader && customBg == null) {
                    android.graphics.Color.WHITE
                } else {
                    android.graphics.Color.parseColor("#1E1F22")
                }

                val textPaint = android.text.TextPaint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                    color = textColor
                    textSize = 12f * density
                    typeface = android.graphics.Typeface.create(
                        android.graphics.Typeface.DEFAULT,
                        if (isBold && isItalic) android.graphics.Typeface.BOLD_ITALIC
                        else if (isBold) android.graphics.Typeface.BOLD
                        else if (isItalic) android.graphics.Typeface.ITALIC
                        else android.graphics.Typeface.NORMAL
                    )
                    if (isUnderline) {
                        isUnderlineText = true
                    }
                }

                val padding = 4f * density
                val allowedWidth = maxOf(10f, cellWidth - padding * 2)
                val emojiTf = getEmojiTypeface()
                val spannableText = createEmojiSpannable(cellText, emojiTf)
                val textLayout = android.text.StaticLayout.Builder.obtain(spannableText, 0, spannableText.length, textPaint, allowedWidth.toInt())
                    .setAlignment(android.text.Layout.Alignment.ALIGN_CENTER)
                    .setLineSpacing(0f, 1f)
                    .setIncludePad(false)
                    .build()

                val textHeight = textLayout.height
                val startY = cellY + (cellHeight - textHeight) / 2f
                val startX = cellX + (cellWidth - allowedWidth) / 2f

                canvas.save()
                canvas.translate(startX, startY)
                textLayout.draw(canvas)
                canvas.restore()
            }
        }
    }
    canvas.restore() // restore from tableClipPath

    // 3. Draw theme effect over-effects (unclipped, on table bounds)
    val effectPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
        style = android.graphics.Paint.Style.STROKE
    }
    when (selectedThemeEffect) {
        "Glossy Reflex" -> {
            // Gradient overlay
            val glossPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {
                style = android.graphics.Paint.Style.FILL
            }
            val colors = intArrayOf(
                android.graphics.Color.argb((0.15f * 255).toInt(), 255, 255, 255),
                android.graphics.Color.argb(0, 255, 255, 255),
                android.graphics.Color.argb((0.05f * 255).toInt(), 0, 0, 0)
            )
            val positions = floatArrayOf(0f, 0.5f, 1f)
            glossPaint.shader = android.graphics.LinearGradient(
                0f, 0f, 0f, h,
                colors, positions, android.graphics.Shader.TileMode.CLAMP
            )
            canvas.drawRoundRect(destRect, rx, ry, glossPaint)
            
            // White border
            effectPaint.color = android.graphics.Color.argb((0.4f * 255).toInt(), 255, 255, 255)
            effectPaint.strokeWidth = 1f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
        }
        "Matte Border" -> {
            effectPaint.color = android.graphics.Color.parseColor("#333333")
            effectPaint.strokeWidth = 2.5f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
        }
        "Soft Edges Blurry" -> {
            // Outer border: 4.dp, alpha 0.1f
            effectPaint.color = android.graphics.Color.argb((0.1f * 255).toInt(), 128, 128, 128)
            effectPaint.strokeWidth = 4f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            // Inner border: 2.dp, alpha 0.25f
            effectPaint.color = android.graphics.Color.argb((0.25f * 255).toInt(), 128, 128, 128)
            effectPaint.strokeWidth = 2f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
        }
        "Glow Neon Blue" -> {
            // Outer glow: 4.dp, alpha 0.25f
            effectPaint.color = android.graphics.Color.argb((0.25f * 255).toInt(), 0, 0xF5, 0xFF)
            effectPaint.strokeWidth = 4f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
            // Inner glow: 2.dp, alpha 0.7f
            effectPaint.color = android.graphics.Color.argb((0.7f * 255).toInt(), 0, 0xF5, 0xFF)
            effectPaint.strokeWidth = 2f * density
            canvas.drawRoundRect(destRect, rx, ry, effectPaint)
        }
    }

    canvas.restore()
}

private var cachedEmojiTypeface: android.graphics.Typeface? = null

fun getEmojiTypeface(): android.graphics.Typeface {
    cachedEmojiTypeface?.let { return it }
    val tf = try {
        val file = java.io.File("/system/fonts/NotoColorEmoji.ttf")
        if (file.exists()) {
            android.graphics.Typeface.createFromFile(file)
        } else {
            val file2 = java.io.File("/system/fonts/NotoColorEmojiLegacy.ttf")
            if (file2.exists()) {
                android.graphics.Typeface.createFromFile(file2)
            } else {
                android.graphics.Typeface.DEFAULT
            }
        }
    } catch (e: Exception) {
        android.graphics.Typeface.DEFAULT
    }
    cachedEmojiTypeface = tf
    return tf
}

fun isEmoji(codePoint: Int): Boolean {
    val type = Character.getType(codePoint)
    return type.toByte() == Character.OTHER_SYMBOL || 
           (codePoint in 0x1F300..0x1F9FF) ||
           (codePoint in 0x1F600..0x1F64F) ||
           (codePoint in 0x1F680..0x1F6FF) ||
           (codePoint in 0x2600..0x27BF) ||
           (codePoint in 0x1FA00..0x1FAFF) ||
           (codePoint in 0x1F1E6..0x1F1FF)
}

fun createEmojiSpannable(text: String, emojiTypeface: android.graphics.Typeface): android.text.SpannableString {
    val spannable = android.text.SpannableString(text)
    try {
        val textLength = text.length
        var i = 0
        while (i < textLength) {
            val codePoint = text.codePointAt(i)
            val charCount = Character.charCount(codePoint)
            if (isEmoji(codePoint)) {
                spannable.setSpan(
                    CustomTypefaceSpan(emojiTypeface),
                    i,
                    i + charCount,
                    android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE
                )
            }
            i += charCount
        }
    } catch (e: Exception) {}
    return spannable
}

private fun loadBitmapFromUri(context: android.content.Context, uriStr: String): android.graphics.Bitmap? {
    if (uriStr.isBlank()) return null
    try {
        val options = android.graphics.BitmapFactory.Options().apply {
            inPreferredConfig = android.graphics.Bitmap.Config.ARGB_8888
            inScaled = false
            inPremultiplied = true
        }

        // 1. Check if it's a web URL
        if (uriStr.startsWith("http://") || uriStr.startsWith("https://")) {
            val client = okhttp3.OkHttpClient.Builder()
                .connectTimeout(5, java.util.concurrent.TimeUnit.SECONDS)
                .readTimeout(5, java.util.concurrent.TimeUnit.SECONDS)
                .build()
            val request = okhttp3.Request.Builder().url(uriStr).build()
            client.newCall(request).execute().use { response ->
                if (response.isSuccessful) {
                    response.body?.byteStream()?.use { stream ->
                        return android.graphics.BitmapFactory.decodeStream(stream, null, options)
                    }
                }
            }
        }
        
        // 2. Check if it's an android resource
        if (uriStr.startsWith("android.resource://")) {
            val uri = android.net.Uri.parse(uriStr)
            val parts = uri.pathSegments
            if (parts.isNotEmpty()) {
                val resName = parts.last()
                val defType = if (parts.size >= 2) parts[parts.size - 2] else "drawable"
                val resId = context.resources.getIdentifier(resName, defType, context.packageName)
                if (resId != 0) {
                    val drawable = androidx.core.content.ContextCompat.getDrawable(context, resId)
                    if (drawable != null) {
                        return drawableToBitmap(drawable)
                    }
                }
            }
        }

        // 3. Check if it is a direct file path or file:// URI
        if (uriStr.startsWith("/")) {
            return android.graphics.BitmapFactory.decodeFile(uriStr, options)
        }
        if (uriStr.startsWith("file://")) {
            val path = uriStr.substringAfter("file://")
            return android.graphics.BitmapFactory.decodeFile(path, options)
        }

        // 4. Default: try content resolver
        val uri = android.net.Uri.parse(uriStr)
        context.contentResolver.openInputStream(uri)?.use { stream ->
            return android.graphics.BitmapFactory.decodeStream(stream, null, options)
        }
    } catch (e: Exception) {
        e.printStackTrace()
    }
    return null
}

private fun drawableToBitmap(drawable: android.graphics.drawable.Drawable): android.graphics.Bitmap {
    if (drawable is android.graphics.drawable.BitmapDrawable) {
        if (drawable.bitmap != null) {
            return drawable.bitmap
        }
    }
    val width = if (drawable.intrinsicWidth <= 0) 100 else drawable.intrinsicWidth
    val height = if (drawable.intrinsicHeight <= 0) 100 else drawable.intrinsicHeight
    val bitmap = android.graphics.Bitmap.createBitmap(width, height, android.graphics.Bitmap.Config.ARGB_8888)
    val canvas = android.graphics.Canvas(bitmap)
    drawable.setBounds(0, 0, width, height)
    drawable.draw(canvas)
    return bitmap
}

